local function __bfs_require(name)
    if __BFS_CACHE[name] ~= nil then
        return __BFS_CACHE[name]
    end
    local factory = __BFS_MODULES[name]
    if not factory then
        error("[BFS] module not found in bundle: " .. tostring(name))
    end
    local result = factory(__bfs_require)
    __BFS_CACHE[name] = result
    return result
