__BFS_MODULES["core.cleanup"] = function(require)
--[[
    core/cleanup.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Teardown registry.

    Every module registers its teardown callbacks here. Unloading the suite
    then restores the environment exactly: connections are disconnected,
    overridden globals are put back, instances are destroyed and every
    scheduler task is removed.

    The v11 build overrode `print` at protection level >= 7 and never undid
    it, which meant the executor's own logging was gone for the rest of the
    session. Nothing in this suite overrides a global without registering a
    matching restore.
]]

local Cleanup = {}

Cleanup.__index = Cleanup

function Cleanup.new(logger)
    return setmetatable({
        _entries = {},
        _logger = logger,
        _done = false,
    }, Cleanup)
end

--- Register a teardown callback. `label` is only used for logging.
function Cleanup:onDestroy(label, callback)
    if type(callback) ~= "function" then
        return function() end
    end
    local entry = { label = label or "anonymous", callback = callback, active = true }
    table.insert(self._entries, entry)

    return function()
        entry.active = false
    end
end

--- Register a Roblox connection for automatic disconnection.
function Cleanup:trackConnection(connection, label)
    if not connection then
        return
    end
    self:onDestroy(label or "connection", function()
        pcall(function()
            connection:Disconnect()
        end)
    end)
end

--- Register an instance for destruction on unload.
function Cleanup:trackInstance(instance, label)
    if not instance then
        return
    end
    self:onDestroy(label or "instance", function()
        pcall(function()
            instance:Destroy()
        end)
    end)
end

--- Register a restore for a global that the suite overwrote.
function Cleanup:trackGlobal(name, original)
    self:onDestroy("global:" .. tostring(name), function()
        _G[name] = original
    end)
end

--- Run every teardown callback. Safe to call more than once.
function Cleanup:run()
    if self._done then
        return
    end
    self._done = true

    -- newest first: later registrations usually depend on earlier ones
    for i = #self._entries, 1, -1 do
        local entry = self._entries[i]
        if entry.active then
            entry.active = false
            local ok, err = pcall(entry.callback)
            if not ok and self._logger then
                self._logger:warn("Cleanup failed for %s: %s", entry.label, tostring(err))
            end
        end
    end

    self._entries = {}
end

function Cleanup:count()
    return #self._entries
end

return Cleanup
end

__BFS_MODULES["core.events"] = function(require)
--[[
    core/events.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Minimal, allocation-friendly event bus.

    * on()     -> disconnect handle
    * once()   -> fires a single time
    * off()    -> remove by handle or by (event, callback) pair
    * emit()   -> synchronous dispatch, never errors out on a bad listener
]]

local Events = {}

Events.__index = Events

function Events.new()
    return setmetatable({
        _handlers = {},
        _wildcard = {},
        _muted = false,
    }, Events)
end

--- Register a listener. Returns a function that removes the listener.
function Events:on(eventName, callback)
    if type(eventName) ~= "string" or type(callback) ~= "function" then
        return function() end
    end

    self._handlers[eventName] = self._handlers[eventName] or {}
    local handle = { event = eventName, callback = callback, active = true }
    table.insert(self._handlers[eventName], handle)

    return function()
        handle.active = false
    end
end

--- Register a listener that is removed after its first invocation.
function Events:once(eventName, callback)
    local disconnect
    disconnect = self:on(eventName, function(...)
        disconnect()
        callback(...)
    end)
    return disconnect
end

--- Remove a listener. Pass a handle returned by on(), or (event, callback).
function Events:off(eventName, target)
    if type(target) == "function" then
        local list = self._handlers[eventName]
        if not list then
            return false
        end
        for i = #list, 1, -1 do
            if list[i].callback == target or list[i].active == false then
                table.remove(list, i)
            end
        end
        return true
    end

    if type(target) == "table" then
        target.active = false
        return true
    end

    return false
end

--- Fire an event. Listener errors are swallowed so one bad listener cannot
--- break the emit loop (and therefore the whole suite).
function Events:emit(eventName, ...)
    if self._muted then
        return
    end

    local list = self._handlers[eventName]
    if list then
        -- iterate over a copy: listeners may disconnect themselves
        local snapshot = {}
        for i = 1, #list do
            snapshot[i] = list[i]
        end

        for i = 1, #snapshot do
            local handle = snapshot[i]
            if handle.active then
                pcall(handle.callback, ...)
            end
        end

        -- prune dead handles
        for i = #list, 1, -1 do
            if not list[i].active then
                table.remove(list, i)
            end
        end
    end

    if #self._wildcard > 0 then
        for i = 1, #self._wildcard do
            local handle = self._wildcard[i]
            if handle.active then
                pcall(handle.callback, eventName, ...)
            end
        end
    end
end

--- Listen to every event. Callback receives (eventName, ...).
function Events:onAny(callback)
    if type(callback) ~= "function" then
        return function() end
    end
    local handle = { callback = callback, active = true }
    table.insert(self._wildcard, handle)
    return function()
        handle.active = false
    end
end

--- Temporarily suppress dispatch (used while tearing the suite down).
function Events:muted(shouldMute)
    if shouldMute == nil then
        return self._muted
    end
    self._muted = shouldMute
    return self._muted
end

--- Drop every registered listener.
function Events:clear()
    self._handlers = {}
    self._wildcard = {}
end

--- Number of listeners currently registered for an event.
function Events:count(eventName)
    local list = self._handlers[eventName]
    if not list then
        return 0
    end
    local n = 0
    for i = 1, #list do
        if list[i].active then
            n = n + 1
        end
    end
    return n
end

return Events
end

__BFS_MODULES["core.hotkeys"] = function(require)
--[[
    core/hotkeys.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Keybind registry.

    A bind is a name -> KeyCode pair plus an action. Binds can be rebound
    from the interface, are stored in the settings file, and are ignored
    while the player is typing in chat or a text box.
]]

local Hotkeys = {}

Hotkeys.__index = Hotkeys

function Hotkeys.new(settings, logger)
    local self = setmetatable({
        _settings = settings,
        _logger = logger,
        _binds = {},
        _connection = nil,
        _enabled = true,
    }, Hotkeys)

    return self
end

--- Register a bind.
---   name     identifier, e.g. "toggle_ui"
---   action   function() called when the key is pressed
---   key      optional KeyCode override
function Hotkeys:bind(name, action, key)
    if type(action) ~= "function" then
        return
    end

    self._binds[name] = {
        name = name,
        action = action,
        key = key or Enum.KeyCode.Unknown,
        defaultKey = key or Enum.KeyCode.Unknown,
    }
end

function Hotkeys:unbind(name)
    self._binds[name] = nil
end

function Hotkeys:setKey(name, keyCode)
    local bind = self._binds[name]
    if not bind then
        return false
    end
    bind.key = keyCode
    return true
end

function Hotkeys:getKey(name)
    local bind = self._binds[name]
    return bind and bind.key or nil
end

function Hotkeys:getBind(name)
    return self._binds[name]
end

function Hotkeys:list()
    local out = {}
    for name, bind in pairs(self._binds) do
        out[#out + 1] = {
            name = name,
            key = bind.key,
            action = bind.action,
        }
    end
    table.sort(out, function(a, b)
        return a.name < b.name
    end)
    return out
end

--- True when the player is typing, so a bind must not fire.
function Hotkeys:_isTyping()
    local ok, UserInputService = pcall(function()
        return game:GetService("UserInputService")
    end)
    if not ok then
        return false
    end

    local focused = UserInputService:GetFocusedTextBox()
    if focused then
        return true
    end

    -- chat window
    local okChat, chat = pcall(function()
        return game:GetService("Chat")
    end)
    if okChat and chat then
        local okVisible, visible = pcall(function()
            return chat.Visible
        end)
        if okVisible and visible then
            local okFocused, isFocused = pcall(function()
                return chat:IsFocused()
            end)
            if okFocused and isFocused then
                return true
            end
        end
    end

    return false
end

function Hotkeys:start()
    if self._connection then
        return
    end

    local ok, UserInputService = pcall(function()
        return game:GetService("UserInputService")
    end)
    if not ok then
        return
    end

    self._connection = UserInputService.InputBegan:Connect(function(input, processed)
        if processed then
            return
        end
        if not self._enabled then
            return
        end
        if input.UserInputType ~= Enum.UserInputType.Keyboard then
            return
        end
        if self:_isTyping() then
            return
        end

        for _, bind in pairs(self._binds) do
            if bind.key ~= Enum.KeyCode.Unknown and bind.key == input.KeyCode then
                pcall(bind.action, bind)
            end
        end
    end)
end

function Hotkeys:stop()
    if self._connection then
        pcall(function()
            self._connection:Disconnect()
        end)
        self._connection = nil
    end
end

function Hotkeys:setEnabled(enabled)
    self._enabled = enabled and true or false
end

function Hotkeys:isEnabled()
    return self._enabled
end

--- Name of a KeyCode, e.g. "RightShift" -> "RIGHT SHIFT".
function Hotkeys:keyName(keyCode)
    if not keyCode then
        return "None"
    end
    local raw = tostring(keyCode):match("KeyCode%.(.+)")
    if not raw then
        return "None"
    end
    return (raw:gsub("(%l)(%u)", "%1 %2"):upper())
end

return Hotkeys
end

__BFS_MODULES["core"] = function(require)
--[[
    core/init.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Suite root. Owns the shared services and the module lifecycle.

        local Suite = require("core")
        local suite = Suite.new()
        suite:Register("luck", require("luck"))
        suite:Start()
]]

local Logger = require("core.logger")
local Settings = require("core.settings")
local Scheduler = require("core.scheduler")
local Hotkeys = require("core.hotkeys")
local Events = require("core.events")
local Cleanup = require("core.cleanup")
local Util = require("core.util")

local Suite = {}

Suite.__index = Suite
Suite.Version = "12.0.0"
Suite.Name = "BLOX FRUITS SUITE"

function Suite.new(options)
    options = options or {}

    local logger = options.logger or Logger.new({
        prefix = "[BFS]",
        level = Logger.LEVELS.INFO,
    })

    local settings = options.settings or Settings.new({ logger = logger })

    local self = setmetatable({
        _logger = logger,
        _settings = settings,
        _scheduler = Scheduler.new(logger),
        _hotkeys = Hotkeys.new(settings, logger),
        _events = Events.new(),
        _cleanup = Cleanup.new(logger),
        _modules = {},
        _moduleOrder = {},
        _started = false,
        _startTime = os.time(),
        _uptime = 0,
    }, Suite)

    return self
end

function Suite:logger()
    return self._logger
end

function Suite:settings()
    return self._settings
end

function Suite:state()
    return self._settings:store()
end

function Suite:events()
    return self._events
end

function Suite:scheduler()
    return self._scheduler
end

function Suite:hotkeys()
    return self._hotkeys
end

function Suite:cleanup()
    return self._cleanup
end

--- Register a module. A module is a table with optional
--- Start(suite) / Stop(suite) / Name fields.
function Suite:Register(name, module)
    if type(module) ~= "table" then
        self._logger:warn("Cannot register module '%s': not a table", tostring(name))
        return false
    end

    self._modules[name] = module
    table.insert(self._moduleOrder, name)
    return true
end

function Suite:Get(name)
    return self._modules[name]
end

function Suite:ModuleNames()
    local out = {}
    for i = 1, #self._moduleOrder do
        out[i] = self._moduleOrder[i]
    end
    return out
end

--- Start the suite: settings, scheduler, hotkeys and every module.
function Suite:Start()
    if self._started then
        return false
    end
    self._started = true
    self._startTime = os.time()

    self._logger:info("==========================================")
    self._logger:info("%s v%s", Suite.Name, Suite.Version)
    self._logger:info("==========================================")

    self._settings:load()
    self._logger:info("Settings loaded (persistent: %s)", tostring(self._settings:isPersistent()))

    self._scheduler:start()
    self._hotkeys:start()

    for i = 1, #self._moduleOrder do
        local name = self._moduleOrder[i]
        local module = self._modules[name]
        if type(module.Start) == "function" then
            -- the module is the receiver, the suite is the argument
            local ok, err = pcall(module.Start, module, self)
            if ok then
                self._logger:info("Module '%s' started", name)
            else
                self._logger:error("Module '%s' failed to start: %s", name, tostring(err))
            end
        end
    end

    self._events:emit("suite.started", self)
    return true
end

--- Stop the suite and restore the environment.
function Suite:Stop()
    if not self._started then
        return false
    end
    self._started = false

    for i = #self._moduleOrder, 1, -1 do
        local name = self._moduleOrder[i]
        local module = self._modules[name]
        if type(module.Stop) == "function" then
            local ok, err = pcall(module.Stop, module, self)
            if not ok then
                self._logger:warn("Module '%s' failed to stop cleanly: %s", name, tostring(err))
            end
        end
    end

    self._scheduler:stop()
    self._hotkeys:stop()
    self._cleanup:run()
    self._events:emit("suite.stopped", self)

    self._logger:info("Suite stopped, environment restored")
    return true
end

function Suite:IsRunning()
    return self._started
end

function Suite:Uptime()
    return os.time() - self._startTime
end

--- Aggregate statistics for the dashboard.
function Suite:Snapshot()
    return {
        version = Suite.Version,
        uptime = self:Uptime(),
        modules = #self._moduleOrder,
        tasks = #self._scheduler._tasks,
        bindings = #self._hotkeys:list(),
        persistent = self._settings:isPersistent(),
    }
end

return Suite
end

__BFS_MODULES["core.json"] = function(require)
--[[
    core/json.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Dependency-free JSON encoder / decoder.

    Why not HttpService? Because HttpService:JSONDecode is unavailable inside
    some executor sandboxes and it silently rejects untrusted payloads. This
    implementation is pure Lua, has no Roblox dependencies and can round-trip
    the settings file the suite writes to disk.
]]

local Json = {}

-- ═══════════════════════════════════════════════════════════════════════
-- ENCODING
-- ═══════════════════════════════════════════════════════════════════════

local ESCAPE_MAP = {
    ['"'] = '\\"',
    ["\\"] = "\\\\",
    ["\b"] = "\\b",
    ["\f"] = "\\f",
    ["\n"] = "\\n",
    ["\r"] = "\\r",
    ["\t"] = "\\t",
}

local function escapeString(str)
    return (str:gsub('[%c"\\]', function(char)
        return ESCAPE_MAP[char] or string.format("\\u%04x", char:byte())
    end))
end

local function encodeValue(value, pretty, indent, depth)
    depth = depth or 0

    local valueType = type(value)

    if value == nil then
        return "null"
    elseif valueType == "boolean" then
        return tostring(value)
    elseif valueType == "number" then
        if value ~= value or value == math.huge or value == -math.huge then
            return "null"
        end
        if value == math.floor(value) and math.abs(value) < 1e15 then
            return string.format("%d", value)
        end
        return string.format("%.14g", value)
    elseif valueType == "string" then
        return '"' .. escapeString(value) .. '"'
    elseif valueType == "table" then
        local isArray = Json.isArray(value)
        local newIndent = indent .. "  "
        local pieces = {}
        local separator = pretty and (",\n" .. newIndent) or ","

        if isArray then
            for i = 1, #value do
                pieces[#pieces + 1] = encodeValue(value[i], pretty, newIndent, depth + 1)
            end
            if #pieces == 0 then
                return "[]"
            end
            local open = pretty and "[\n" .. newIndent or "["
            local close = pretty and "\n" .. indent .. "]" or "]"
            return open .. table.concat(pieces, separator) .. close
        end

        -- object: keys are sorted so the output is stable between runs
        local keys = {}
        for key in pairs(value) do
            keys[#keys + 1] = key
        end
        table.sort(keys, function(a, b)
            return tostring(a) < tostring(b)
        end)

        for _, key in ipairs(keys) do
            local keyType = type(key)
            if keyType == "string" or keyType == "number" then
                pieces[#pieces + 1] = '"' .. escapeString(tostring(key)) .. '": '
                    .. encodeValue(value[key], pretty, newIndent, depth + 1)
            end
        end
        if #pieces == 0 then
            return "{}"
        end
        local open = pretty and "{\n" .. newIndent or "{"
        local close = pretty and "\n" .. indent .. "}" or "}"
        return open .. table.concat(pieces, separator) .. close
    end

    return "null"
end

--- Encode a Lua value as JSON. `pretty` (boolean) enables indentation.
function Json.encode(value, pretty)
    return encodeValue(value, pretty and true or false, "", 0)
end

-- ═══════════════════════════════════════════════════════════════════════
-- DECODING
-- ═══════════════════════════════════════════════════════════════════════

local Parser = {}
Parser.__index = Parser

local function newParser(text)
    return setmetatable({
        text = text,
        pos = 1,
        len = #text,
    }, Parser)
end

function Parser:error(message)
    error(string.format("JSON error at position %d: %s", self.pos, message), 0)
end

function Parser:skipWhitespace()
    while self.pos <= self.len do
        local char = self.text:sub(self.pos, self.pos)
        if char == " " or char == "\t" or char == "\n" or char == "\r" then
            self.pos = self.pos + 1
        else
            break
        end
    end
end

function Parser:peek()
    return self.text:sub(self.pos, self.pos)
end

function Parser:expect(char)
    if self:peek() ~= char then
        self:error("expected '" .. char .. "' but found '" .. self:peek() .. "'")
    end
    self.pos = self.pos + 1
end

local UNESCAPES = {
    ['"'] = '"',
    ["\\"] = "\\",
    ["/"] = "/",
    ["b"] = "\b",
    ["f"] = "\f",
    ["n"] = "\n",
    ["r"] = "\r",
    ["t"] = "\t",
}

function Parser:parseString()
    self:expect('"')
    local buffer = {}

    while true do
        if self.pos > self.len then
            self:error("unterminated string")
        end

        local char = self.text:sub(self.pos, self.pos)

        if char == '"' then
            self.pos = self.pos + 1
            break
        elseif char == "\\" then
            self.pos = self.pos + 1
            local escape = self.text:sub(self.pos, self.pos)
            if escape == "u" then
                local hex = self.text:sub(self.pos + 1, self.pos + 4)
                local code = tonumber(hex, 16) or 63
                buffer[#buffer + 1] = utf8 and utf8.char(code) or string.char(code)
                self.pos = self.pos + 5
            else
                buffer[#buffer + 1] = UNESCAPES[escape] or escape
                self.pos = self.pos + 1
            end
        else
            buffer[#buffer + 1] = char
            self.pos = self.pos + 1
        end
    end

    return table.concat(buffer)
end

function Parser:parseNumber()
    local start = self.pos
    local pattern = "^%-?%d+%.?%d*[eE]?[%+%-]?%d*"
    local literal = self.text:match(pattern, self.pos)
    if not literal or literal == "" then
        self:error("invalid number")
    end
    self.pos = start + #literal
    return tonumber(literal)
end

function Parser:parseValue()
    self:skipWhitespace()
    local char = self:peek()

    if char == "" then
        self:error("unexpected end of input")
    elseif char == '"' then
        return self:parseString()
    elseif char == "{" then
        return self:parseObject()
    elseif char == "[" then
        return self:parseArray()
    elseif char == "t" then
        if self.text:sub(self.pos, self.pos + 3) ~= "true" then
            self:error("invalid literal")
        end
        self.pos = self.pos + 4
        return true
    elseif char == "f" then
        if self.text:sub(self.pos, self.pos + 4) ~= "false" then
            self:error("invalid literal")
        end
        self.pos = self.pos + 5
        return false
    elseif char == "n" then
        if self.text:sub(self.pos, self.pos + 3) ~= "null" then
            self:error("invalid literal")
        end
        self.pos = self.pos + 4
        return nil
    end

    return self:parseNumber()
end

function Parser:parseObject()
    self:expect("{")
    local out = {}

    self:skipWhitespace()
    if self:peek() == "}" then
        self.pos = self.pos + 1
        return out
    end

    while true do
        self:skipWhitespace()
        local key = self:parseString()
        self:skipWhitespace()
        self:expect(":")
        out[key] = self:parseValue()
        self:skipWhitespace()

        local char = self:peek()
        if char == "," then
            self.pos = self.pos + 1
        elseif char == "}" then
            self.pos = self.pos + 1
            break
        else
            self:error("expected ',' or '}'")
        end
    end

    return out
end

function Parser:parseArray()
    self:expect("[")
    local out = {}

    self:skipWhitespace()
    if self:peek() == "]" then
        self.pos = self.pos + 1
        return out
    end

    while true do
        out[#out + 1] = self:parseValue()
        self:skipWhitespace()

        local char = self:peek()
        if char == "," then
            self.pos = self.pos + 1
        elseif char == "]" then
            self.pos = self.pos + 1
            break
        else
            self:error("expected ',' or ']'")
        end
    end

    return out
end

--- Decode a JSON string. Returns (value, nil) or (nil, errorMessage).
function Json.decode(text)
    if type(text) ~= "string" then
        return nil, "input is not a string"
    end

    local parser = newParser(text)
    local ok, result = pcall(function()
        local value = parser:parseValue()
        parser:skipWhitespace()
        if parser.pos <= parser.len then
            parser:error("trailing garbage")
        end
        return value
    end)

    if not ok then
        return nil, tostring(result)
    end
    return result, nil
end

-- ═══════════════════════════════════════════════════════════════════════
-- HELPERS
-- ═══════════════════════════════════════════════════════════════════════

--- True when the table is a dense array (1..n).
function Json.isArray(tbl)
    if type(tbl) ~= "table" then
        return false
    end
    local count = 0
    for key in pairs(tbl) do
        if type(key) ~= "number" then
            return false
        end
        if key < 1 or key ~= math.floor(key) then
            return false
        end
        count = count + 1
    end
    return count == #tbl
end

return Json
end

__BFS_MODULES["core.logger"] = function(require)
--[[
    core/logger.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Levelled logger with optional file sink.

    The v11 build silenced `print` wholesale at protection level >= 7, which
    also killed the script's own output. This logger never touches the global
    `print`; it only writes when a level is enabled.
]]

local Logger = {}

Logger.__index = Logger

Logger.LEVELS = {
    TRACE = 0,
    DEBUG = 1,
    INFO = 2,
    WARN = 3,
    ERROR = 4,
    NONE = 5,
}

-- Keyed by the level value, not by position. The levels start at 0 and
-- Lua tables are 1 based, so an array here would shift every name by one
-- and report a warning as an info.
local LEVEL_NAMES = {
    [Logger.LEVELS.TRACE] = "TRACE",
    [Logger.LEVELS.DEBUG] = "DEBUG",
    [Logger.LEVELS.INFO] = "INFO",
    [Logger.LEVELS.WARN] = "WARN",
    [Logger.LEVELS.ERROR] = "ERROR",
}

function Logger.new(config)
    config = config or {}

    local self = setmetatable({
        _level = config.level or Logger.LEVELS.INFO,
        _prefix = config.prefix or "[BFS]",
        _file = config.file or nil,
        _fileEnabled = config.fileEnabled or false,
        _history = {},
        _maxHistory = config.maxHistory or 200,
        _echo = config.echo ~= false,
    }, Logger)

    return self
end

function Logger:setLevel(level)
    if type(level) == "number" then
        self._level = level
    elseif type(level) == "string" then
        self._level = Logger.LEVELS[string.upper(level)] or self._level
    end
    return self._level
end

function Logger:getLevel()
    return self._level
end

function Logger:setPrefix(prefix)
    self._prefix = prefix or self._prefix
end

function Logger:enableFile(enabled, path)
    self._fileEnabled = enabled and true or false
    if path then
        self._file = path
    end
end

function Logger:_writeLine(line)
    self._history[#self._history + 1] = line
    if #self._history > self._maxHistory then
        table.remove(self._history, 1)
    end

    if self._fileEnabled and self._file then
        pcall(function()
            local handle = io.open(self._file, "a")
            if handle then
                handle:write(line .. "\n")
                handle:close()
            end
        end)
    end
end

function Logger:log(level, message, ...)
    if level < self._level then
        return
    end

    if type(message) == "string" and select("#", ...) > 0 then
        local ok, formatted = pcall(string.format, message, ...)
        if ok then
            message = formatted
        end
    end

    message = tostring(message)
    local name = LEVEL_NAMES[level] or "INFO"
    local line = string.format("%s [%s] %s", self._prefix, name, message)

    if self._echo then
        pcall(print, line)
    end

    self:_writeLine(line)
end

function Logger:trace(message, ...)
    self:log(Logger.LEVELS.TRACE, message, ...)
end

function Logger:debug(message, ...)
    self:log(Logger.LEVELS.DEBUG, message, ...)
end

function Logger:info(message, ...)
    self:log(Logger.LEVELS.INFO, message, ...)
end

function Logger:warn(message, ...)
    self:log(Logger.LEVELS.WARN, message, ...)
end

function Logger:error(message, ...)
    self:log(Logger.LEVELS.ERROR, message, ...)
end

--- Recent log lines, newest last.
function Logger:history(limit)
    local out = {}
    local count = #self._history
    local from = math.max(1, count - (limit or 50) + 1)
    for i = from, count do
        out[#out + 1] = self._history[i]
    end
    return out
end

function Logger:clear()
    self._history = {}
end

return Logger
end

__BFS_MODULES["core.scheduler"] = function(require)
--[[
    core/scheduler.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    One Heartbeat connection drives every recurring task in the suite.

    v11 used `spawn(function() while true do wait(0.5) ... end end)` in a
    dozen places, which cannot be stopped and keeps running after the
    interface is destroyed. This scheduler can be paused, torn down and
    inspected.
]]

local Scheduler = {}

Scheduler.__index = Scheduler

function Scheduler.new(logger)
    return setmetatable({
        _tasks = {},
        _running = false,
        _paused = false,
        _logger = logger,
        _connection = nil,
        _lastRun = {},
        _frame = 0,
    }, Scheduler)
end

function Scheduler:start()
    if self._running then
        return
    end

    local ok, RunService = pcall(function()
        return game:GetService("RunService")
    end)
    if not ok then
        return
    end

    self._running = true
    self._connection = RunService.Heartbeat:Connect(function(deltaTime)
        self:tick(deltaTime)
    end)
end

function Scheduler:tick(deltaTime)
    self._frame = self._frame + 1
    if self._paused then
        return
    end

    local now = os.clock()
    for name, task in pairs(self._tasks) do
        if task.active then
            if task.interval then
                local last = self._lastRun[name] or 0
                if now - last >= task.interval then
                    self._lastRun[name] = now
                    pcall(task.callback, deltaTime)
                end
            else
                -- frame task
                pcall(task.callback, deltaTime)
            end
        end
    end
end

--- Register a recurring task.
---   name     unique identifier
---   interval seconds between runs (nil = every frame)
---   callback function(deltaTime)
function Scheduler:every(name, interval, callback)
    if type(callback) ~= "function" then
        return function() end
    end

    self._tasks[name] = {
        interval = interval,
        callback = callback,
        active = true,
    }
    self._lastRun[name] = 0

    return function()
        self:remove(name)
    end
end

--- Run a task on every frame.
function Scheduler:frame(name, callback)
    return self:every(name, nil, callback)
end

--- Run a task once, after `delay` seconds.
function Scheduler:after(name, delay, callback)
    if type(callback) ~= "function" then
        return
    end
    task.delay(delay or 0, function()
        self:remove(name)
        pcall(callback)
    end)
end

--- Remove a task by name.
function Scheduler:remove(name)
    if self._tasks[name] then
        self._tasks[name].active = false
        self._tasks[name] = nil
        self._lastRun[name] = nil
        return true
    end
    return false
end

function Scheduler:has(name)
    return self._tasks[name] ~= nil
end

function Scheduler:pause()
    self._paused = true
end

function Scheduler:resume()
    self._paused = false
end

function Scheduler:isPaused()
    return self._paused
end

function Scheduler:frameCount()
    return self._frame
end

--- Stop every task and drop the Heartbeat connection.
function Scheduler:stop()
    self._tasks = {}
    self._lastRun = {}
    if self._connection then
        pcall(function()
            self._connection:Disconnect()
        end)
        self._connection = nil
    end
    self._running = false
end

return Scheduler
end

__BFS_MODULES["core.settings"] = function(require)
--[[
    core/settings.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Persistence layer.

    On a real executor the suite writes a JSON file next to the script
    (`bfs_settings.json`). When no file API is available (Studio sandbox,
    stripped executor) the settings live in memory for the session and the
    UI clearly reports that persistence is unavailable.

    v11 shipped a `config/settings.json` that was never read by any code --
    the toggles silently did nothing. Everything here is wired to the live
    store, so a value that is visible in the UI is a value that is honoured.
]]

local Json = require("core.json")
local Util = require("core.util")

local Settings = {}

Settings.__index = Settings

local FILE_NAME = "bfs_settings.json"

-- Every setting the suite understands, with its default and a short
-- description. The UI builds itself from this table, so adding a setting
-- here automatically exposes it.
Settings.SCHEMA = {
    general = {
        keybind = { type = "key", default = Enum.KeyCode.RightShift, desc = "Toggle the interface" },
        minimizeOnDeath = { type = "bool", default = true, desc = "Hide the interface when the character dies" },
        minimizeKey = { type = "key", default = Enum.KeyCode.End, desc = "Minimise the interface" },
        theme = { type = "string", default = "midnight", desc = "Interface theme" },
        transparency = { type = "number", default = 0, min = 0, max = 90, desc = "Interface transparency" },
        accent = { type = "string", default = "cyan", desc = "Accent colour" },
        notifications = { type = "bool", default = true, desc = "Show toast notifications" },
        sounds = { type = "bool", default = false, desc = "Play UI sounds" },
        logLevel = { type = "string", default = "INFO", desc = "Console verbosity" },
        saveOnChange = { type = "bool", default = true, desc = "Save settings automatically" },
    },
    luck = {
        enabled = { type = "bool", default = true, desc = "Enable the luck engine" },
        multiplier = { type = "number", default = 2.0, min = 1, max = 10, step = 0.5, desc = "Luck multiplier" },
        luckyFruitOnly = { type = "bool", default = true, desc = "Restrict to selected fruits" },
        targetRarities = { type = "list", default = { "Legendary", "Mythic" }, desc = "Target rarities" },
        rollHistorySize = { type = "number", default = 50, min = 10, max = 500, step = 10, desc = "Roll history size" },
        autoTrackSpawns = { type = "bool", default = true, desc = "Observe real fruit spawns" },
        trackGacha = { type = "bool", default = true, desc = "Observe real gacha results" },
        useClientRoll = { type = "bool", default = false, desc = "Bias client-side rolls (cosmetic only)" },
    },
    world = {
        fruitESP = { type = "bool", default = true, desc = "Highlight fruit spawns" },
        fruitESPLabel = { type = "bool", default = true, desc = "Show fruit name label" },
        fruitESPDistance = { type = "bool", default = true, desc = "Show distance label" },
        mobESP = { type = "bool", default = false, desc = "Highlight mobs" },
        mobESPLabel = { type = "bool", default = true, desc = "Show mob name and level" },
        chestESP = { type = "bool", default = false, desc = "Highlight chests" },
        npcESP = { type = "bool", default = false, desc = "Highlight NPCs" },
        bossESP = { type = "bool", default = true, desc = "Highlight bosses" },
        maxESP = { type = "number", default = 150, min = 25, max = 500, step = 25, desc = "Maximum ESP objects" },
        scanRadius = { type = "number", default = 1500, min = 200, max = 5000, step = 100, desc = "Scan radius (studs)" },
    },
    farm = {
        autoFarm = { type = "bool", default = false, desc = "Enable auto farming" },
        autoCollect = { type = "bool", default = false, desc = "Collect fruit automatically" },
        autoQuest = { type = "bool", default = false, desc = "Run quests automatically" },
        targetLevel = { type = "number", default = 0, min = 0, max = 3000, step = 10, desc = "Target mob level" },
        attackRange = { type = "number", default = 12, min = 3, max = 60, step = 1, desc = "Attack range (studs)" },
        teleportSmoothing = { type = "number", default = 0, min = 0, max = 100, step = 5, desc = "Teleport smoothing" },
        safeMode = { type = "bool", default = true, desc = "Stop when the character is low" },
        safeHealth = { type = "number", default = 30, min = 0, max = 100, step = 5, desc = "Stop at health %" },
    },
    ui = {
        tabWidth = { type = "number", default = 128, min = 90, max = 200, step = 2, desc = "Tab width" },
        windowWidth = { type = "number", default = 560, min = 420, max = 900, step = 20, desc = "Window width" },
        windowHeight = { type = "number", default = 480, min = 320, max = 800, step = 20, desc = "Window height" },
        showFps = { type = "bool", default = true, desc = "Show the performance counter" },
        animations = { type = "bool", default = true, desc = "Enable animations" },
    },
}

--- Build a nested defaults table from the flat schema.
local function buildDefaults()
    local defaults = {}
    for group, entries in pairs(Settings.SCHEMA) do
        defaults[group] = {}
        for key, definition in pairs(entries) do
            defaults[group][key] = Util.deepCopy(definition.default)
        end
    end
    return defaults
end

function Settings.new(options)
    options = options or {}

    return setmetatable({
        _store = require("core.state").new(buildDefaults()),
        _logger = options.logger,
        _fileName = options.fileName or FILE_NAME,
        _persistent = false,
        _lastSave = 0,
        _saveInterval = 2.0,
    }, Settings)
end

function Settings:store()
    return self._store
end

--- Read a setting, e.g. `get("luck.multiplier")`.
function Settings:get(path, fallback)
    return self._store:get(path, fallback)
end

--- Write a setting. Persists immediately when `general.saveOnChange` is on.
function Settings:set(path, value)
    self._store:set(path, value)
    if self:get("general.saveOnChange", true) then
        self:save(true)
    end
    return value
end

function Settings:onChange(path, callback)
    return self._store:onChange(path, callback)
end

function Settings:defaults()
    return buildDefaults()
end

function Settings:reset()
    self._store:replace(buildDefaults())
    self:save(true)
end

-- ═══════════════════════════════════════════════════════════════════════
-- FILE ACCESS (executor-only, degrades gracefully)
-- ═══════════════════════════════════════════════════════════════════════

function Settings:_canWrite()
    return type(writefile) == "function" and type(isfile) == "function"
end

function Settings:_canRead()
    return type(readfile) == "function" and type(isfile) == "function"
end

--- Load settings from disk. Returns true when a file was read.
function Settings:load()
    if not self:_canRead() then
        self._persistent = false
        return false
    end

    local ok, exists = pcall(function()
        return isfile(self._fileName)
    end)
    if not ok or not exists then
        self._persistent = true
        return false
    end

    local okRead, raw = pcall(function()
        return readfile(self._fileName)
    end)
    if not okRead or type(raw) ~= "string" then
        return false
    end

    local decoded, err = Json.decode(raw)
    if not decoded then
        if self._logger then
            self._logger:warn("Settings file is corrupt (%s), using defaults", tostring(err))
        end
        return false
    end

    self._store:merge(decoded)
    self._persistent = true
    return true
end

--- Write settings to disk. `silent` suppresses the "saved" toast.
function Settings:save(silent)
    if not self:_canWrite() then
        self._persistent = false
        return false
    end

    local payload = Json.encode(self._store:snapshot(), true)
    local ok = pcall(function()
        writefile(self._fileName, payload)
    end)

    self._persistent = ok
    self._lastSave = os.clock()

    if ok and not silent and self._logger then
        self._logger:debug("Settings written to %s", self._fileName)
    end
    return ok
end

function Settings:isPersistent()
    return self._persistent
end

function Settings:fileName()
    return self._fileName
end

--- Restore defaults and wipe the file.
function Settings:clear()
    self._store:replace(buildDefaults())
    if self:_canWrite() then
        pcall(function()
            if isfile(self._fileName) then
                delfile(self._fileName)
            end
        end)
    end
end

return Settings
end

__BFS_MODULES["core.state"] = function(require)
--[[
    core/state.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Reactive key/value store.

    Every module reads configuration through this store instead of keeping
    its own copies, so a change in the UI is instantly visible everywhere
    and the settings file is a straight serialisation of the store.

        local State = require("core.state")
        State:set("luck.multiplier", 3)
        State:get("luck.multiplier")        --> 3
        State:onChange("luck.multiplier", function(value, old) ... end)
]]

local Util = require("core.util")

local State = {}

State.__index = State

function State.new(defaults)
    return setmetatable({
        _values = Util.deepCopy(defaults or {}),
        _subscribers = {},
    }, State)
end

--- Read a value using a dotted path ("luck.multiplier").
function State:get(path, fallback)
    local value = Util.pathGet(self._values, path)
    if value == nil then
        return fallback
    end
    return value
end

--- Write a value using a dotted path. Returns the stored value.
function State:set(path, value)
    local old = Util.pathGet(self._values, path)
    if old == value then
        return value
    end

    Util.pathSet(self._values, path, value)
    self:_notify(path, value, old)
    return value
end

--- Toggle a boolean path.
function State:toggle(path)
    local newValue = not self:get(path, false)
    self:set(path, newValue)
    return newValue
end

--- Increment a numeric path.
function State:increment(path, amount)
    local newValue = (self:get(path, 0) or 0) + (amount or 1)
    self:set(path, newValue)
    return newValue
end

--- Subscribe to a path. A path of "*" listens to every change.
--- Returns a disconnect function.
function State:onChange(path, callback)
    if type(callback) ~= "function" then
        return function() end
    end

    self._subscribers[path] = self._subscribers[path] or {}
    local handle = { path = path, callback = callback, active = true }
    table.insert(self._subscribers[path], handle)

    return function()
        handle.active = false
    end
end

function State:_notify(path, value, old)
    local exact = self._subscribers[path]
    if exact then
        for i = 1, #exact do
            if exact[i].active then
                pcall(exact[i].callback, value, old, path)
            end
        end
    end

    -- parent paths also fire, e.g. setting "luck.multiplier" notifies "luck"
    local parent = path:match("^(.*)%.[^%.]+$")
    while parent do
        local list = self._subscribers[parent]
        if list then
            for i = 1, #list do
                if list[i].active then
                    pcall(list[i].callback, Util.pathGet(self._values, parent), old, parent)
                end
            end
        end
        parent = parent:match("^(.*)%.[^%.]+$")
    end

    local wildcards = self._subscribers["*"]
    if wildcards then
        for i = 1, #wildcards do
            if wildcards[i].active then
                pcall(wildcards[i].callback, value, old, path)
            end
        end
    end
end

--- Snapshot of the whole store (a deep copy).
function State:snapshot()
    return Util.deepCopy(self._values)
end

--- Replace the whole store. `merge` keeps existing keys that are absent
--- from the new table.
function State:replace(values, merge)
    if merge then
        Util.deepMerge(self._values, values)
    else
        self._values = Util.deepCopy(values or {})
    end
    self:_notify("*", self._values, nil)
    return self._values
end

--- Merge a table into the store path by path.
function State:merge(values)
    for key, value in pairs(values or {}) do
        self:set(key, value)
    end
end

function State:clearSubscribers()
    self._subscribers = {}
end

return State
end

__BFS_MODULES["core.util"] = function(require)
--[[
    core/util.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Shared helper library. Pure functions only -- no state, no side effects
    beyond the ones explicitly documented.

    This module is intentionally dependency-free so it can be required from
    anywhere in the suite without ordering concerns.
]]

local Util = {}

-- ═══════════════════════════════════════════════════════════════════════
-- NUMBERS
-- ═══════════════════════════════════════════════════════════════════════

function Util.clamp(value, minimum, maximum)
    if value < minimum then
        return minimum
    elseif value > maximum then
        return maximum
    end
    return value
end

function Util.clamp01(value)
    return Util.clamp(value, 0, 1)
end

function Util.lerp(a, b, t)
    return a + (b - a) * Util.clamp01(t)
end

--- Round to a fixed number of decimals.
function Util.round(value, decimals)
    local mult = 10 ^ (decimals or 0)
    return math.floor(value * mult + 0.5) / mult
end

function Util.roundTo(value, step)
    if not step or step == 0 then
        return value
    end
    return math.floor(value / step + 0.5) * step
end

function Util.sign(value)
    if value > 0 then
        return 1
    elseif value < 0 then
        return -1
    end
    return 0
end

-- ═══════════════════════════════════════════════════════════════════════
-- TABLES
-- ═══════════════════════════════════════════════════════════════════════

function Util.tableCount(tbl)
    local n = 0
    for _ in pairs(tbl) do
        n = n + 1
    end
    return n
end

function Util.tableKeys(tbl)
    local out = {}
    for key in pairs(tbl) do
        out[#out + 1] = key
    end
    return out
end

function Util.tableValues(tbl)
    local out = {}
    for _, value in pairs(tbl) do
        out[#out + 1] = value
    end
    return out
end

--- Shallow copy (array part included).
function Util.tableCopy(tbl)
    local out = {}
    for key, value in pairs(tbl) do
        out[key] = value
    end
    return out
end

function Util.deepCopy(tbl)
    if type(tbl) ~= "table" then
        return tbl
    end
    local out = {}
    for key, value in pairs(tbl) do
        out[key] = Util.deepCopy(value)
    end
    return out
end

function Util.tableMap(tbl, fn)
    local out = {}
    for i, value in ipairs(tbl) do
        out[i] = fn(value, i)
    end
    return out
end

function Util.tableFilter(tbl, predicate)
    local out = {}
    for i, value in ipairs(tbl) do
        if predicate(value, i) then
            out[#out + 1] = value
        end
    end
    return out
end

function Util.tableFind(tbl, predicate)
    for i, value in ipairs(tbl) do
        if predicate(value, i) then
            return value, i
        end
    end
    return nil
end

function Util.tableFindKey(tbl, value)
    for key, candidate in pairs(tbl) do
        if candidate == value then
            return key
        end
    end
    return nil
end

--- Recursively merge `source` into `target` (in place) and return target.
function Util.deepMerge(target, source)
    for key, value in pairs(source) do
        if type(value) == "table" and type(target[key]) == "table" then
            Util.deepMerge(target[key], value)
        else
            target[key] = value
        end
    end
    return target
end

--- Remove nil holes from an array and return the compacted copy.
function Util.compact(tbl)
    local out = {}
    for _, value in ipairs(tbl) do
        if value ~= nil then
            out[#out + 1] = value
        end
    end
    return out
end

function Util.slice(tbl, from, to)
    local out = {}
    for i = from, to do
        out[#out + 1] = tbl[i]
    end
    return out
end

function Util.reverse(tbl)
    local out = {}
    for i = #tbl, 1, -1 do
        out[#out + 1] = tbl[i]
    end
    return out
end

-- ═══════════════════════════════════════════════════════════════════════
-- STRINGS
-- ═══════════════════════════════════════════════════════════════════════

function Util.trim(str)
    if type(str) ~= "string" then
        return ""
    end
    return (str:gsub("^%s+", ""):gsub("%s+$", ""))
end

function Util.startsWith(str, prefix)
    return type(str) == "string" and str:sub(1, #prefix) == prefix
end

function Util.endsWith(str, suffix)
    if type(str) ~= "string" then
        return false
    end
    return suffix == "" or str:sub(-#suffix) == suffix
end

function Util.contains(str, needle, caseInsensitive)
    if type(str) ~= "string" then
        return false
    end
    if caseInsensitive then
        return str:lower():find(needle:lower()) ~= nil
    end
    return str:find(needle) ~= nil
end

function Util.titleCase(str)
    return (str:gsub("(%a)([%w']*)", function(first, rest)
        return first:upper() .. rest:lower()
    end))
end

-- ═══════════════════════════════════════════════════════════════════════
-- PATHS  ("a.b.c" -> nested table access)
-- ═══════════════════════════════════════════════════════════════════════

function Util.pathGet(root, path)
    local node = root
    for segment in string.gmatch(path, "[^%.]+") do
        if type(node) ~= "table" then
            return nil
        end
        node = node[segment]
        if node == nil then
            return nil
        end
    end
    return node
end

function Util.pathSet(root, path, value)
    local segments = {}
    for segment in string.gmatch(path, "[^%.]+") do
        segments[#segments + 1] = segment
    end

    local node = root
    for i = 1, #segments - 1 do
        local segment = segments[i]
        if type(node[segment]) ~= "table" then
            node[segment] = {}
        end
        node = node[segment]
    end

    node[segments[#segments]] = value
    return value
end

-- ═══════════════════════════════════════════════════════════════════════
-- ROBLOX HELPERS
-- ═══════════════════════════════════════════════════════════════════════

--- True when `object` is a Roblox instance (and optionally of `className`).
function Util.isInstance(object, className)
    if type(object) ~= "table" then
        return false
    end
    local ok, isValid = pcall(function()
        return typeof(object) == "Instance"
    end)
    if not ok or not isValid then
        return false
    end
    if className then
        local okClass, matches = pcall(function()
            return object:IsA(className)
        end)
        return okClass and matches
    end
    return true
end

function Util.getClass(object)
    local ok, className = pcall(function()
        return typeof(object)
    end)
    if ok and className == "Instance" then
        local okName, name = pcall(function()
            return object.ClassName
        end)
        if okName then
            return name
        end
    end
    return type(object)
end

function Util.getName(object)
    local ok, name = pcall(function()
        return object.Name
    end)
    if ok and type(name) == "string" then
        return name
    end
    return nil
end

--- Distance between two BaseParts / Vector3 positions.
function Util.distance(a, b)
    local pa, pb
    if type(a) == "Vector3" then
        pa = a
    else
        local ok, pos = pcall(function()
            return a.Position
        end)
        if not ok then
            return math.huge
        end
        pa = pos
    end

    if type(b) == "Vector3" then
        pb = b
    else
        local ok, pos = pcall(function()
            return b.Position
        end)
        if not ok then
            return math.huge
        end
        pb = pos
    end

    return (pa - pb).Magnitude
end

function Util.distanceToPart(part, target)
    if not Util.isInstance(part) or not Util.isInstance(target) then
        return math.huge
    end
    return Util.distance(part.Position, target.Position)
end

-- ═══════════════════════════════════════════════════════════════════════
-- SAFETY
-- ═══════════════════════════════════════════════════════════════════════

--- Call `fn` protected by pcall. Returns (ok, result...).
function Util.safeCall(fn, ...)
    if type(fn) ~= "function" then
        return false, "not a function"
    end
    local results = { pcall(fn, ...) }
    if not results[1] then
        return false, results[2]
    end
    return true, unpack(results, 2)
end

--- Call `fn` and swallow any error. Returns true on success.
function Util.try(fn, ...)
    local ok = pcall(fn, ...)
    return ok
end

-- ═══════════════════════════════════════════════════════════════════════
-- FORMATTING
-- ═══════════════════════════════════════════════════════════════════════

function Util.formatNumber(value)
    if type(value) ~= "number" then
        return "0"
    end
    local abs = math.abs(value)
    if abs >= 1e9 then
        return string.format("%.2fB", value / 1e9)
    elseif abs >= 1e6 then
        return string.format("%.2fM", value / 1e6)
    elseif abs >= 1e3 then
        return string.format("%.1fK", value / 1e3)
    elseif abs == math.floor(abs) then
        return string.format("%d", value)
    end
    return string.format("%.2f", value)
end

function Util.formatDuration(seconds)
    seconds = math.max(0, math.floor(seconds or 0))
    local h = math.floor(seconds / 3600)
    local m = math.floor((seconds % 3600) / 60)
    local s = seconds % 60
    if h > 0 then
        return string.format("%02dh %02dm %02ds", h, m, s)
    elseif m > 0 then
        return string.format("%02dm %02ds", m, s)
    end
    return string.format("%02ds", s)
end

function Util.formatClock(seconds)
    seconds = math.floor(seconds or 0)
    return string.format("%02d:%02d:%02d",
        math.floor(seconds / 3600) % 24,
        math.floor(seconds / 60) % 60,
        seconds % 60)
end

function Util.timestamp()
    return os.time()
end

-- ═══════════════════════════════════════════════════════════════════════
-- RANDOMNESS
-- ═══════════════════════════════════════════════════════════════════════

function Util.randomChoice(list)
    if type(list) ~= "table" or #list == 0 then
        return nil
    end
    return list[math.random(1, #list)]
end

--- Fisher-Yates in place.
function Util.shuffle(list)
    for i = #list, 2, -1 do
        local j = math.random(1, i)
        list[i], list[j] = list[j], list[i]
    end
    return list
end

--- Pick one entry honouring a `weight` field (or a weight function).
function Util.pickWeighted(list, weightKey)
    local total = 0
    local weights = {}
    for i, entry in ipairs(list) do
        local w
        if type(weightKey) == "function" then
            w = weightKey(entry, i)
        else
            w = entry[weightKey or "weight"] or 1
        end
        w = tonumber(w) or 0
        weights[i] = w
        total = total + w
    end

    if total <= 0 then
        return list[math.random(1, #list)]
    end

    local roll = math.random() * total
    local running = 0
    for i = 1, #list do
        running = running + weights[i]
        if roll <= running then
            return list[i]
        end
    end
    return list[#list]
end

-- ═══════════════════════════════════════════════════════════════════════
-- COLOURS
-- ═══════════════════════════════════════════════════════════════════════

function Util.lerpColor(a, b, t)
    t = Util.clamp01(t)
    return Color3.new(
        a.R + (b.R - a.R) * t,
        a.G + (b.G - a.G) * t,
        a.B + (b.B - a.B) * t
    )
end

function Util.colorToHex(color)
    return string.format("%02X%02X%02X",
        math.floor(color.R * 255),
        math.floor(color.G * 255),
        math.floor(color.B * 255))
end

--- Approximate a colour's brightness -- used to pick readable text on top.
function Util.luminance(color)
    return 0.2126 * color.R + 0.7152 * color.G + 0.0722 * color.B
end

-- ═══════════════════════════════════════════════════════════════════════
-- TWEENING
-- ═══════════════════════════════════════════════════════════════════════

--- Tween `instance` properties using TweenService.
-- Returns true when the tween was created.
function Util.tween(instance, properties, duration, style, direction)
    if not Util.isInstance(instance) then
        return false
    end

    local ok, TweenService = pcall(function()
        return game:GetService("TweenService")
    end)
    if not ok then
        return false
    end

    local okTween = pcall(function()
        local info = TweenInfo.new(
            duration or 0.25,
            style or Enum.EasingStyle.Quad,
            direction or Enum.EasingDirection.Out
        )
        TweenService:Create(instance, info, properties):Play()
    end)
    return okTween
end

-- ═══════════════════════════════════════════════════════════════════════
-- MISC
-- ═══════════════════════════════════════════════════════════════════════

--- Human readable byte size.
function Util.formatBytes(bytes)
    bytes = tonumber(bytes) or 0
    if bytes < 1024 then
        return string.format("%d B", bytes)
    end
    local units = { "KB", "MB", "GB", "TB" }
    local value = bytes / 1024
    local unit = 1
    while value >= 1024 and unit < #units do
        value = value / 1024
        unit = unit + 1
    end
    return string.format("%.1f %s", value, units[unit])
end

--- Split a string on a separator.
function Util.split(str, separator)
    local out = {}
    if type(str) ~= "string" then
        return out
    end
    separator = separator or ","
    local pattern = "([^" .. separator .. "]+)"
    for piece in str:gmatch(pattern) do
        out[#out + 1] = piece
    end
    return out
end

return Util
end

__BFS_MODULES["data.chests"] = function(require)
--[[
    data/chests.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Chest reference data.

    Blox Fruits spawns chests in the world; digging them yields Beli, XP and
    occasionally a fruit. The chest tracker uses these tiers to colour the
    ESP overlay and to decide which chests are worth walking to.
]]

local Chests = {}

-- name, tier, weight of the reward pool, rarity colour
Chests.List = {
    { name = "Chest",            tier = 1, reward = "Beli + XP" },
    { name = "Rare Chest",       tier = 2, reward = "Beli + XP + rare loot" },
    { name = "Legendary Chest",  tier = 3, reward = "Beli + XP + fruit chance" },
    { name = "Super Rare Chest", tier = 4, reward = "High tier loot" },
}

Chests.ByName = {}
for _, chest in ipairs(Chests.List) do
    Chests.ByName[chest.name:lower()] = chest
end

--- Substrings used to spot a chest model.
Chests.Signatures = { "Chest", "Treasure" }

--- True when the model name looks like a chest.
function Chests.IsChest(modelName)
    if type(modelName) ~= "string" then
        return false
    end
    local lowered = modelName:lower()
    for _, signature in ipairs(Chests.Signatures) do
        if lowered:find(signature:lower(), 1, true) then
            return true
        end
    end
    return false
end

--- Tier of a chest model name (1 = plain chest).
function Chests.TierOf(modelName)
    if type(modelName) ~= "string" then
        return 0
    end
    local record = Chests.ByName[modelName:lower()]
    if record then
        return record.tier
    end
    if Chests.IsChest(modelName) then
        return 1
    end
    return 0
end

return Chests
end

__BFS_MODULES["data.fruits"] = function(require)
--[[
    data/fruits.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Fruit reference table.

    Rarity tiers and membership follow the live game (snapshot: 2026-10).
    Dealer prices are community-reported and drift between game updates --
    they are display-only and are never used by the roll engine.

    Aliases let the tracker match the in-game model names, which have
    changed over time:
        Chop   -> Blade      (pre-2024 name)
        Revive -> Ghost      (pre-2024 name)
        Leopard-> Tiger      (renamed, both spellings still appear in scripts)
]]

local Fruits = {}

Fruits.Order = { "Common", "Uncommon", "Rare", "Legendary", "Mythic" }

-- name, rarity, type, beli, robux, aliases
Fruits.List = {
    -- ── Common ──────────────────────────────────────────────────────────
