    return out
end

return NPCs
end

__BFS_MODULES["luck.client_roll"] = function(require)
--[[
    luck/client_roll.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Optional hook over `math.random`.

    READ THIS BEFORE ENABLING IT
    ---------------------------
    Blox Fruits resolves fruit rolls on the server. The server picks the
    fruit and sends the client the outcome. A client-side hook over
    `math.random` therefore cannot change which fruit you get -- it can
    only change numbers that the client itself happens to roll, such as a
    cosmetic animation or a local shuffle.

    The v11 build shipped this hook as "100% Real Luck Enhancement". It
    was not, and it was also broken in two ways that this module fixes:

        1. it called `OriginalRandom(min, max)` even when `math.random()`
           was called with no arguments, which raised
           "bad argument #2 to 'random' (number expected, got nil)" and
           took the whole script down
        2. it ran `debug.traceback()` on *every* random call to guess
           whether it was a fruit roll. Roblox calls math.random thousands
           of times per second, so this was a large and constant frame
           cost. Here the call site is identified with `debug.getinfo`
           and the answer is cached per function.

    The module is therefore off by default and clearly labelled as
    cosmetic in the interface.
]]

local ClientRoll = {}

ClientRoll.__index = ClientRoll

-- Substrings that mark a call site as "interesting" in the v11 build.
-- Kept narrow on purpose: a wide list (the v11 one matched "random" and
-- "item") flags almost every call in the game.
local INTERESTING = { "fruit", "gacha", "luck", "drop", "roll" }

function ClientRoll.new(options)
    options = options or {}

    return setmetatable({
        _logger = options.logger,
        _cleanup = options.cleanup,
        _bias = options.bias or 0.35,   -- how strongly the low end is favoured
        _enabled = false,
        _originalRandom = nil,
        _originalSeed = nil,
        _cache = {},
        _hits = 0,
        _misses = 0,
    }, ClientRoll)
end

--- Decide whether the caller at stack level 2 is an "interesting" call.
--- The answer is cached per function name, so the cost is one table
--- lookup after the first call of each function.
function ClientRoll:_isInteresting()
    local info = debug.getinfo(2, "n")
    local name = info and info.name
    if not name then
        return false
    end

    local cached = self._cache[name]
    if cached ~= nil then
        return cached
    end

    local lowered = string.lower(name)
    local verdict = false
    for _, keyword in ipairs(INTERESTING) do
        if lowered:find(keyword, 1, true) then
            verdict = true
            break
        end
    end

    self._cache[name] = verdict
    return verdict
end

function ClientRoll:Enable()
    if self._enabled then
        return false
    end

    local originalRandom = math.random
    local originalSeed = math.randomseed
    self._originalRandom = originalRandom
    self._originalSeed = originalSeed

    local self_ = self

    math.random = function(a, b)
        -- Reproduce every calling convention of the original function.
        -- math.random()        -> float in [0, 1)
        -- math.random(max)     -> integer in [1, max]
        -- math.random(min, max) -> integer in [min, max]
        local result
        if a == nil then
            result = originalRandom()
        elseif b == nil then
            result = originalRandom(a)
        else
            result = originalRandom(a, b)
        end

        if not self_._enabled then
            return result
        end

        if b == nil then
            self_._misses = self_._misses + 1
            return result
        end

        if not self_:_isInteresting() then
            self_._misses = self_._misses + 1
            return result
        end

        -- Bias towards the low end of the range. Which end is "better"
        -- depends on the table the caller uses; the low end is the
        -- convention used by the fruit tables in this game.
        local span = b - a + 1
        if span <= 1 then
            self_._hits = self_._hits + 1
            return result
        end

        local threshold = a + math.floor(span * self_._bias)
        if result > threshold then
            self_._hits = self_._hits + 1
            return originalRandom(a, threshold)
        end

        self_._hits = self_._hits + 1
        return result
    end

    math.randomseed = originalSeed

    self._enabled = true

    if self._cleanup then
        self._cleanup:trackGlobal("math.random", originalRandom)
        self._cleanup:trackGlobal("math.randomseed", originalSeed)
    end

    if self._logger then
        self._logger:warn("Client-side roll bias is ENABLED -- cosmetic only, it cannot change server rolls")
    end

    return true
end

function ClientRoll:Disable()
    if not self._enabled then
        return false
    end

    if self._originalRandom then
        math.random = self._originalRandom
    end
    if self._originalSeed then
        math.randomseed = self._originalSeed
    end

    self._enabled = false
    self._cache = {}

    if self._logger then
        self._logger:info("Client-side roll bias disabled, math.random restored")
    end

    return true
end

function ClientRoll:IsEnabled()
    return self._enabled
end

function ClientRoll:SetBias(bias)
    local value = tonumber(bias) or 0.35
    if value < 0 then value = 0 elseif value > 0.9 then value = 0.9 end
    self._bias = value
end

function ClientRoll:GetStats()
    return {
        enabled = self._enabled,
        bias = self._bias,
        hits = self._hits,
        misses = self._misses,
        cachedCallSites = (function()
            local count = 0
            for _ in pairs(self._cache) do
                count = count + 1
            end
            return count
        end)(),
    }
end

return ClientRoll
end

__BFS_MODULES["luck.drop_table"] = function(require)
--[[
    luck/drop_table.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    A generic weighted drop table with optional pity progress.

    The table keeps a running total of rolls and can be asked for the
    chance of the next roll, which is what a "pity" system needs.
]]

local Rng = require("luck.rng")

local DropTable = {}

DropTable.__index = DropTable

--- entries: array of { name = string, weight = number, ...payload }
function DropTable.new(entries, options)
    options = options or {}

    local self = setmetatable({
        _entries = {},
        _total = 0,
        _rolls = 0,
        _pity = 0,
        _pityTarget = options.pityTarget or 0,
        _history = {},
        _maxHistory = options.maxHistory or 100,
    }, DropTable)

    for _, entry in ipairs(entries or {}) do
        self:Add(entry)
    end

    return self
end

function DropTable:Add(entry)
    if type(entry) ~= "table" or type(entry.name) ~= "string" then
        return false
    end
    entry.weight = tonumber(entry.weight) or 0
    table.insert(self._entries, entry)
    self._total = self._total + entry.weight
    return true
end

function DropTable:Remove(name)
    for index = #self._entries, 1, -1 do
        if self._entries[index].name == name then
            self._total = self._total - self._entries[index].weight
            table.remove(self._entries, index)
            return true
        end
    end
    return false
end

function DropTable:SetWeight(name, weight)
    weight = tonumber(weight) or 0
    for _, entry in ipairs(self._entries) do
        if entry.name == name then
            self._total = self._total - entry.weight + weight
            entry.weight = weight
            return true
        end
    end
    return false
end

function DropTable:Entries()
    return self._entries
end

function DropTable:Total()
    return self._total
end

function DropTable:Count()
    return #self._entries
end

function DropTable:Rolls()
    return self._rolls
end

--- Percentage chance for a specific entry.
function DropTable:Chance(name)
    if self._total <= 0 then
        return 0
    end
    for _, entry in ipairs(self._entries) do
        if entry.name == name then
            return (entry.weight / self._total) * 100
        end
    end
    return 0
end

--- Percentage chance of rolling any of the given names.
function DropTable:ChanceOfAny(names)
    if self._total <= 0 then
        return 0
    end
    local weight = 0
    for _, name in ipairs(names) do
        for _, entry in ipairs(self._entries) do
            if entry.name == name then
                weight = weight + entry.weight
            end
        end
    end
    return (weight / self._total) * 100
end

--- Roll one entry.
function DropTable:Roll(generator)
    generator = generator or Rng.new()

    if self._total <= 0 or #self._entries == 0 then
        return nil
    end

    local roll = generator:NextFloat() * self._total
    local running = 0
    local picked = self._entries[#self._entries]

    for _, entry in ipairs(self._entries) do
        running = running + entry.weight
        if roll <= running then
            picked = entry
            break
        end
    end

    self._rolls = self._rolls + 1
    self._pity = self._pity + 1

    table.insert(self._history, picked.name)
    if #self._history > self._maxHistory then
        table.remove(self._history, 1)
    end

    return picked
end

--- Reset the roll counter and the pity progress.
function DropTable:Reset()
    self._rolls = 0
    self._pity = 0
    self._history = {}
end

function DropTable:History()
    return self._history
end

--- Number of rolls since the last "target" entry was hit.
function DropTable:Pity(targetName)
    if targetName then
        for index = #self._history, 1, -1 do
            if self._history[index] == targetName then
                return index
            end
        end
        return #self._history
    end
    return self._pity
end

--- Pity progress towards the target (0..1).
function DropTable:PityProgress(targetName, targetCount)
    targetCount = targetCount or 1
    if self._pityTarget <= 0 then
        return 0
    end
    local progress = self:Pity(targetName) / (self._pityTarget * targetCount)
    if progress < 0 then progress = 0 elseif progress > 1 then progress = 1 end
    return progress
end

return DropTable
end

__BFS_MODULES["luck.gacha_tracker"] = function(require)
--[[
    luck/gacha_tracker.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Observes the results the game sends to the client.

    When the Blox Fruit Gacha resolves, the server pushes the outcome to
    the client over a RemoteEvent. This tracker listens on the remote
    events it can find and inspects the payload for a fruit name, which
    gives a truthful record of what the gacha actually produced.

    The payload shape changes between game updates, so the matcher is
    deliberately forgiving: any argument (string or table) is searched for
    a known fruit name, and the deepest match wins.
]]

local Fruits = require("data.fruits")
local Rarity = require("luck.rarity")
local Util = require("core.util")

local GachaTracker = {}

GachaTracker.__index = GachaTracker

-- Remote names that have carried gacha results in the past.
local CANDIDATE_REMOTE_NAMES = {
    "Gacha", "FruitGacha", "GachaResult", "GachaRoll", "PurchaseFruits",
    "FruitPurchase", "RandomFruits", "BuyFruit", "FruitResult",
}

--- A stable identifier for an instance (GetDebugId is not always there).
local function DebugId(instance)
    local ok, id = pcall(function()
        return instance:GetDebugId()
    end)
    if ok and id then
        return tostring(id)
    end
    return tostring(instance)
end

function GachaTracker.new(options)
    options = options or {}

    return setmetatable({
        _logger = options.logger,
        _engine = options.engine,
        _history = {},
        _maxHistory = options.maxHistory or 100,
        _connections = {},
        _active = false,
        _listenedRemotes = {},
    }, GachaTracker)
end

--- Walk a payload and return the most specific fruit record found.
function GachaTracker:MatchPayload(payload, depth)
    depth = depth or 0
    if depth > 3 then
        return nil
    end

    if type(payload) == "string" then
        return Fruits.Resolve(payload)
    end

    if type(payload) ~= "table" then
        return nil
    end

    -- direct table fields first
    for _, key in ipairs({ "Fruit", "FruitName", "Name", "Rarity", "Reward", "Item" }) do
        local value = payload[key]
        if type(value) == "string" then
            local record = Fruits.Resolve(value)
            if record then
                return record
            end
        end
    end

    for _, value in pairs(payload) do
        if type(value) == "table" then
            local record = self:MatchPayload(value, depth + 1)
            if record then
                return record
            end
        elseif type(value) == "string" then
            local record = Fruits.Resolve(value)
            if record then
                return record
            end
        end
    end

    return nil
end

function GachaTracker:_handle(remoteName, ...)
    local record = self:MatchPayload({ ... })
    if not record then
        return
    end

    local event = {
        fruit = record.name,
        rarity = record.rarity,
        rank = Rarity.Rank(record.rarity),
        type = record.type,
        timestamp = os.time(),
        source = "gacha",
        remote = remoteName,
    }

    table.insert(self._history, event)
    while #self._history > self._maxHistory do
        table.remove(self._history, 1)
    end

    if self._engine then
        self._engine:RecordExternal(event)
    end

    if self._logger then
        self._logger:info("Gacha result observed: %s (%s) via %s", event.fruit, event.rarity, remoteName)
    end

    if self._onResult then
        self._onResult(event)
    end
end

function GachaTracker:OnResult(callback)
    self._onResult = callback
end

function GachaTracker:Start()
    if self._active then
        return false
    end

    local ok, replicatedStorage = pcall(function()
        return game:GetService("ReplicatedStorage")
    end)
    if not ok then
        return false
    end

    local connected = 0

    for _, descendant in ipairs(replicatedStorage:GetDescendants()) do
        if Util.isInstance(descendant, "RemoteEvent") then
            local lowered = string.lower(descendant.Name)
            local interesting = false
            for _, candidate in ipairs(CANDIDATE_REMOTE_NAMES) do
                if lowered:find(candidate:lower(), 1, true) then
                    interesting = true
                    break
                end
            end

            if interesting and not self._listenedRemotes[DebugId(descendant)] then
                local connection
                connection = descendant.OnClientEvent:Connect(function(...)
                    self:_handle(descendant.Name, ...)
                end)
                table.insert(self._connections, connection)
                connected = connected + 1
            end
        end
    end

    self._active = true

    if self._logger then
        self._logger:debug("Gacha tracker listening on %d remote(s)", connected)
    end

    return true
end

function GachaTracker:Stop()
    for _, connection in ipairs(self._connections) do
        pcall(function()
            connection:Disconnect()
        end)
    end
    self._connections = {}
    self._active = false
end

function GachaTracker:IsActive()
    return self._active
end

function GachaTracker:History()
    return self._history
end

function GachaTracker:Reset()
    self._history = {}
end

return GachaTracker
end

__BFS_MODULES["luck"] = function(require)
--[[
    luck/init.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Luck module facade.

    Owns the roll engine, the spawn tracker, the gacha tracker and the
    optional client-side roll hook, and exposes a single surface to the
    interface.
]]

local RollEngine = require("luck.roll_engine")
local SpawnTracker = require("luck.spawn_tracker")
local GachaTracker = require("luck.gacha_tracker")
local ClientRoll = require("luck.client_roll")
local Rarity = require("luck.rarity")
local Fruits = require("data.fruits")
local LuckMath = require("luck.luck_math")

local Luck = {}

Luck.__index = Luck

function Luck.new(options)
    options = options or {}

    local self = setmetatable({
        _logger = options.logger,
        _settings = options.settings,
        _cleanup = options.cleanup,
        _engine = RollEngine.new({
            mode = "spawn",
            maxHistory = 50,
        }),
        _spawnTracker = nil,
        _gachaTracker = nil,
        _clientRoll = nil,
        _started = false,
    }, Luck)

    return self
end

function Luck:Start(suite)
    local settings = suite and suite:settings() or self._settings

    self:SpawnTracker():Start()
    self:GachaTracker()
    self:ClientRoll()

    -- react to the settings
    if settings then
        settings:onChange("luck.multiplier", function(value)
            self._engine:SetLuckStat(math.max(0, (tonumber(value) or 1) - 1))
        end)

        settings:onChange("luck.rollHistorySize", function(value)
            self._engine:SetHistoryLimit(value)
        end)

        settings:onChange("luck.trackGacha", function(value)
            if value then
                self._gachaTracker:Start()
            else
                self._gachaTracker:Stop()
            end
        end)
    end

    -- apply the current values
    if settings then
        self._engine:SetLuckStat(math.max(0, (settings:get("luck.multiplier", 2) or 2) - 1))
        self._engine:SetHistoryLimit(settings:get("luck.rollHistorySize", 50))
        if settings:get("luck.trackGacha", true) then
            self._gachaTracker:Start()
        end
    end

    self._started = true

    if self._logger then
        self._logger:info("Luck module started (engine + spawn tracker + gacha tracker)")
    end

    return true
end

function Luck:Stop()
    self._started = false
    if self._gachaTracker then
        self._gachaTracker:Stop()
    end
    if self._clientRoll then
        self._clientRoll:Disable()
    end
    return true
end

--- True once Start() has run successfully.
function Luck:IsStarted()
    return self._started
end

-- ── accessors ────────────────────────────────────────────────────────────

function Luck:Engine()
    return self._engine
end

--- The spawn tracker, created on first use.
---
--- The interface is built before the modules are started, so the tabs ask
--- for the tracker while it does not exist yet. Creating it lazily keeps
--- both orderings safe.
function Luck:SpawnTracker()
    if not self._spawnTracker then
        self._spawnTracker = SpawnTracker.new({
            logger = self._logger,
            engine = self._engine,
            maxHistory = 100,
        })
        self._spawnTracker:Start()
    end
    return self._spawnTracker
end

--- The gacha tracker, created on first use.
function Luck:GachaTracker()
    if not self._gachaTracker then
        self._gachaTracker = GachaTracker.new({
            logger = self._logger,
            engine = self._engine,
        })
    end
    return self._gachaTracker
end

--- The optional client-side roll hook, created on first use.
function Luck:ClientRoll()
    if not self._clientRoll then
        self._clientRoll = ClientRoll.new({
            logger = self._logger,
            cleanup = self._cleanup,
        })
    end
    return self._clientRoll
end

--- One snapshot for the dashboard.
function Luck:GetStats()
    local engineStats = self._engine:GetStats()
    local spawnDistribution = self._spawnTracker and self._spawnTracker:Distribution() or {}
    local gachaHistory = self._gachaTracker and self._gachaTracker:History() or {}

    return {
        engine = engineStats,
        spawns = {
            total = self._spawnTracker and #self._spawnTracker:History() or 0,
            active = self._spawnTracker and #self._spawnTracker:Active() or 0,
            distribution = spawnDistribution,
        },
        gacha = {
            total = #gachaHistory,
            last = gachaHistory[#gachaHistory],
        },
        clientRoll = self._clientRoll and self._clientRoll:GetStats() or { enabled = false },
        chances = {
            spawn = {
                legendary = Rarity.Chance(Rarity.SPAWN_WEIGHTS, "Legendary"),
                mythic = Rarity.Chance(Rarity.SPAWN_WEIGHTS, "Mythic"),
            },
            gacha = {
                legendary = Rarity.Chance(Rarity.GACHA_WEIGHTS, "Legendary"),
                mythic = Rarity.Chance(Rarity.GACHA_WEIGHTS, "Mythic"),
            },
        },
    }
end

--- Roll once using the engine. Used by the "Roll" button in the Luck tab.
function Luck:Roll()
    return self._engine:Roll()
end

function Luck:SetMode(mode)
    self._engine:SetMode(mode)
end

function Luck:GetMode()
    return self._engine:GetMode()
end

function Luck:SetLuckStat(value)
    self._engine:SetLuckStat(value)
end

function Luck:GetLuckStat()
    return self._engine:GetLuckStat()
end

function Luck:Simulate(iterations)
    return self._engine:Simulate(iterations)
end

function Luck:Reset()
    self._engine:Reset()
    if self._spawnTracker then
        self._spawnTracker:Reset()
    end
    if self._gachaTracker then
        self._gachaTracker:Reset()
    end
end

return Luck
end

__BFS_MODULES["luck.luck_math"] = function(require)
--[[
    luck/luck_math.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Luck statistics.

    A "luck stat" answers the question every gacha player asks: "was that
    a good roll?". The answer here is a z-score -- how far the observed
    result sits from the expected one, measured in standard deviations.
    Two standard deviations above the mean is a genuinely unusual result,
    which is exactly what a player means by "lucky".
]]

local LuckMath = {}

--- Mean of a numeric list.
function LuckMath.Mean(values)
    if type(values) ~= "table" or #values == 0 then
        return 0
    end
    local total = 0
    for index = 1, #values do
        total = total + values[index]
    end
    return total / #values
end

--- Population standard deviation.
function LuckMath.StdDev(values)
    if type(values) ~= "table" or #values < 2 then
        return 0
    end
    local mean = LuckMath.Mean(values)
    local total = 0
    for index = 1, #values do
        local delta = values[index] - mean
        total = total + delta * delta
    end
    return math.sqrt(total / #values)
end

--- z-score of `value` inside `values`.
function LuckMath.ZScore(values, value)
    local stdDev = LuckMath.StdDev(values)
    if stdDev <= 0 then
        return 0
    end
    return (value - LuckMath.Mean(values)) / stdDev
end

--- A human readable verdict for a z-score.
function LuckMath.Rating(zScore)
    if zScore >= 2.0 then
        return "Legendary luck", "jacked"
    elseif zScore >= 1.0 then
        return "Very lucky", "great"
    elseif zScore >= 0.35 then
        return "Lucky", "good"
    elseif zScore > -0.35 then
        return "Average", "normal"
    elseif zScore > -1.0 then
        return "Unlucky", "rough"
    elseif zScore > -2.0 then
        return "Very unlucky", "bad"
    end
    return "Cursed", "brutal"
end

--- Full report for a list of observed rarity ranks.
function LuckMath.Report(values, expectedMean, expectedStdDev)
    local count = #values
    if count == 0 then
        return {
            count = 0,
            mean = expectedMean or 0,
            zScore = 0,
            rating = "No data",
            verdict = "waiting",
        }
    end

    local mean = LuckMath.Mean(values)
    local zScore
    if expectedStdDev and expectedStdDev > 0 then
        zScore = (mean - (expectedMean or mean)) / expectedStdDev
    else
        zScore = LuckMath.ZScore(values, mean)
    end

    local rating, verdict = LuckMath.Rating(zScore)

    return {
        count = count,
        mean = mean,
        zScore = zScore,
        rating = rating,
        verdict = verdict,
    }
end

--- How many standard deviations of good luck a single result is worth.
function LuckMath.ResultDelta(value, mean, stdDev)
    if not stdDev or stdDev <= 0 then
        return 0
    end
    return (value - mean) / stdDev
end

--- Confidence that the observed average differs from the expected one.
--- Uses a simple normal approximation -- good enough for a dashboard.
function LuckMath.Confidence(zScore, sampleSize)
    sampleSize = math.max(1, sampleSize or 1)
    local scaled = math.abs(zScore) / math.sqrt(sampleSize)
    -- erf approximation
    local t = 1 / (1 + 0.3275911 * scaled)
    local erf = 1 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * math.exp(-scaled * scaled)
    if erf < 0 then erf = 0 elseif erf > 1 then erf = 1 end
    return erf * 100
end

--- Cumulative distribution helper: probability of rolling at least a rank.
function LuckMath.CumulativeChance(weights, minimumRank)
    local total = 0
    local hit = 0
    for _, name in ipairs(require("luck.rarity").Order) do
        local weight = weights[name] or 0
        total = total + weight
        if require("luck.rarity").Rank(name) >= minimumRank then
            hit = hit + weight
        end
    end
    if total <= 0 then
        return 0
    end
    return (hit / total) * 100
end

return LuckMath
end

__BFS_MODULES["luck.rarity"] = function(require)
--[[
    luck/rarity.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Rarity tiers, colours and the weight tables used by the roll engine.

    The developers have never published the exact drop rates, so the weights
    below are community estimates and are clearly marked as such. They are
    configuration, not fact: edit them in `luck/rarity.lua` and the whole
    engine follows.

    Two tables are provided because the game has two different economies:
        SPAWN -- a fruit found in the world (Mythic is roughly 0.5%)
        GACHA -- the Blox Fruit Gacha (Mythic is roughly 1-4%)
]]

local Rng = require("luck.rng")

local Rarity = {}

Rarity.Order = { "Common", "Uncommon", "Rare", "Legendary", "Mythic" }

Rarity.Colors = {
    Common = Color3.fromRGB(160, 165, 175),
    Uncommon = Color3.fromRGB(70, 205, 120),
    Rare = Color3.fromRGB(60, 160, 255),
    Legendary = Color3.fromRGB(190, 80, 230),
    Mythic = Color3.fromRGB(255, 170, 40),
}

Rarity.ShortLabels = {
    Common = "COM",
    Uncommon = "UNC",
    Rare = "RAR",
    Legendary = "LEG",
    Mythic = "MYT",
}

--- Community estimated weights.
Rarity.SPAWN_WEIGHTS = {
    Common = 60.0,
    Uncommon = 25.0,
    Rare = 11.0,
    Legendary = 3.4,
    Mythic = 0.6,
}

Rarity.GACHA_WEIGHTS = {
    Common = 46.0,
    Uncommon = 28.0,
    Rare = 15.0,
    Legendary = 8.0,
    Mythic = 3.0,
}

--- Value used for the "expected luck" maths. Roughly the middle of each
--- tier's Beli range, normalised.
Rarity.VALUE = {
    Common = 1,
    Uncommon = 2,
    Rare = 3,
    Legendary = 4,
    Mythic = 5,
}

function Rarity.Rank(name)
    for index, rarity in ipairs(Rarity.Order) do
        if rarity == name then
            return index
        end
    end
    return 0
end

function Rarity.Color(name)
    return Rarity.Colors[name] or Color3.fromRGB(200, 200, 200)
end

function Rarity.Short(name)
    return Rarity.ShortLabels[name] or string.sub(name or "?", 1, 3):upper()
end

--- Build a weighted list of { name, weight, rank } from a weight table.
function Rarity.ToWeightedList(weights)
    local list = {}
    for _, name in ipairs(Rarity.Order) do
        list[#list + 1] = {
            name = name,
            weight = weights[name] or 0,
            rank = Rarity.Rank(name),
        }
    end
    return list
end

--- Percentage chance of a rarity under a weight table.
function Rarity.Chance(weights, name)
    local total = 0
    for _, rarity in ipairs(Rarity.Order) do
        total = total + (weights[rarity] or 0)
    end
    if total <= 0 then
        return 0
    end
    return ((weights[name] or 0) / total) * 100
end

--- Apply a luck stat to a weight table.
---
--- Luck works the way it does in every modern gacha: the higher the tier,
--- the more a point of luck is worth. A luck stat of 1.0 gives Mythic
--- entries a 60% weight boost while Common entries gain almost nothing.
function Rarity.ApplyLuck(weights, luckStat)
    local out = {}
    for _, name in ipairs(Rarity.Order) do
        local rank = Rarity.Rank(name)
        local tierBonus = 1 + (rank - 1) * 0.20
        out[name] = (weights[name] or 0) * (1 + (luckStat or 0) * tierBonus)
    end
    return out
end

--- Expected rarity rank for a weight table.
function Rarity.ExpectedRank(weights)
    local total = 0
    local weighted = 0
    for _, name in ipairs(Rarity.Order) do
        local weight = weights[name] or 0
        total = total + weight
        weighted = weighted + weight * Rarity.Rank(name)
    end
    if total <= 0 then
        return 0
    end
    return weighted / total
end

--- Standard deviation of the rarity rank distribution.
function Rarity.StdDev(weights)
    local mean = Rarity.ExpectedRank(weights)
    local total = 0
    local variance = 0
    for _, name in ipairs(Rarity.Order) do
        local weight = weights[name] or 0
        total = total + weight
        variance = variance + weight * ((Rarity.Rank(name) - mean) ^ 2)
    end
    if total <= 0 then
        return 0
    end
    return math.sqrt(variance / total)
end

--- Roll a rarity name from a weight table using the given generator.
function Rarity.Roll(weights, generator)
    generator = generator or Rng.new()
    local list = Rarity.ToWeightedList(weights)
    local picked = generator:PickWeighted(list, "weight")
    return picked and picked.name or "Common"
end

return Rarity
end

__BFS_MODULES["luck.rng"] = function(require)
--[[
    luck/rng.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Self-contained pseudo random number generator.

    Why not math.random? Two reasons:
        1. the suite optionally hooks math.random to bias client-side rolls,
           and a roll engine that used the same source would end up biased
           by its own hook
        2. math.random() with no arguments returns a float, and the v11
           hook passed that straight back into the original function,
           which raised "bad argument #2 to 'random'" and killed the
           script. This generator has one unambiguous contract:
               NextFloat() -> float in [0, 1)
               NextInt(min, max) -> integer in [min, max] inclusive

    Algorithm: xorshift64* -- fast, deterministic, good enough for a game
    loot roller and trivially portable between Lua and Luau.
]]

local Rng = {}

Rng.__index = Rng

-- The generator is deliberately built from multiplication, addition and
-- modulo only -- no bitwise operators.
--
-- The reason is portability: Lua 5.3 has 64 bit integers, Luau has only
-- doubles, and some Lua hosts cap their integer range at 32 bits. The
-- bitwise operators behave differently in all three and refuse to run on
-- a value that is not exactly representable as an integer.
--
-- Every intermediate value below stays under 2^48, so it is exact in a
-- double and the generator produces the same stream everywhere.
local MODULUS = 2147483647        -- 2^31 - 1
local MULTIPLIER_A = 48271        -- Park & Miller
local MULTIPLIER_B = 16807        -- second, decorrelated stream
local MIX = 65599

function Rng.new(seed)
    local self = setmetatable({
        _state = 0,
        _a = 1,
        _b = 1,
    }, Rng)

    self:Seed(seed or os.time() * 1000 + (os.clock() * 1000000) % 1000000)
    return self
end

--- Reseed the generator.
function Rng:Seed(seed)
    seed = math.floor(math.abs(tonumber(seed) or 0)) % MODULUS
    if seed == 0 then
        seed = 1
    end

    self._a = seed
    self._b = math.floor((seed * MULTIPLIER_B) % MODULUS)
    if self._b == 0 then
        self._b = 1
    end
    self._state = 0

    -- warm the generator up so the first values are not correlated with
    -- the seed
    for _ = 1, 4 do
        self:_next()
    end

    return self
end

--- Advance both streams and mix them into a single 31 bit value.
function Rng:_next()
    self._a = math.floor((self._a * MULTIPLIER_A) % MODULUS)
    self._b = math.floor((self._b * MULTIPLIER_B) % MODULUS)

    local combined = self._a + self._b
    self._state = math.floor((combined * MIX) % MODULUS)
    return self._state
end

--- Float in [0, 1).
function Rng:NextFloat()
    local raw = math.floor(self:_next())
    return raw / MODULUS
end

--- Integer in [min, max], both inclusive.
function Rng:NextInt(min, max)
    min = math.floor(tonumber(min) or 1)
    max = math.floor(tonumber(max) or 1)
    if max < min then
        min, max = max, min
    end
    local span = max - min + 1
    return math.floor(min + (math.floor(self:_next()) % span))
end

--- True with the given probability (0..1).
function Rng:Chance(probability)
    return self:NextFloat() < probability
end

--- Pick one entry from an array, honouring an optional weight field.
function Rng:PickWeighted(list, weightKey)
    if type(list) ~= "table" or #list == 0 then
        return nil
    end

    local total = 0
    local weights = {}
    for index, entry in ipairs(list) do
        local weight
        if type(weightKey) == "function" then
            weight = weightKey(entry, index)
        else
            weight = entry[weightKey or "weight"] or 1
        end
        weight = tonumber(weight) or 0
        weights[index] = weight
        total = total + weight
    end

    if total <= 0 then
        return list[self:NextInt(1, #list)]
    end

    local roll = self:NextFloat() * total
    local running = 0
    for index = 1, #list do
        running = running + weights[index]
        if roll <= running then
            return list[index]
        end
    end
    return list[#list]
end

--- Fisher-Yates shuffle on a copy of the input.
function Rng:Shuffled(list)
    local copy = {}
    for index = 1, #list do
        copy[index] = list[index]
    end
    for index = #copy, 2, -1 do
        local swap = self:NextInt(1, index)
        copy[index], copy[swap] = copy[swap], copy[index]
    end
    return copy
end

--- Current internal state -- handy for reproducing a session.
function Rng:State()
    return self._state
end

return Rng
end

__BFS_MODULES["luck.roll_engine"] = function(require)
--[[
    luck/roll_engine.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    The roll engine.

    It ties together the rarity tables, the fruit database and the luck
    statistics, and keeps a rolling history that the interface renders.

    Two important notes about what this engine is and is not:

    1. It rolls from the *modelled* tables. It does not and cannot change
       the odds the Blox Fruits server uses -- no client-side script can,
       because the server decides the result and only sends the outcome
       to the client.
    2. It is still useful: it powers the simulator in the Luck tab, it
       estimates the effective odds of the current table, and it grades
       the *real* results that the spawn and gacha trackers observe.
]]

local Rng = require("luck.rng")
local Rarity = require("luck.rarity")
local Fruits = require("data.fruits")
local LuckMath = require("luck.luck_math")
local Util = require("core.util")

local RollEngine = {}

RollEngine.__index = RollEngine

function RollEngine.new(options)
    options = options or {}

    local self = setmetatable({
        _rng = Rng.new(options.seed),
        _mode = options.mode or "spawn",   -- "spawn" | "gacha"
        _luckStat = options.luckStat or 0,
        _history = {},
        _maxHistory = options.maxHistory or 50,
        _totalRolls = 0,
        _rarityCounts = {},
        _lastResult = nil,
    }, RollEngine)

    for _, rarity in ipairs(Rarity.Order) do
        self._rarityCounts[rarity] = 0
    end

    return self
end

function RollEngine:SetMode(mode)
    self._mode = (mode == "gacha") and "gacha" or "spawn"
end

function RollEngine:GetMode()
    return self._mode
end

function RollEngine:SetLuckStat(value)
    self._luckStat = tonumber(value) or 0
end

function RollEngine:GetLuckStat()
    return self._luckStat
end

function RollEngine:SetHistoryLimit(limit)
    self._maxHistory = math.max(1, tonumber(limit) or 50)
    while #self._history > self._maxHistory do
        table.remove(self._history, 1)
    end
end

--- The weight table for the current mode, before luck is applied.
function RollEngine:BaseWeights()
    if self._mode == "gacha" then
        return Rarity.GACHA_WEIGHTS
    end
    return Rarity.SPAWN_WEIGHTS
end

--- The weight table actually used for a roll.
function RollEngine:EffectiveWeights()
    return Rarity.ApplyLuck(self:BaseWeights(), self._luckStat)
end

--- Roll a rarity, then a fruit inside that rarity.
--- Returns nil when the rarity is empty.
function RollEngine:Roll()
    local weights = self:EffectiveWeights()
    local rarityName = Rarity.Roll(weights, self._rng)

    local pool = Fruits.ByRarity[rarityName] or {}
    if #pool == 0 then
        return nil
    end

    local fruit = self._rng:PickWeighted(pool, "beli")

    local result = {
        rarity = rarityName,
        rank = Rarity.Rank(rarityName),
        fruit = fruit.name,
        type = fruit.type,
        beli = fruit.beli,
        timestamp = os.time(),
        luckStat = self._luckStat,
        mode = self._mode,
    }

    self:_record(result)
    return result
end

--- Roll `count` times. Returns the list of results.
function RollEngine:RollMany(count)
    local out = {}
    for _ = 1, (count or 10) do
        local result = self:Roll()
        if result then
            out[#out + 1] = result
        end
    end
    return out
end

function RollEngine:_record(result)
    self._totalRolls = self._totalRolls + 1
    self._rarityCounts[result.rarity] = (self._rarityCounts[result.rarity] or 0) + 1
    self._lastResult = result

    table.insert(self._history, result)
    if #self._history > self._maxHistory then
        table.remove(self._history, 1)
    end
end

--- Record a result that was observed in the real game (from the spawn or
--- gacha tracker) so that the statistics reflect reality rather than the
--- model.
function RollEngine:RecordExternal(result)
    if type(result) ~= "table" or not result.rarity then
        return false
    end
    result.external = true
    self:_record(result)
    return true
end

function RollEngine:History()
    return self._history
end

function RollEngine:LastResult()
    return self._lastResult
end

function RollEngine:TotalRolls()
    return self._totalRolls
end

function RollEngine:RarityCounts()
    return self._rarityCounts
end

--- Percentage of rolls that landed on each rarity.
function RollEngine:RarityDistribution()
    local out = {}
    for _, rarity in ipairs(Rarity.Order) do
        local count = self._rarityCounts[rarity] or 0
        local percent = 0
        if self._totalRolls > 0 then
            percent = (count / self._totalRolls) * 100
        end
        out[rarity] = {
            count = count,
            percent = percent,
        }
    end
    return out
end

--- Luck report for the recorded results.
function RollEngine:GetStats()
    local ranks = {}
    for _, result in ipairs(self._history) do
        ranks[#ranks + 1] = result.rank or Rarity.Rank(result.rarity)
    end

    local weights = self:BaseWeights()
    local expectedMean = Rarity.ExpectedRank(weights)
    local expectedStdDev = Rarity.StdDev(weights)

    local report = LuckMath.Report(ranks, expectedMean, expectedStdDev)

    return {
        -- NOTE: keys are lower camel case everywhere. The v11 build mixed
        -- `Active` and `active` in the same project, which is why its
        -- statistics tab always showed zeros.
        active = self._luckStat > 0,
        mode = self._mode,
        multiplier = 1 + self._luckStat,
        totalRolls = self._totalRolls,
        enhancedRolls = self._rarityCounts.Legendary + self._rarityCounts.Mythic,
        successRate = report.zScore and ((report.zScore + 3) / 6) * 100 or 0,
        luckRating = report.rating,
        luckVerdict = report.verdict,
        luckZScore = report.zScore,
        expectedMean = expectedMean,
        observedMean = report.mean,
        confidence = LuckMath.Confidence(report.zScore, report.count),
        lastResult = self._lastResult,
        distribution = self:RarityDistribution(),
    }
end

--- Effective probability of a rarity after luck is applied.
function RollEngine:EffectiveChance(rarity)
    local weights = self:EffectiveWeights()
    return Rarity.Chance(weights, rarity)
end

--- Monte-Carlo estimate of the effective odds. Used by the simulator tab
--- so the user can see the table they are actually rolling against.
function RollEngine:Simulate(iterations)
    iterations = iterations or 1000
    local counts = {}
    for _, rarity in ipairs(Rarity.Order) do
        counts[rarity] = 0
    end

    for _ = 1, iterations do
        local weights = self:EffectiveWeights()
        local picked = Rarity.Roll(weights, self._rng)
        counts[picked] = counts[picked] + 1
    end

    local out = {}
    for _, rarity in ipairs(Rarity.Order) do
        out[rarity] = {
            count = counts[rarity],
            percent = (counts[rarity] / iterations) * 100,
            expected = Rarity.Chance(self:EffectiveWeights(), rarity),
        }
    end
    return out
end

function RollEngine:Reset()
    self._history = {}
    self._totalRolls = 0
    self._lastResult = nil
    for _, rarity in ipairs(Rarity.Order) do
        self._rarityCounts[rarity] = 0
    end
end

return RollEngine
end

__BFS_MODULES["luck.spawn_tracker"] = function(require)
--[[
    luck/spawn_tracker.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Observes the fruit that actually spawns in the world.

    The tracker walks the live workspace on an interval, looks for fruit
    models, and works out which fruit it is. Every new fruit is recorded
    with a timestamp, which gives the suite something the v11 build never
    had: a real, measured picture of how the spawns are distributed on
    *this* server, and a luck rating based on real results instead of on
    a simulation.

    Fruit models in Blox Fruits are not standardised, so the name is
    recovered in several ways and the first one that works wins:
        1. an attribute (FruitName / Name / Fruit / Rarity)
        2. a StringValue child
        3. a child model named after a known fruit
        4. the model's own name matched against the fruit database
]]

local Fruits = require("data.fruits")
local Rarity = require("luck.rarity")
local Util = require("core.util")

local SpawnTracker = {}

SpawnTracker.__index = SpawnTracker

-- Attribute names the game has used over time.
local NAME_ATTRIBUTES = { "FruitName", "Fruit", "Name", "DisplayName", "Rarity" }

--- A stable identifier for an instance. GetDebugId is not available in
--- every environment, so the instance itself is the fallback.
function SpawnTracker.DebugId(instance)
    local ok, id = pcall(function()
        return instance:GetDebugId()
    end)
    if ok and id then
        return tostring(id)
    end
    return tostring(instance)
end

function SpawnTracker.new(options)
    options = options or {}

    return setmetatable({
        _logger = options.logger,
        _engine = options.engine,
        _scanInterval = options.scanInterval or 2.0,
        _active = {},
        _seen = {},
        _history = {},
        _maxHistory = options.maxHistory or 100,
        _lastScan = 0,
        _scanCount = 0,
        _root = options.root,
    }, SpawnTracker)
end

function SpawnTracker:Start()
    if self._root == nil then
        local ok, Players = pcall(function()
            return game:GetService("Players")
        end)
        if not ok then
            return false
        end
        local okPlayer, player = pcall(function()
            return Players.LocalPlayer
        end)
        if okPlayer and player then
            self._root = player:FindFirstChild("Character")
        end
    end
    return true
end

function SpawnTracker:_getWorkspace()
    if self._workspace then
        return self._workspace
    end
    local ok, workspace = pcall(function()
        return game:GetService("Workspace")
    end)
    if ok then
        self._workspace = workspace
    end
    return self._workspace
end

--- Extract a fruit record from an instance, or nil.
function SpawnTracker:Identify(instance)
    if not Util.isInstance(instance) then
        return nil
    end

    -- 1. attributes
    for _, attributeName in ipairs(NAME_ATTRIBUTES) do
        local ok, value = pcall(function()
            return instance:GetAttribute(attributeName)
        end)
        if ok and type(value) == "string" then
            local record = Fruits.Resolve(value)
            if record then
                return record
            end
        end
    end

    -- 2. StringValue children
    for _, child in ipairs(instance:GetChildren()) do
        if Util.isInstance(child, "StringValue") then
            local record = Fruits.Resolve(child.Value)
            if record then
                return record
            end
        end
    end

    -- 3. child models named after a fruit
    for _, child in ipairs(instance:GetChildren()) do
        if Util.isInstance(child, "Model") then
            local record = Fruits.Resolve(child.Name)
            if record then
                return record
            end
        end
    end

    -- 4. the instance name itself
    local record = Fruits.Resolve(instance.Name)
    if record then
        return record
    end

    return nil
end

--- True when an instance looks like a fruit model.
function SpawnTracker:LooksLikeFruit(instance)
    if not Util.isInstance(instance) then
        return false
    end

    local name = string.lower(instance.Name or "")
    if name:find("fruit", 1, true) then
        return true
    end

    -- some spawns are named after the fruit directly
    return Fruits.Resolve(instance.Name) ~= nil
end

--- Scan the workspace once and return the list of live fruit spawns.
function SpawnTracker:Scan()
    local workspace = self:_getWorkspace()
    if not workspace then
        return {}
    end

    local found = {}
    local seen = {}

    for _, descendant in ipairs(workspace:GetDescendants()) do
        if Util.isInstance(descendant) and self:LooksLikeFruit(descendant) then
            local record = self:Identify(descendant)
            if record then
                local entry = {
                    instance = descendant,
                    fruit = record.name,
                    rarity = record.rarity,
                    type = record.type,
                    position = descendant.Position,
                    instanceId = SpawnTracker.DebugId(descendant),
                }
                found[#found + 1] = entry
                seen[entry.instanceId] = true

                if not self._seen[entry.instanceId] then
                    self._seen[entry.instanceId] = true
                    self:_onNewSpawn(entry)
                end
            end
        end
    end

    -- forget spawns that are gone
    for id in pairs(self._seen) do
        if not seen[id] then
            self._seen[id] = nil
        end
    end

    self._active = found
    self._scanCount = self._scanCount + 1
    self._lastScan = os.clock()

    return found
end

function SpawnTracker:_onNewSpawn(entry)
    local event = {
        fruit = entry.fruit,
        rarity = entry.rarity,
        rank = Rarity.Rank(entry.rarity),
        type = entry.type,
        timestamp = os.time(),
        source = "spawn",
    }

    table.insert(self._history, event)
    while #self._history > self._maxHistory do
        table.remove(self._history, 1)
    end

    if self._engine then
        self._engine:RecordExternal(event)
    end

    if self._logger then
        self._logger:info("Fruit spawn observed: %s (%s)", entry.fruit, entry.rarity)
    end

    if self._onSpawn then
        self._onSpawn(event)
    end
end

--- Register a callback fired whenever a new fruit spawns.
function SpawnTracker:OnSpawn(callback)
    self._onSpawn = callback
end

function SpawnTracker:Active()
    return self._active
end

function SpawnTracker:History()
    return self._history
end

function SpawnTracker:ScanCount()
    return self._scanCount
end

--- Observed rarity distribution of real spawns.
function SpawnTracker:Distribution()
    local counts = {}
    for _, rarity in ipairs(Rarity.Order) do
        counts[rarity] = 0
    end

    local total = 0
    for _, event in ipairs(self._history) do
        counts[event.rarity] = (counts[event.rarity] or 0) + 1
        total = total + 1
    end

    local out = {}
    for _, rarity in ipairs(Rarity.Order) do
        out[rarity] = {
            count = counts[rarity],
            percent = total > 0 and (counts[rarity] / total) * 100 or 0,
        }
    end
    return out
end

function SpawnTracker:Reset()
    self._history = {}
    self._seen = {}
    self._active = {}
end

return SpawnTracker
end

__BFS_MODULES["main"] = function(require)
--[[
    src/main.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Entry point. Wires the modules, the interface and the keybinds together.

    The module loader works in two modes:
        * Roblox Studio -- resolves the sibling ModuleScripts and requires
          them directly
        * an executor    -- downloads the files from the publish URL and
          evaluates them

    Set the global BFS_SOURCE_URL before running this file to point the
    executor mode at your own copy of the project.
]]

local SOURCE_URL = _G.BFS_SOURCE_URL
    or "https://raw.githubusercontent.com/modbadr3-coder/blox-fruits-luck/main/v12"

-- ═══════════════════════════════════════════════════════════════════════
-- MODULE RESOLUTION
-- ═══════════════════════════════════════════════════════════════════════

local ModuleCache = {}

--- Resolve a module path such as "core.util" to its value.
local function LoadModule(path)
    if ModuleCache[path] ~= nil then
        return ModuleCache[path]
    end

    -- bundle mode: the single file build installs a resolver
    if type(_G.BFS_MODULE_RESOLVER) == "function" then
        local ok, result = pcall(_G.BFS_MODULE_RESOLVER, path)
        if ok then
            ModuleCache[path] = result
            return result
        end
    end

    local ok, result = pcall(function()
        -- 1. Roblox Studio: walk the folder tree next to this script
        if script and script.Parent then
            local current = script
            local found = true
            for segment in path:gmatch("[^%.]+") do
                local child = current:FindFirstChild(segment)
                if not child then
                    found = false
                    break
                end
                current = child
            end

            if found and current:IsA("ModuleScript") then
                return require(current)
            end

            -- "core" -> core/init.lua
            local initCandidate = current:FindFirstChild("init")
            if found == false then
                -- retry with an "init" suffix
            end
        end

        -- 2. executor: download it
        if SOURCE_URL then
            local url = SOURCE_URL .. "/" .. path:gsub("%.", "/")
            if path == "core" or path == "luck" or path == "world" or path == "ui" then
                url = url .. "/init"
            end
            url = url .. ".lua"

            local loader = loadstring or load
            local chunk = loader(game:HttpGet(url, true))
            if not chunk then
                error("failed to download " .. url)
            end
            return chunk()
        end

        error("cannot resolve module '" .. path .. "'")
    end)

    if not ok then
        error("Failed to load module '" .. path .. "': " .. tostring(result))
    end

    ModuleCache[path] = result
    return result
end

-- ═══════════════════════════════════════════════════════════════════════
-- BOOTSTRAP
-- ═══════════════════════════════════════════════════════════════════════

local Suite = LoadModule("core")
local Logger = LoadModule("core.logger")
local Settings = LoadModule("core.settings")
local Window = LoadModule("ui")

local Luck = LoadModule("luck")
local World = LoadModule("world")

local logger = Logger.new({
    prefix = "[BFS]",
    level = Logger.LEVELS.INFO,
})

local settings = Settings.new({ logger = logger })

local suite = Suite.new({
    logger = logger,
    settings = settings,
})

-- ── modules ─────────────────────────────────────────────────────────────

suite:Register("luck", Luck.new({
    logger = logger,
    settings = settings,
    cleanup = suite:cleanup(),
}))

suite:Register("world", World.new({
    logger = logger,
    settings = settings,
    cleanup = suite:cleanup(),
}))

-- ── interface ───────────────────────────────────────────────────────────

local window = Window.new({
    logger = logger,
    title = "BLOX FRUITS SUITE",
    version = "v12.0",
    width = settings:get("ui.windowWidth", 560),
    height = settings:get("ui.windowHeight", 480),
    theme = settings:get("general.theme", "midnight"),
    accent = settings:get("general.accent", "cyan"),
    animations = settings:get("ui.animations", true),
    cleanup = suite:cleanup(),
})

local TabBuilders = {
    { "dashboard", LoadModule("ui.tabs.dashboard") },
    { "luck", LoadModule("ui.tabs.luck") },
    { "world", LoadModule("ui.tabs.world") },
    { "farm", LoadModule("ui.tabs.farm") },
    { "stats", LoadModule("ui.tabs.stats") },
    { "settings", LoadModule("ui.tabs.settings") },
    { "about", LoadModule("ui.tabs.about") },
}

for _, entry in ipairs(TabBuilders) do
    local ok, err = pcall(entry[2].Create, window, suite)
    if not ok then
        logger:error("Could not build the '%s' tab: %s", entry[1], tostring(err))
    end
end

window:SetTabWidth(settings:get("ui.tabWidth", 128))
window:SetNotificationsEnabled(settings:get("general.notifications", true))

-- ── keybinds ────────────────────────────────────────────────────────────

local hotkeys = suite:hotkeys()

hotkeys:bind("toggle_ui", function()
    window:Toggle()
end, settings:get("general.keybind", Enum.KeyCode.RightShift))

hotkeys:bind("minimize_ui", function()
    window:ToggleMinimize()
end, settings:get("general.minimizeKey", Enum.KeyCode.End))

hotkeys:bind("rescan_world", function()
    suite:Get("world"):Scanner():Scan()
    window:Notify("World", "Rescan finished", "info")
end)

hotkeys:bind("toggle_esp", function()
    local world = suite:Get("world")
    local enabled = world:ESP():IsEnabled()
    world:ESP():SetEnabled(not enabled)
    window:Notify("ESP", enabled and "disabled" or "enabled", "info")
end)

-- ── character events ────────────────────────────────────────────────────

local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer

LocalPlayer.CharacterAdded:Connect(function(character)
    if settings:get("general.minimizeOnDeath", true) then
        window:ToggleMinimize()
    end
end)

-- ── start ───────────────────────────────────────────────────────────────

suite:Start()

-- refresh the interface a few times a second
suite:scheduler():every("ui.refresh", 0.35, function()
    window:Refresh()
end)

-- keep the fps counter honest
suite:scheduler():every("ui.fps", 1.0, function()
    local stats = suite:Get("world"):GetStats()
    if stats then
        suite:events():emit("ui.tick", stats)
    end
end)

logger:info("Press %s to toggle the interface", hotkeys:keyName(hotkeys:getKey("toggle_ui")))

-- expose the suite for the console
_G.BloxFruitsSuite = suite
_G.BFS_Window = window

return suite
end

__BFS_MODULES["ui.container"] = function(require)
--[[
    ui/container.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    The widget container mixin.

    Both a tab page and a collapsible section can hold widgets, so both
    share the same Add* API. The methods ask the window to build the
    widget, which keeps the widget modules independent of each other and
    avoids a require cycle between the section widget and the rest.
]]

local Container = {}

Container.__index = Container

function Container:_parent()
    return self._container
end

function Container:AddToggle(text, default, callback)
    return self._window:CreateWidget("Toggle", self._container, {
        text = text,
        default = default,
        callback = callback,
    })
end

function Container:AddSlider(text, min, max, default, step, suffix, callback)
    return self._window:CreateWidget("Slider", self._container, {
        text = text,
        min = min,
        max = max,
        default = default,
        step = step,
        suffix = suffix,
        callback = callback,
    })
end

function Container:AddDropdown(text, options, default, callback)
    return self._window:CreateWidget("Dropdown", self._container, {
        text = text,
        options = options,
        default = default,
        callback = callback,
    })
end

function Container:AddButton(text, style, callback)
    return self._window:CreateWidget("Button", self._container, {
        text = text,
        style = style,
        callback = callback,
    })
end

function Container:AddInput(text, placeholder, default, callback)
    return self._window:CreateWidget("Input", self._container, {
        text = text,
        placeholder = placeholder,
        default = default,
        callback = callback,
    })
end

function Container:AddSection(text, expanded)
    return self._window:CreateWidget("Section", self._container, {
        text = text,
        expanded = expanded,
    })
end

function Container:AddLabel(text, value, valueColor)
    return self._window:CreateWidget("Label", self._container, {
        text = text,
        value = value,
        valueColor = valueColor,
    })
end

function Container:AddStat(title, value, color)
    return self._window:CreateWidget("Stat", self._container, {
        title = title,
        value = value,
        color = color,
    })
end

function Container:AddTable(columns, maxRows)
    return self._window:CreateWidget("Table", self._container, {
        columns = columns,
        maxRows = maxRows,
    })
end

return Container
end

__BFS_MODULES["ui"] = function(require)
--[[
    ui/init.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    The window.

    A tab is a scrolling page; every widget is added to a page. The window
    owns the ScreenGui, the title bar, the tab strip and the toast layer.

    Widget refresh: widgets that show live data register a refresh
    function. The window calls all of them on an interval, so the
    dashboard keeps up with the game without every widget polling on its
    own.
]]

local Theme = require("ui.theme")
local Util = require("core.util")
local Container = require("ui.container")

local ToggleWidget = require("ui.widgets.toggle")
local SliderWidget = require("ui.widgets.slider")
local DropdownWidget = require("ui.widgets.dropdown")
local ButtonWidget = require("ui.widgets.button")
local InputWidget = require("ui.widgets.input")
local SectionWidget = require("ui.widgets.section")
local LabelWidget = require("ui.widgets.label")
local StatWidget = require("ui.widgets.stat")
local TableWidget = require("ui.widgets.table")
local NotifyWidget = require("ui.widgets.notify")

local Window = {}

Window.__index = Window

local Widgets = {
    Toggle = ToggleWidget,
    Slider = SliderWidget,
    Dropdown = DropdownWidget,
    Button = ButtonWidget,
    Input = InputWidget,
    Section = SectionWidget,
    Label = LabelWidget,
    Stat = StatWidget,
    Table = TableWidget,
}

--- Build a widget of the given kind. Both tabs and sections go through
--- here, which is why a section can hold the same widgets a page can.
function Window:CreateWidget(kind, parent, options)
    local module = Widgets[kind]
    if not module then
        error("unknown widget kind: " .. tostring(kind))
    end
    return module.Create(self, parent, options)
end

-- ═══════════════════════════════════════════════════════════════════════
-- TAB
-- ═══════════════════════════════════════════════════════════════════════

local Tab = setmetatable({}, Container)
Tab.__index = Tab

-- ═══════════════════════════════════════════════════════════════════════
-- WINDOW
-- ═══════════════════════════════════════════════════════════════════════

function Window.new(options)
    options = options or {}

    local self = setmetatable({
        _logger = options.logger,
        _title = options.title or "BLOX FRUITS SUITE",
        _version = options.version or "v12.0",
        _width = options.width or 560,
        _height = options.height or 480,
        _themeName = options.theme or "midnight",
        _accentName = options.accent or "cyan",
        _animations = options.animations ~= false,
        _screenGui = nil,
        _main = nil,
        _titleBar = nil,
        _tabStrip = nil,
        _content = nil,
        _tabs = {},
        _activeTab = nil,
        _refreshers = {},
        _notify = NotifyWidget.New({ logger = options.logger }),
        _minimized = false,
        _visible = true,
        _cleanup = options.cleanup,
    }, Window)

    self.Theme = Theme.Build(self._themeName, self._accentName)
    self.Animations = self._animations
    self.Logger = options.logger

    self:_build()
    return self
end

-- ── construction ─────────────────────────────────────────────────────────

function Window:_build()
    local theme = self.Theme

    local screenGui = Instance.new("ScreenGui")
    screenGui.Name = "BFS_Window_" .. tostring(math.random(100000, 999999))
    screenGui.ResetOnSpawn = false
    screenGui.DisplayOrder = 950
    screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling

    local ok, coreGui = pcall(function()
        return game:GetService("CoreGui")
    end)
    if ok then
        pcall(function()
            screenGui.Parent = coreGui
        end)
    end

    if not screenGui.Parent then
        local okPlayer, player = pcall(function()
            return game:GetService("Players").LocalPlayer
        end)
        if okPlayer and player then
            pcall(function()
                screenGui.Parent = player:WaitForChild("PlayerGui")
            end)
        end
    end

    self._screenGui = screenGui

    if self._cleanup then
        self._cleanup:trackInstance(screenGui, "window-gui")
    end

    -- main frame
    local main = Instance.new("Frame")
    main.Name = "Main"
    main.Size = UDim2.new(0, self._width, 0, self._height)
    main.Position = UDim2.new(0.5, -self._width / 2, 0.5, -self._height / 2)
    main.BackgroundColor3 = theme.background
    main.BorderSizePixel = 0
    main.ClipsDescendants = true
    main.Parent = screenGui

    local mainCorner = Instance.new("UICorner")
    mainCorner.CornerRadius = UDim.new(0, 12)
    mainCorner.Parent = main

    local mainStroke = Instance.new("UIStroke")
    mainStroke.Color = theme.border
    mainStroke.Thickness = 1
    mainStroke.Transparency = 0.4
    mainStroke.Parent = main

    self._main = main

    -- title bar
    local titleBar = Instance.new("Frame")
    titleBar.Name = "TitleBar"
    titleBar.Size = UDim2.new(1, 0, 0, 42)
    titleBar.BackgroundColor3 = theme.surface
    titleBar.BorderSizePixel = 0
    titleBar.Parent = main

    local titleCorner = Instance.new("UICorner")
    titleCorner.CornerRadius = UDim.new(0, 12)
    titleCorner.Parent = titleBar

    local titleFix = Instance.new("Frame")
    titleFix.Size = UDim2.new(1, 0, 0, 12)
    titleFix.Position = UDim2.new(0, 0, 1, -12)
    titleFix.BackgroundColor3 = theme.surface
    titleFix.BorderSizePixel = 0
    titleFix.Parent = titleBar

    local title = Instance.new("TextLabel")
    title.Size = UDim2.new(1, -190, 1, 0)
    title.Position = UDim2.new(0, 16, 0, 0)
    title.BackgroundTransparency = 1
    title.Text = self._title
    title.TextColor3 = theme.text
    title.Font = Enum.Font.GothamBold
    title.TextSize = 14
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.Parent = titleBar

    local version = Instance.new("TextLabel")
    version.Size = UDim2.new(0, 52, 0, 20)
    version.Position = UDim2.new(1, -158, 0.5, -10)
    version.BackgroundColor3 = theme.accent
    version.Text = self._version
    version.TextColor3 = Color3.fromRGB(255, 255, 255)
    version.Font = Enum.Font.GothamBold
    version.TextSize = 10
    version.Parent = titleBar

    local versionCorner = Instance.new("UICorner")
    versionCorner.CornerRadius = UDim.new(0, 5)
    versionCorner.Parent = version

    -- minimise and close buttons
    local minimize = Instance.new("TextButton")
    minimize.Name = "Minimize"
    minimize.Size = UDim2.new(0, 24, 0, 24)
    minimize.Position = UDim2.new(1, -100, 0.5, -12)
    minimize.BackgroundTransparency = 1
    minimize.Text = "-"
    minimize.TextColor3 = theme.textDim
    minimize.Font = Enum.Font.GothamBold
    minimize.TextSize = 16
    minimize.Parent = titleBar

    local close = Instance.new("TextButton")
    close.Name = "Close"
    close.Size = UDim2.new(0, 24, 0, 24)
    close.Position = UDim2.new(1, -68, 0.5, -12)
    close.BackgroundTransparency = 1
    close.Text = "x"
    close.TextColor3 = theme.textDim
    close.Font = Enum.Font.GothamBold
    close.TextSize = 14
    close.Parent = titleBar

    close.MouseButton1Click:Connect(function()
        self:Close()
    end)

    minimize.MouseButton1Click:Connect(function()
        self:ToggleMinimize()
    end)

    self._titleBar = titleBar

    -- tab strip
    local tabStrip = Instance.new("ScrollingFrame")
    tabStrip.Name = "TabStrip"
    tabStrip.Size = UDim2.new(1, -24, 0, 36)
    tabStrip.Position = UDim2.new(0, 12, 0, 50)
    tabStrip.BackgroundTransparency = 1
    tabStrip.BorderSizePixel = 0
    tabStrip.ScrollBarThickness = 2
    tabStrip.ScrollBarImageColor3 = theme.accent
    tabStrip.CanvasSize = UDim2.new(0, 0, 0, 0)
    tabStrip.AutomaticCanvasSize = Enum.AutomaticSize.X
    tabStrip.Parent = main

    local tabLayout = Instance.new("UIListLayout")
    tabLayout.FillDirection = Enum.FillDirection.Horizontal
    tabLayout.Padding = UDim.new(0, 6)
    tabLayout.SortOrder = Enum.SortOrder.LayoutOrder
    tabLayout.Parent = tabStrip

    self._tabStrip = tabStrip

    -- content area
    local content = Instance.new("Frame")
    content.Name = "Content"
    content.Size = UDim2.new(1, -24, 1, -96)
    content.Position = UDim2.new(0, 12, 0, 92)
    content.BackgroundColor3 = theme.surface
    content.BorderSizePixel = 0
    content.Parent = main

    local contentCorner = Instance.new("UICorner")
    contentCorner.CornerRadius = UDim.new(0, 10)
    contentCorner.Parent = content

    self._content = content

    self:_makeDraggable(titleBar, main)
end

function Window:_makeDraggable(handle, target)
    local dragging = false
    local startPos, startOffset

    handle.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging = true
            startPos = input.Position
            startOffset = target.Position
        end
    end)

    handle.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging = false
        end
    end)

    local ok, UserInputService = pcall(function()
        return game:GetService("UserInputService")
    end)
    if not ok then
        return
    end

    UserInputService.InputChanged:Connect(function(input)
        if dragging and input.UserInputType == Enum.UserInputType.MouseMovement then
            local delta = input.Position - startPos
            target.Position = UDim2.new(
                startOffset.X.Scale,
                startOffset.X.Offset + delta.X,
                startOffset.Y.Scale,
                startOffset.Y.Offset + delta.Y
            )
        end
    end)
end

-- ── tabs ─────────────────────────────────────────────────────────────────

function Window:AddTab(name)
    local theme = self.Theme

    local button = Instance.new("TextButton")
    button.Name = name
    button.LayoutOrder = #self._tabs + 1
    button.Size = UDim2.new(0, self._tabWidth or 128, 1, 0)
    button.BackgroundColor3 = theme.surface
    button.Text = name
    button.TextColor3 = theme.textDim
    button.Font = Enum.Font.GothamSemibold
    button.TextSize = 12
    button.BorderSizePixel = 0
    button.AutoButtonColor = false
    button.Parent = self._tabStrip

    local buttonCorner = Instance.new("UICorner")
    buttonCorner.CornerRadius = UDim.new(0, 7)
    buttonCorner.Parent = button

    local page = Instance.new("ScrollingFrame")
    page.Name = name .. "Page"
    page.Size = UDim2.new(1, 0, 1, 0)
    page.BackgroundTransparency = 1
    page.BorderSizePixel = 0
    page.ScrollBarThickness = 3
    page.ScrollBarImageColor3 = theme.accent
    page.Visible = false
    page.Parent = self._content

    local pageLayout = Instance.new("UIListLayout")
    pageLayout.Padding = UDim.new(0, 8)
    pageLayout.SortOrder = Enum.SortOrder.LayoutOrder
    pageLayout.Parent = page

    local pagePadding = Instance.new("UIPadding")
    pagePadding.PaddingTop = UDim.new(0, 14)
    pagePadding.PaddingLeft = UDim.new(0, 14)
    pagePadding.PaddingRight = UDim.new(0, 14)
    pagePadding.PaddingBottom = UDim.new(0, 14)
    pagePadding.Parent = page

    local tab = setmetatable({
        Name = name,
        Button = button,
        Page = page,
        _window = self,
        _container = page,
        _widgets = {},
    }, Tab)

    button.MouseButton1Click:Connect(function()
        self:SelectTab(tab)
    end)

    table.insert(self._tabs, tab)

    if not self._activeTab then
        self:SelectTab(tab)
    end

    return tab
end

function Window:SelectTab(tab)
    if not tab then
        return
    end

    local theme = self.Theme

    for _, other in ipairs(self._tabs) do
        local isActive = (other == tab)
        other.Page.Visible = isActive

        if self.Animations then
            self:Animate(other.Button, {
                BackgroundColor3 = isActive and theme.accent or theme.surface,
                TextColor3 = isActive and Color3.fromRGB(255, 255, 255) or theme.textDim,
            }, 0.18)
        else
            other.Button.BackgroundColor3 = isActive and theme.accent or theme.surface
            other.Button.TextColor3 = isActive and Color3.fromRGB(255, 255, 255) or theme.textDim
        end
    end

    self._activeTab = tab
end

function Window:ActiveTab()
    return self._activeTab
end

function Window:Tabs()
    return self._tabs
end

-- ── live refresh ─────────────────────────────────────────────────────────

--- Register a function that is called on every interface refresh.
function Window:AddRefresher(callback)
    table.insert(self._refreshers, callback)
    return function()
        for index = #self._refreshers, 1, -1 do
            if self._refreshers[index] == callback then
                table.remove(self._refreshers, index)
            end
        end
    end
end

function Window:Refresh()
    for _, refresher in ipairs(self._refreshers) do
        pcall(refresher)
    end
end

-- ── appearance ───────────────────────────────────────────────────────────

function Window:SetTheme(themeName, accentName)
    self._themeName = themeName or self._themeName
    self._accentName = accentName or self._accentName
    self.Theme = Theme.Build(self._themeName, self._accentName)
    self:_applyTheme()
end

function Window:_applyTheme()
    local theme = self.Theme

    if self._main then
        self._main.BackgroundColor3 = theme.background
        local stroke = self._main:FindFirstChildOfClass("UIStroke")
        if stroke then
            stroke.Color = theme.border
        end
    end
    if self._titleBar then
        self._titleBar.BackgroundColor3 = theme.surface
    end
    if self._content then
        self._content.BackgroundColor3 = theme.surface
    end

    for _, tab in ipairs(self._tabs) do
        local isActive = (tab == self._activeTab)
        tab.Button.BackgroundColor3 = isActive and theme.accent or theme.surface
        tab.Button.TextColor3 = isActive and Color3.fromRGB(255, 255, 255) or theme.textDim
    end
end

function Window:SetAnimations(enabled)
    self._animations = enabled and true or false
    self.Animations = self._animations
end

function Window:SetSize(width, height)
    self._width = width or self._width
    self._height = height or self._height
    if self._main then
        self._main.Size = UDim2.new(0, self._width, 0, self._height)
    end
end

function Window:SetTabWidth(width)
    self._tabWidth = width
    for _, tab in ipairs(self._tabs) do
        tab.Button.Size = UDim2.new(0, width, 1, 0)
    end
end

-- ── behaviour ────────────────────────────────────────────────────────────

function Window:Notify(title, message, kind)
    return self._notify:Show(title, message, kind)
end

function Window:SetNotificationsEnabled(enabled)
    self._notify:SetEnabled(enabled)
end

function Window:Toggle()
    self._visible = not self._visible
    if self._screenGui then
        self._screenGui.Enabled = self._visible
    end
    return self._visible
end

function Window:IsVisible()
    return self._visible
end

function Window:ToggleMinimize()
    self._minimized = not self._minimized
    if self._main then
        self._main.Size = UDim2.new(0, self._width, 0, self._minimized and 42 or self._height)
    end
    return self._minimized
end

function Window:IsMinimized()
    return self._minimized
end

--- Tween helper used by the widgets.
function Window:Animate(instance, properties, duration)
    return Util.tween(instance, properties, duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
end

function Window:Close()
    self._notify:Destroy()
    if self._screenGui then
        pcall(function()
            self._screenGui:Destroy()
        end)
        self._screenGui = nil
    end
    return true
end

return Window
end

__BFS_MODULES["ui.theme"] = function(require)
--[[
    ui/theme.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Theme definitions.

    A theme is a flat table of colours. The window reads the active theme
    from here and every widget pulls its colours from `window.Theme`, so
    switching themes restyles the whole interface without any widget
    needing to know about it.
]]

local Theme = {}

--- Accent colours the user can pick from.
Theme.ACCENTS = {
    { name = "Cyan",   value = Color3.fromRGB(0, 170, 255) },
    { name = "Blue",   value = Color3.fromRGB(60, 120, 255) },
    { name = "Purple", value = Color3.fromRGB(150, 80, 240) },
    { name = "Pink",   value = Color3.fromRGB(240, 80, 170) },
    { name = "Green",  value = Color3.fromRGB(40, 200, 110) },
    { name = "Yellow", value = Color3.fromRGB(240, 190, 50) },
    { name = "Orange", value = Color3.fromRGB(240, 130, 40) },
    { name = "Red",    value = Color3.fromRGB(230, 60, 70) },
}

Theme.ACCENT_NAMES = {}
for _, accent in ipairs(Theme.ACCENTS) do
    table.insert(Theme.ACCENT_NAMES, accent.name)
end

function Theme.AccentColor(name)
    for _, accent in ipairs(Theme.ACCENTS) do
        if accent.name:lower() == tostring(name):lower() then
            return accent.value
        end
    end
    return Theme.ACCENTS[1].value
end

--- Built in themes. `accent` is filled in from the user's choice.
Theme.THEMES = {
    midnight = {
        name = "Midnight",
        background = Color3.fromRGB(10, 11, 16),
        surface = Color3.fromRGB(20, 22, 30),
        surfaceAlt = Color3.fromRGB(28, 30, 40),
        border = Color3.fromRGB(44, 47, 60),
        text = Color3.fromRGB(238, 240, 248),
        textDim = Color3.fromRGB(140, 146, 165),
        success = Color3.fromRGB(40, 200, 110),
        danger = Color3.fromRGB(230, 60, 70),
        warning = Color3.fromRGB(240, 180, 50),
        shadow = Color3.fromRGB(0, 0, 0),
    },
    carbon = {
        name = "Carbon",
        background = Color3.fromRGB(16, 16, 16),
        surface = Color3.fromRGB(28, 28, 28),
        surfaceAlt = Color3.fromRGB(38, 38, 38),
        border = Color3.fromRGB(56, 56, 56),
        text = Color3.fromRGB(240, 240, 240),
        textDim = Color3.fromRGB(150, 150, 150),
        success = Color3.fromRGB(60, 200, 120),
        danger = Color3.fromRGB(240, 70, 70),
        warning = Color3.fromRGB(240, 190, 60),
        shadow = Color3.fromRGB(0, 0, 0),
    },
    ocean = {
        name = "Ocean",
        background = Color3.fromRGB(8, 20, 32),
        surface = Color3.fromRGB(14, 34, 52),
        surfaceAlt = Color3.fromRGB(20, 44, 66),
        border = Color3.fromRGB(30, 62, 90),
        text = Color3.fromRGB(232, 244, 252),
        textDim = Color3.fromRGB(130, 165, 190),
        success = Color3.fromRGB(50, 200, 160),
        danger = Color3.fromRGB(240, 90, 90),
        warning = Color3.fromRGB(240, 200, 80),
        shadow = Color3.fromRGB(0, 0, 0),
    },
    daylight = {
        name = "Daylight",
        background = Color3.fromRGB(238, 240, 245),
        surface = Color3.fromRGB(255, 255, 255),
        surfaceAlt = Color3.fromRGB(226, 230, 238),
        border = Color3.fromRGB(198, 204, 215),
        text = Color3.fromRGB(26, 30, 40),
        textDim = Color3.fromRGB(110, 118, 135),
        success = Color3.fromRGB(30, 160, 90),
        danger = Color3.fromRGB(210, 50, 60),
        warning = Color3.fromRGB(220, 160, 30),
        shadow = Color3.fromRGB(120, 126, 140),
    },
    ember = {
        name = "Ember",
        background = Color3.fromRGB(22, 12, 12),
        surface = Color3.fromRGB(36, 20, 18),
        surfaceAlt = Color3.fromRGB(48, 27, 24),
        border = Color3.fromRGB(70, 40, 34),
        text = Color3.fromRGB(248, 236, 230),
        textDim = Color3.fromRGB(168, 140, 130),
        success = Color3.fromRGB(210, 160, 60),
        danger = Color3.fromRGB(230, 70, 60),
        warning = Color3.fromRGB(240, 150, 50),
        shadow = Color3.fromRGB(0, 0, 0),
    },
}

Theme.NAMES = {}
for key, _ in pairs(Theme.THEMES) do
    table.insert(Theme.NAMES, key)
end
table.sort(Theme.NAMES)

--- Build the live theme table.
--- `themeName` is a key of Theme.THEMES, `accentName` a name of Theme.ACCENTS.
function Theme.Build(themeName, accentName)
    local base = Theme.THEMES[themeName] or Theme.THEMES.midnight

    local built = {}
    for key, value in pairs(base) do
        built[key] = value
    end

    built.accent = Theme.AccentColor(accentName)
    built.accentSoft = built.accent:Lerp(built.background, 0.55)
    built.key = themeName or "midnight"

    return built
end

return Theme
end

__BFS_MODULES["ui.tabs.about"] = function(require)
--[[
    ui/tabs/about.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    The About page.

    It is worth being explicit here about what the suite can and cannot
    do, because the v11 build advertised capabilities it did not have.
]]

local Tab = {}

function Tab.Create(window, suite)
    local tab = window:AddTab("About")

    local infoSection = tab:AddSection("Build")

    infoSection:AddLabel("Version", "v12.0.0")
    infoSection:AddLabel("Engine", "Luau (Roblox client)")
    local moduleLabel = infoSection:AddLabel("Modules", "0")
    infoSection:AddLabel("Documentation", "README.md in the archive")

    local statModules = infoSection:AddStat("Loaded modules", "0")

    -- ── capabilities ───────────────────────────────────────────────────
    local realSection = tab:AddSection("What actually works")
    realSection:AddLabel("Fruit ESP", "yes - reads live world models")
    realSection:AddLabel("Mob / boss / chest ESP", "yes - reads live world models")
    realSection:AddLabel("Auto farm and auto collect", "yes - needs an executor with input events")
    realSection:AddLabel("Gacha result tracking", "yes - listens to the game's own events")
    realSection:AddLabel("Fruit spawn tracking", "yes - observes the world")

    -- ── limits ─────────────────────────────────────────────────────────
    local limitSection = tab:AddSection("What it cannot do")
    limitSection:AddLabel("Change the server's drop rates", "no - the server decides")
    limitSection:AddLabel("Guarantee a mythical fruit", "no - nothing client side can")
    limitSection:AddLabel("Read client id / hardware id", "no - not attempted on purpose")

    local noteSection = tab:AddSection("Note")
    local note = noteSection:AddLabel("Statement", "")
    note:SetValue("Fair use only. You are responsible for your account.")

    window:AddRefresher(function()
        statModules:SetValue(#suite:ModuleNames())
        moduleLabel:SetValue(tostring(#suite:ModuleNames()))
    end)

    return tab
end

return Tab
end

__BFS_MODULES["ui.tabs.dashboard"] = function(require)
--[[
    ui/tabs/dashboard.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    The landing page: live player statistics, suite status and the most
    important switches.
]]

local Util = require("core.util")

local Tab = {}

function Tab.Create(window, suite)
    local tab = window:AddTab("Dashboard")
    local settings = suite:settings()
    local world = suite:Get("world")
    local luck = suite:Get("luck")

    -- ── player ──────────────────────────────────────────────────────────
    local playerSection = tab:AddSection("Player")

    local statLevel = playerSection:AddStat("Level", "-")
    local statBeli = playerSection:AddStat("Beli", "-")
    local statBounty = playerSection:AddStat("Bounty", "-")
    local statFruit = playerSection:AddStat("Equipped Fruit", "-")

    -- ── suite ──────────────────────────────────────────────────────────
    local suiteSection = tab:AddSection("Suite")

    local statUptime = suiteSection:AddStat("Uptime", "-")
    local statScans = suiteSection:AddStat("World Scans", "-")
    local statSpawns = suiteSection:AddStat("Fruits Tracked", "-")

    local statusLabel = suiteSection:AddLabel("Status", "starting...")
    local storageLabel = suiteSection:AddLabel("Settings storage", "-")

    -- ── quick actions ──────────────────────────────────────────────────
    local actionSection = tab:AddSection("Quick Actions")

    actionSection:AddButton("Rescan the world", "primary", function()
        world:Scanner():Scan()
        window:Notify("World", "Rescan finished", "info")
    end)

    actionSection:AddButton("Refresh ESP", "primary", function()
        local count = world:RefreshESP()
        window:Notify("World", string.format("%d entity label(s) drawn", count), "info")
    end)

    actionSection:AddButton("Save settings now", "primary", function()
        local ok = settings:save()
        window:Notify("Settings", ok and "Saved to disk" or "No writable file API", ok and "success" or "warning")
    end)

    -- ── live updates ───────────────────────────────────────────────────
    window:AddRefresher(function()
        local player = world:PlayerStats():Get()
        statLevel:SetValue(player.level)
        statBeli:SetValue(Util.formatNumber(player.beli))
        statBounty:SetValue(Util.formatNumber(player.bounty))
        statFruit:SetValue(player.fruit or "None")

        statUptime:SetValue(Util.formatDuration(suite:Uptime()))
        statScans:SetValue(world:Scanner():ScanCount())

        local luckStats = luck:GetStats()
        statSpawns:SetValue(luckStats.spawns.total)

        statusLabel:SetValue(string.format("%d modules | %d tasks",
            #suite:ModuleNames(), suite:Snapshot().tasks))

        storageLabel:SetValue(settings:isPersistent() and ("file: " .. settings:fileName()) or "in-memory only")
    end)

    return tab
end

return Tab
end

__BFS_MODULES["ui.tabs.farm"] = function(require)
--[[
    ui/tabs/farm.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    The Farm page: the automation loops and their live state.
]]

local Tab = {}

function Tab.Create(window, suite)
    local tab = window:AddTab("Farm")
    local settings = suite:settings()
    local world = suite:Get("world")

    -- ── auto farm ──────────────────────────────────────────────────────
    local farmSection = tab:AddSection("Auto farm")

    farmSection:AddToggle("Enable auto farm", false, function(state)
        settings:set("farm.autoFarm", state)
        window:Notify("Farm", state and "Auto farm started" or "Auto farm stopped", state and "success" or "info")
    end)

    farmSection:AddSlider("Target level (0 = follow yours)", 0, 3000, 0, 10, "", function(value)
        settings:set("farm.targetLevel", value)
    end)

    farmSection:AddSlider("Attack range", 3, 60, 12, 1, " st", function(value)
        settings:set("farm.attackRange", value)
    end)

    farmSection:AddToggle("Safe mode", true, function(state)
        settings:set("farm.safeMode", state)
    end)

    farmSection:AddSlider("Stop below health", 0, 100, 30, 5, "%", function(value)
        settings:set("farm.safeHealth", value)
    end)

    local statFarmState = farmSection:AddStat("State", "idle")
    local statFarmTarget = farmSection:AddStat("Current target", "-")
    local statFarmKills = farmSection:AddStat("Kills this session", "0")

    -- ── auto collect ───────────────────────────────────────────────────
    local collectSection = tab:AddSection("Auto collect")

    collectSection:AddToggle("Enable auto collect", false, function(state)
        settings:set("farm.autoCollect", state)
        window:Notify("Farm", state and "Auto collect started" or "Auto collect stopped", state and "success" or "info")
    end)

    local statCollectState = collectSection:AddStat("State", "idle")
    local statCollected = collectSection:AddStat("Collected", "0")
    local statCollectLast = collectSection:AddStat("Last fruit", "-")

    -- ── auto quest ─────────────────────────────────────────────────────
    local questSection = tab:AddSection("Auto quest")

    questSection:AddToggle("Enable auto quest", false, function(state)
        settings:set("farm.autoQuest", state)
        window:Notify("Farm", state and "Auto quest started" or "Auto quest stopped", state and "success" or "info")
    end)

    local statQuestState = questSection:AddStat("State", "idle")
    local statQuestGiver = questSection:AddStat("Quest giver", "-")
    local statQuestDone = questSection:AddStat("Quests done", "0")

    -- ── input ──────────────────────────────────────────────────────────
    local inputSection = tab:AddSection("Input backend")

    local statInput = inputSection:AddStat("Click method", "unknown")
    local inputNote = inputSection:AddLabel("Note", "")
    inputNote:SetValue("Attacks need an executor that can send input events")

    -- ── live updates ───────────────────────────────────────────────────
    window:AddRefresher(function()
        local stats = world:GetStats()

        statFarmState:SetValue(stats.autoFarm.state)
        statFarmTarget:SetValue(stats.autoFarm.target or "-")
        statFarmKills:SetValue(stats.autoFarm.kills)

        statCollectState:SetValue(stats.autoCollect.state)
        statCollected:SetValue(stats.autoCollect.collected)
        statCollectLast:SetValue(stats.autoCollect.lastCollected or "-")

        statQuestState:SetValue(stats.autoQuest.state)
        statQuestGiver:SetValue(stats.autoQuest.questGiver or "-")
        statQuestDone:SetValue(stats.autoQuest.completed)

        statInput:SetValue(stats.input.method or "unknown")
    end)

    return tab
end

return Tab
end

__BFS_MODULES["ui.tabs.luck"] = function(require)
--[[
    ui/tabs/luck.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    The Luck page.

    Everything here is labelled for what it actually is:
        * the observed numbers come from the real game (spawn tracker and
          gacha tracker)
        * the modelled odds are community estimates
        * the roll button drives the suite's own simulator, it cannot
          change what the server hands you
]]

local Rarity = require("luck.rarity")
local Fruits = require("data.fruits")
local Util = require("core.util")

local Tab = {}

function Tab.Create(window, suite)
    local tab = window:AddTab("Luck")
    local settings = suite:settings()
    local luck = suite:Get("luck")
    local engine = luck:Engine()

    -- ── real observations ──────────────────────────────────────────────
    local realSection = tab:AddSection("Observed in this server")

    local statSpawns = realSection:AddStat("Fruits seen", "0")
    local statActive = realSection:AddStat("Fruits alive now", "0")
    local statGacha = realSection:AddStat("Gacha results", "0")
    local statRating = realSection:AddStat("Luck rating", "no data")

    local historyTable = realSection:AddTable({
        { name = "Fruit", width = 0.34 },
        { name = "Rarity", width = 0.3 },
        { name = "Source", width = 0.36 },
    }, 6)

    -- ── engine ─────────────────────────────────────────────────────────
    local engineSection = tab:AddSection("Roll engine")

    local statRolls = engineSection:AddStat("Modelled rolls", "0")
    local statLast = engineSection:AddStat("Last roll", "-")
    local statEffective = engineSection:AddStat("Mythic chance (effective)", "-")

    local modeDropdown = engineSection:AddDropdown("Table", {
        { name = "World spawn" },
        { name = "Gacha" },
    }, "World spawn", function(name)
        luck:SetMode(name == "Gacha" and "gacha" or "spawn")
        window:Notify("Luck", "Switched to the " .. name .. " table", "info")
    end)

    local multiplierSlider = engineSection:AddSlider("Luck multiplier", 1, 10, 2, 0.5, "x", function(value)
        settings:set("luck.multiplier", value)
    end)

    engineSection:AddButton("Roll once (simulated)", "primary", function()
        local result = luck:Roll()
        if result then
            window:Notify("Roll", string.format("%s (%s)", result.fruit, result.rarity), "success")
        end
    end)

    engineSection:AddButton("Roll 100 (simulated)", "primary", function()
        luck:Roll()
        luck:Roll()
        engine:RollMany(98)
        window:Notify("Roll", "100 simulated rolls complete", "info")
    end)

    engineSection:AddButton("Reset statistics", "danger", function()
        luck:Reset()
        window:Notify("Luck", "Statistics reset", "warning")
    end)

    -- ── odds ───────────────────────────────────────────────────────────
    local oddsSection = tab:AddSection("Estimated odds")

    local labelCommon = oddsSection:AddLabel("Common", "-")
    local labelUncommon = oddsSection:AddLabel("Uncommon", "-")
    local labelRare = oddsSection:AddLabel("Rare", "-")
    local labelLegendary = oddsSection:AddLabel("Legendary", "-")
    local labelMythic = oddsSection:AddLabel("Mythic", "-")

    local noteLabel = oddsSection:AddLabel("Note", "")
    noteLabel:SetValue("Community estimates, not published rates")

    -- ── client hook ────────────────────────────────────────────────────
    local hookSection = tab:AddSection("Client-side roll hook")

    local hookToggle = hookSection:AddToggle("Enable client roll bias", false, function(state)
        if state then
            luck:ClientRoll():Enable()
            window:Notify("Luck", "Client bias ON - cosmetic only", "warning")
        else
            luck:ClientRoll():Disable()
            window:Notify("Luck", "Client bias OFF", "info")
        end
    end)

    local hookLabel = hookSection:AddLabel("Status", "disabled")
    local hookHitLabel = hookSection:AddLabel("Intercepted calls", "0")

    -- ── live updates ───────────────────────────────────────────────────
    window:AddRefresher(function()
        local stats = luck:GetStats()

        statSpawns:SetValue(stats.spawns.total)
        statActive:SetValue(stats.spawns.active)
        statGacha:SetValue(stats.gacha.total)
        statRating:SetValue(stats.engine.luckRating or "no data")

        statRolls:SetValue(stats.engine.totalRolls)
        statLast:SetValue(stats.engine.lastResult
            and (stats.engine.lastResult.fruit .. " / " .. stats.engine.lastResult.rarity)
            or "-")

        statEffective:SetValue(string.format("%.2f%%", engine:EffectiveChance("Mythic")))

        -- the observed history
        local rows = {}
        local spawnHistory = luck:SpawnTracker():History()
        local gachaHistory = luck:GachaTracker():History()

        for index = #spawnHistory, 1, -1 do
            rows[#rows + 1] = { spawnHistory[index].fruit, spawnHistory[index].rarity, "world spawn" }
            if #rows >= 6 then
                break
            end
        end
        for index = #gachaHistory, 1, -1 do
            rows[#rows + 1] = { gachaHistory[index].fruit, gachaHistory[index].rarity, "gacha" }
            if #rows >= 6 then
                break
            end
        end
        historyTable:SetRows(rows)

        -- odds
        local weights = engine:BaseWeights()
        labelCommon:SetValue(string.format("%.2f%%", Rarity.Chance(weights, "Common")))
        labelUncommon:SetValue(string.format("%.2f%%", Rarity.Chance(weights, "Uncommon")))
        labelRare:SetValue(string.format("%.2f%%", Rarity.Chance(weights, "Rare")))
        labelLegendary:SetValue(string.format("%.2f%%", Rarity.Chance(weights, "Legendary")))
        labelMythic:SetValue(string.format("%.2f%%", Rarity.Chance(weights, "Mythic")))

        -- client hook
        local clientStats = stats.clientRoll or {}
        hookLabel:SetValue(clientStats.enabled and "enabled" or "disabled")
        hookHitLabel:SetValue(tostring(clientStats.hits or 0))
    end)

    -- keep the widgets in sync with the stored settings
    multiplierSlider:SetValue(settings:get("luck.multiplier", 2), true)
    local mode = luck:GetMode()
    modeDropdown:SetValue(mode == "gacha" and "Gacha" or "World spawn", true)
    hookToggle:SetValue(luck:ClientRoll():IsEnabled(), true)

    return tab
end

return Tab
end

__BFS_MODULES["ui.tabs.settings"] = function(require)
--[[
    ui/tabs/settings.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    The Settings page: appearance, keybinds and storage.
]]

local Theme = require("ui.theme")
local Util = require("core.util")

local Tab = {}

function Tab.Create(window, suite)
    local tab = window:AddTab("Settings")
    local settings = suite:settings()
    local hotkeys = suite:hotkeys()

    -- ── appearance ─────────────────────────────────────────────────────
    local lookSection = tab:AddSection("Appearance")

    lookSection:AddDropdown("Theme", Theme.NAMES, settings:get("general.theme", "midnight"), function(name)
        settings:set("general.theme", name)
        window:SetTheme(name, settings:get("general.accent", "cyan"))
    end)

    lookSection:AddDropdown("Accent", Theme.ACCENT_NAMES, settings:get("general.accent", "cyan"), function(name)
        settings:set("general.accent", name)
        window:SetTheme(settings:get("general.theme", "midnight"), name)
    end)

    lookSection:AddSlider("Transparency", 0, 90, 0, 5, "%", function(value)
        settings:set("general.transparency", value)
        if window._main then
            window._main.BackgroundTransparency = value / 100
        end
    end)

    lookSection:AddSlider("Window width", 420, 900, settings:get("ui.windowWidth", 560), 20, " px", function(value)
        settings:set("ui.windowWidth", value)
        window:SetSize(value, settings:get("ui.windowHeight", 480))
    end)

    lookSection:AddSlider("Window height", 320, 800, settings:get("ui.windowHeight", 480), 20, " px", function(value)
        settings:set("ui.windowHeight", value)
        window:SetSize(settings:get("ui.windowWidth", 560), value)
    end)

    lookSection:AddToggle("Animations", true, function(state)
        settings:set("ui.animations", state)
        window:SetAnimations(state)
    end)

    lookSection:AddToggle("Toasts", true, function(state)
        settings:set("general.notifications", state)
        window:SetNotificationsEnabled(state)
    end)

    -- ── keybinds ───────────────────────────────────────────────────────
    local bindSection = tab:AddSection("Keybinds")

    local bindList = bindSection:AddTable({
        { name = "Action", width = 0.6 },
        { name = "Key", width = 0.4 },
    }, 6)

    bindSection:AddButton("Rebind the interface toggle", "primary", function()
        window:Notify("Keybinds", "Press a key now...", "info")
        self._rebinding = true

        local ok, UserInputService = pcall(function()
            return game:GetService("UserInputService")
        end)
        if not ok then
            self._rebinding = false
            return
        end

        local connection
        connection = UserInputService.InputBegan:Connect(function(input)
            if not self._rebinding then
                connection:Disconnect()
                return
            end
            if input.UserInputType ~= Enum.UserInputType.Keyboard then
                return
            end
            self._rebinding = false
            connection:Disconnect()

            hotkeys:setKey("toggle_ui", input.KeyCode)
            settings:set("general.keybind", input.KeyCode)
            window:Notify("Keybinds", "Interface toggle is now " .. hotkeys:keyName(input.KeyCode), "success")
        end)
    end)

    -- ── storage ────────────────────────────────────────────────────────
    local storageSection = tab:AddSection("Storage")

    local statStorage = storageSection:AddStat("Settings file", "-")
    local statPersistent = storageSection:AddStat("Persistence", "-")

    storageSection:AddButton("Save now", "primary", function()
        local ok = settings:save()
        window:Notify("Settings", ok and "Saved" or "No writable file API available", ok and "success" or "warning")
    end)

    storageSection:AddButton("Restore defaults", "warning", function()
        settings:reset()
        window:Notify("Settings", "Defaults restored", "info")
        window:SetTheme(settings:get("general.theme", "midnight"), settings:get("general.accent", "cyan"))
    end)

    storageSection:AddButton("Delete the settings file", "danger", function()
        settings:clear()
        window:Notify("Settings", "Settings file removed", "warning")
    end)

    -- ── live updates ───────────────────────────────────────────────────
    window:AddRefresher(function()
        local rows = {}
        for _, bind in ipairs(hotkeys:list()) do
            rows[#rows + 1] = { bind.name, hotkeys:keyName(bind.key) }
        end
        bindList:SetRows(rows)

        statStorage:SetValue(settings:fileName())
        statPersistent:SetValue(settings:isPersistent() and "yes" or "no (in-memory)")
    end)

    return tab
end

return Tab
end

__BFS_MODULES["ui.tabs.stats"] = function(require)
--[[
    ui/tabs/stats.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    The Statistics page: the raw numbers the suite has collected.
]]

local Util = require("core.util")

local Tab = {}

function Tab.Create(window, suite)
    local tab = window:AddTab("Statistics")
    local luck = suite:Get("luck")
    local world = suite:Get("world")

    -- ── runtime ────────────────────────────────────────────────────────
    local runtimeSection = tab:AddSection("Runtime")

    local statUptime = runtimeSection:AddStat("Uptime", "-")
    local statModules = runtimeSection:AddStat("Modules", "-")
    local statTasks = runtimeSection:AddStat("Scheduler tasks", "-")
    local statBinds = runtimeSection:AddStat("Keybinds", "-")
    local statFps = runtimeSection:AddStat("Frame rate", "-")

    -- ── luck ───────────────────────────────────────────────────────────
    local luckSection = tab:AddSection("Luck engine")

    local statRolls = luckSection:AddStat("Modelled rolls", "0")
    local statObserved = luckSection:AddStat("Observed results", "0")
    local statZ = luckSection:AddStat("Luck z-score", "-")
    local statConfidence = luckSection:AddStat("Confidence", "-")
    local statMean = luckSection:AddStat("Mean rarity rank", "-")

    local distributionTable = luckSection:AddTable({
        { name = "Rarity", width = 0.4 },
        { name = "Count", width = 0.28 },
        { name = "Share", width = 0.32 },
    }, 5)

    -- ── world ──────────────────────────────────────────────────────────
    local worldSection = tab:AddSection("World")

    local statScans = worldSection:AddStat("Scans", "0")
    local statScanTime = worldSection:AddStat("Avg scan time", "-")
    local statEntities = worldSection:AddStat("Entities tracked", "-")

    -- ── live updates ───────────────────────────────────────────────────
    local frameCount = 0
    local lastFpsSample = os.clock()
    local fps = 0

    window:AddRefresher(function()
        frameCount = frameCount + 1
        local now = os.clock()
        if now - lastFpsSample >= 1 then
            fps = frameCount / (now - lastFpsSample)
            frameCount = 0
            lastFpsSample = now
        end

        local snapshot = suite:Snapshot()
        statUptime:SetValue(Util.formatDuration(snapshot.uptime))
        statModules:SetValue(snapshot.modules)
        statTasks:SetValue(snapshot.tasks)
        statBinds:SetValue(snapshot.bindings)
        statFps:SetValue(string.format("%.0f", fps))

        local luckStats = luck:GetStats()
        statRolls:SetValue(luckStats.engine.totalRolls)
        statObserved:SetValue(luckStats.spawns.total + luckStats.gacha.total)
        statZ:SetValue(string.format("%+.2f", luckStats.engine.luckZScore or 0))
        statConfidence:SetValue(string.format("%.0f%%", luckStats.engine.confidence or 0))
        statMean:SetValue(string.format("%.2f", luckStats.engine.observedMean or 0))

        local rows = {}
        for rarity, data in pairs(luckStats.engine.distribution or {}) do
            rows[#rows + 1] = { rarity, data.count, string.format("%.1f%%", data.percent) }
        end
        table.sort(rows, function(a, b)
            return a[1] < b[1]
        end)
        distributionTable:SetRows(rows)

        local worldStats = world:GetStats()
        statScans:SetValue(worldStats.scanCount)
        statScanTime:SetValue(string.format("%.0f ms", (worldStats.scanDuration or 0) * 1000))
        statEntities:SetValue(worldStats.counts.fruit + worldStats.counts.mob
            + worldStats.counts.boss + worldStats.counts.chest + worldStats.counts.npc)
    end)

    return tab
end

return Tab
end

__BFS_MODULES["ui.tabs.world"] = function(require)
--[[
    ui/tabs/world.lua
    BLOX FRUITS SUITE v12.0
