    -- ── ESP ────────────────────────────────────────────────────────────
    local espSection = tab:AddSection("ESP layers")

    local espToggles = {}

    local function addEspToggle(label, path)
        local widget = espSection:AddToggle(label, false, function(state)
            settings:set(path, state)
        end)
        espToggles[path] = widget
        return widget
    end

    addEspToggle("Fruit", "world.fruitESP")
    addEspToggle("Mobs", "world.mobESP")
    addEspToggle("Bosses", "world.bossESP")
    addEspToggle("Chests", "world.chestESP")
    addEspToggle("NPCs", "world.npcESP")

    espSection:AddSlider("Max objects", 25, 500, 150, 25, "", function(value)
        settings:set("world.maxESP", value)
    end)

    -- ── counters ───────────────────────────────────────────────────────
    local counterSection = tab:AddSection("Entities in the world")

    local statFruit = counterSection:AddStat("Fruits", "0")
    local statMob = counterSection:AddStat("Mobs", "0")
    local statBoss = counterSection:AddStat("Bosses", "0")
    local statChest = counterSection:AddStat("Chests", "0")
    local statNpc = counterSection:AddStat("NPCs", "0")
    local statScan = counterSection:AddStat("Last scan", "-")

    -- ── fast travel ────────────────────────────────────────────────────
    local travelSection = tab:AddSection("Fast travel")

    local travelInput = travelSection:AddInput("Destination", "e.g. Blox Fruit Dealer", "", function(text)
        if text == "" then
            return
        end
        local ok = world:TravelTo(text)
        window:Notify("Travel", ok and ("Travelled to " .. text) or ("No NPC matching '" .. text .. "'"),
            ok and "success" or "error")
    end)

    travelSection:AddButton("Go to the fruit dealer", "primary", function()
        local ok = world:TravelTo("Blox Fruit Dealer")
        window:Notify("Travel", ok and "Travelled" or "No fruit dealer in range", ok and "success" or "error")
    end)

    travelSection:AddButton("Go to the gacha NPC", "primary", function()
        local ok = world:TravelTo("Gacha")
        window:Notify("Travel", ok and "Travelled" or "No gacha NPC in range", ok and "success" or "error")
    end)

    -- ── live updates ───────────────────────────────────────────────────
    window:AddRefresher(function()
        local stats = world:GetStats()
        statFruit:SetValue(stats.counts.fruit)
        statMob:SetValue(stats.counts.mob)
        statBoss:SetValue(stats.counts.boss)
        statChest:SetValue(stats.counts.chest)
        statNpc:SetValue(stats.counts.npc)
        statScan:SetValue(string.format("%.0f ms", (stats.scanDuration or 0) * 1000))
    end)

    -- sync the toggles with the stored settings
    for path, widget in pairs(espToggles) do
        widget:SetValue(settings:get(path, false), true)
    end

    return tab
end

return Tab
end

__BFS_MODULES["ui.widgets.button"] = function(require)
--[[
    ui/widgets/button.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    A styled action button.
]]

local Widget = {}

Widget.__index = Widget

function Widget.Create(window, parent, options)
    options = options or {}

    local theme = window.Theme
    local self = setmetatable({}, Widget)

    local style = options.style or "primary"

    local function styleColor()
        if style == "primary" then
            return theme.accent
        elseif style == "danger" then
            return theme.danger
        elseif style == "warning" then
            return theme.warning
        elseif style == "success" then
            return theme.success
        end
        return theme.surface
    end

    local button = Instance.new("TextButton")
    button.Name = "Button_" .. (options.text or "")
    button.Size = UDim2.new(1, 0, 0, 38)
    button.BackgroundColor3 = styleColor()
    button.Text = options.text or "Button"
    button.TextColor3 = Color3.fromRGB(255, 255, 255)
    button.Font = Enum.Font.GothamBold
    button.TextSize = 13
    button.BorderSizePixel = 0
    button.AutoButtonColor = false
    button.Parent = parent

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 8)
    corner.Parent = button

    local base = styleColor()

    button.MouseEnter:Connect(function()
        if window.Animations then
            window:Animate(button, { BackgroundColor3 = base:Lerp(Color3.fromRGB(255, 255, 255), 0.18) }, 0.15)
        end
    end)

    button.MouseLeave:Connect(function()
        if window.Animations then
            window:Animate(button, { BackgroundColor3 = base }, 0.15)
        end
    end)

    button.MouseButton1Click:Connect(function()
        if options.callback then
            local ok, err = pcall(options.callback)
            if not ok and window.Logger then
                window.Logger:warn("Button '%s' failed: %s", options.text, tostring(err))
            end
        end
    end)

    self.Element = button

    function self:SetText(text)
        button.Text = text
    end

    function self:SetEnabled(enabled)
        button.AutoButtonColor = enabled and true or false
        button.BackgroundColor3 = enabled and base or theme.surface
        button.TextColor3 = enabled and Color3.fromRGB(255, 255, 255) or theme.textDim
    end

    function self:Destroy()
        pcall(function()
            button:Destroy()
        end)
    end

    return self
end

return Widget
end

__BFS_MODULES["ui.widgets.dropdown"] = function(require)
--[[
    ui/widgets/dropdown.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    A dropdown selector with a scrollable option list.
]]

local Widget = {}

Widget.__index = Widget

function Widget.Create(window, parent, options)
    options = options or {}

    local theme = window.Theme
    local self = setmetatable({}, Widget)

    local items = options.options or {}
    local selected = options.default or (items[1] and items[1].name or nil)

    local container = Instance.new("Frame")
    container.Name = "Dropdown_" .. (options.text or "")
    container.Size = UDim2.new(1, 0, 0, 44)
    container.BackgroundColor3 = theme.surfaceAlt
    container.BorderSizePixel = 0
    container.Parent = parent

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 8)
    corner.Parent = container

    local label = Instance.new("TextLabel")
    label.Name = "Label"
    label.Size = UDim2.new(1, -70, 1, 0)
    label.Position = UDim2.new(0, 12, 0, 0)
    label.BackgroundTransparency = 1
    label.Text = options.text or "Select"
    label.TextColor3 = theme.text
    label.Font = Enum.Font.Gotham
    label.TextSize = 13
    label.TextXAlignment = Enum.TextXAlignment.Left
    label.Parent = container

    local button = Instance.new("TextButton")
    button.Name = "Button"
    button.Size = UDim2.new(0, 140, 0, 28)
    button.Position = UDim2.new(1, -152, 0.5, -14)
    button.BackgroundColor3 = theme.surface
    button.Text = tostring(selected or "-")
    button.TextColor3 = theme.text
    button.Font = Enum.Font.GothamSemibold
    button.TextSize = 12
    button.BorderSizePixel = 0
    button.AutoButtonColor = false
    button.Parent = container

    local buttonCorner = Instance.new("UICorner")
    buttonCorner.CornerRadius = UDim.new(0, 6)
    buttonCorner.Parent = button

    local arrow = Instance.new("TextLabel")
    arrow.Name = "Arrow"
    arrow.Size = UDim2.new(0, 20, 1, 0)
    arrow.Position = UDim2.new(1, -20, 0, 0)
    arrow.BackgroundTransparency = 1
    arrow.Text = "v"
    arrow.TextColor3 = theme.textDim
    arrow.Font = Enum.Font.GothamBold
    arrow.TextSize = 13
    arrow.Parent = button

    -- option list
    local list = Instance.new("ScrollingFrame")
    list.Name = "Options"
    list.Size = UDim2.new(0, 140, 0, 0)
    list.Position = UDim2.new(1, -152, 1, 6)
    list.BackgroundColor3 = theme.surface
    list.BorderSizePixel = 0
    list.ScrollBarThickness = 3
    list.ScrollBarImageColor3 = theme.accent
    list.Visible = false
    list.ZIndex = 10
    list.Parent = container

    local listCorner = Instance.new("UICorner")
    listCorner.CornerRadius = UDim.new(0, 6)
    listCorner.Parent = list

    local listLayout = Instance.new("UIListLayout")
    listLayout.Padding = UDim.new(0, 2)
    listLayout.SortOrder = Enum.SortOrder.LayoutOrder
    listLayout.Parent = list

    local listPadding = Instance.new("UIPadding")
    listPadding.PaddingTop = UDim.new(0, 4)
    listPadding.PaddingBottom = UDim.new(0, 4)
    listPadding.Parent = list

    local optionButtons = {}

    local function close()
        list.Visible = false
        arrow.Text = "v"
    end

    local function open()
        list.Visible = true
        arrow.Text = "^"
    end

    local function select(item)
        selected = item.name
        button.Text = item.name
        close()
        if options.callback then
            local ok, err = pcall(options.callback, item.name, item)
            if not ok and window.Logger then
                window.Logger:warn("Dropdown '%s' callback failed: %s", options.text, tostring(err))
            end
        end
    end

    for index, item in ipairs(items) do
        local entry = item
        if type(entry) == "string" then
            entry = { name = entry }
        end

        local optionButton = Instance.new("TextButton")
        optionButton.Name = entry.name
        optionButton.LayoutOrder = index
        optionButton.Size = UDim2.new(1, -6, 0, 26)
        optionButton.BackgroundColor3 = theme.surface
        optionButton.Text = entry.name
        optionButton.TextColor3 = theme.textDim
        optionButton.Font = Enum.Font.Gotham
        optionButton.TextSize = 12
        optionButton.TextXAlignment = Enum.TextXAlignment.Left
        optionButton.BorderSizePixel = 0
        optionButton.AutoButtonColor = false
        optionButton.ZIndex = 11
        optionButton.Parent = list

        local optionCorner = Instance.new("UICorner")
        optionCorner.CornerRadius = UDim.new(0, 4)
        optionCorner.Parent = optionButton

        optionButton.MouseButton1Click:Connect(function()
            select(entry)
        end)

        optionButton.MouseEnter:Connect(function()
            optionButton.BackgroundColor3 = theme.accent
            optionButton.TextColor3 = Color3.fromRGB(255, 255, 255)
        end)

        optionButton.MouseLeave:Connect(function()
            optionButton.BackgroundColor3 = theme.surface
            optionButton.TextColor3 = theme.textDim
        end)

        table.insert(optionButtons, optionButton)
    end

    local function resize()
        local count = math.min(#optionButtons, 8)
        list.Size = UDim2.new(0, 140, 0, count * 28)
    end
    resize()

    button.MouseButton1Click:Connect(function()
        if list.Visible then
            close()
        else
            open()
        end
    end)

    self.Element = container
    self.List = list

    function self:GetValue()
        return selected
    end

    function self:SetValue(name, silent)
        for _, item in ipairs(items) do
            local entry = item
            if type(entry) == "string" then
                entry = { name = entry }
            end
            if entry.name == name then
                selected = name
                button.Text = name
                if not silent and options.callback then
                    pcall(options.callback, name, entry)
                end
                return true
            end
        end
        return false
    end

    function self:SetOptions(newItems)
        items = newItems or {}
    end

    function self:Destroy()
        pcall(function()
            container:Destroy()
        end)
    end

    return self
end

return Widget
end

