__BFS_MODULES["ui.widgets.notify"] = function(require)
--[[
    ui/widgets/notify.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Toast notifications.

    The toast layer lives in its own ScreenGui so it survives the main
    window being closed, and toasts clean themselves up.
]]

local Widget = {}

Widget.__index = Widget

Widget.KINDS = {
    info = "accent",
    success = "success",
    warning = "warning",
    error = "danger",
}

function Widget.New(options)
    options = options or {}

    local self = setmetatable({
        _logger = options.logger,
        _screenGui = nil,
        _toasts = {},
        _enabled = true,
        _maxToasts = options.maxToasts or 4,
        _duration = options.duration or 3.5,
    }, Widget)

    return self
end

function Widget:SetEnabled(enabled)
    self._enabled = enabled and true or false
end

function Widget:_createScreenGui()
    if self._screenGui then
        return self._screenGui
    end

    local screenGui = Instance.new("ScreenGui")
    screenGui.Name = "BFS_Toasts_" .. tostring(math.random(100000, 999999))
    screenGui.ResetOnSpawn = false
    screenGui.DisplayOrder = 1000
    screenGui.IgnoreGuiInset = true
    screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling

    local ok, coreGui = pcall(function()
        return game:GetService("CoreGui")
    end)
    if ok then
        pcall(function()
            screenGui.Parent = coreGui
        end)
    end

    if not screenGui.Parent then
        local okPlayer, player = pcall(function()
            return game:GetService("Players").LocalPlayer
        end)
        if okPlayer and player then
            pcall(function()
                screenGui.Parent = player:WaitForChild("PlayerGui")
            end)
        end
    end

    self._screenGui = screenGui
    return screenGui
end

--- Show a toast.
--- kind: "info" | "success" | "warning" | "error"
function Widget:Show(title, message, kind)
    if not self._enabled then
        return nil
    end

    self:_createScreenGui()
    if not self._screenGui then
        return nil
    end

    local theme = require("ui.theme").Build("midnight", "cyan")
    local colorKey = Widget.KINDS[kind or "info"] or "accent"
    local color = theme[colorKey] or theme.accent

    local holder = Instance.new("Frame")
    holder.Name = "Toast"
    holder.Size = UDim2.new(0, 300, 0, 58)
    holder.Position = UDim2.new(1, -312, 0, -20)
    holder.BackgroundColor3 = theme.surface
    holder.BackgroundTransparency = 0.05
    holder.BorderSizePixel = 0
    holder.Parent = self._screenGui

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 10)
    corner.Parent = holder

    local stroke = Instance.new("Frame")
    stroke.Size = UDim2.new(0, 4, 1, 0)
    stroke.BackgroundColor3 = color
    stroke.BorderSizePixel = 0
    stroke.Parent = holder

    local strokeCorner = Instance.new("UICorner")
    strokeCorner.CornerRadius = UDim.new(0, 2)
    strokeCorner.Parent = stroke

    local titleLabel = Instance.new("TextLabel")
    titleLabel.Size = UDim2.new(1, -24, 0, 20)
    titleLabel.Position = UDim2.new(0, 14, 0, 8)
    titleLabel.BackgroundTransparency = 1
    titleLabel.Text = tostring(title or "")
    titleLabel.TextColor3 = theme.text
    titleLabel.Font = Enum.Font.GothamBold
    titleLabel.TextSize = 13
    titleLabel.TextXAlignment = Enum.TextXAlignment.Left
    titleLabel.Parent = holder

    local messageLabel = Instance.new("TextLabel")
    messageLabel.Size = UDim2.new(1, -24, 0, 26)
    messageLabel.Position = UDim2.new(0, 14, 0, 28)
    messageLabel.BackgroundTransparency = 1
    messageLabel.Text = tostring(message or "")
    messageLabel.TextColor3 = theme.textDim
    messageLabel.Font = Enum.Font.Gotham
    messageLabel.TextSize = 11
    messageLabel.TextXAlignment = Enum.TextXAlignment.Left
    messageLabel.TextWrapped = true
    messageLabel.Parent = holder

    -- stack the toasts
    local index = #self._toasts
    for _, toast in ipairs(self._toasts) do
        toast.holder:Destroy()
    end
    self._toasts = {}

    local offset = 0
    for _, toast in ipairs(self._toasts) do
        offset = offset + 62
    end
    index = 0

    -- position the new toast
    holder.Position = UDim2.new(1, -312, 0, -20 + offset)

    local ok, TweenService = pcall(function()
        return game:GetService("TweenService")
    end)
    if ok then
        pcall(function()
            TweenService:Create(holder, TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Position = UDim2.new(1, -312, 0, 14 + offset),
            }):Play()
        end)
    end

    local toast = { holder = holder, title = titleLabel, message = messageLabel }
    table.insert(self._toasts, toast)

    -- remove the oldest when there are too many
    while #self._toasts > self._maxToasts do
        local oldest = table.remove(self._toasts, 1)
        pcall(function()
            oldest.holder:Destroy()
        end)
    end

    -- auto dismiss
    task.delay(self._duration, function()
        if ok then
            pcall(function()
                TweenService:Create(holder, TweenInfo.new(0.2), {
                    Position = UDim2.new(1, -312, 0, -20),
                    BackgroundTransparency = 1,
                }):Play()
            end)
        end
        task.wait(0.25)
        pcall(function()
            holder:Destroy()
        end)
        for index = #self._toasts, 1, -1 do
            if self._toasts[index].holder == holder then
                table.remove(self._toasts, index)
            end
        end
    end)

    return toast
end

function Widget:Destroy()
    for _, toast in ipairs(self._toasts) do
        pcall(function()
            toast.holder:Destroy()
        end)
    end
    self._toasts = {}
    if self._screenGui then
        pcall(function()
            self._screenGui:Destroy()
        end)
        self._screenGui = nil
    end
end

return Widget
end

__BFS_MODULES["ui.widgets.section"] = function(require)
--[[
    ui/widgets/section.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    A collapsible group with a header.

    The widgets added to a section are parented to the section's content
    frame, so the whole group can be folded away. A section exposes the
    same Add* methods as a tab page.
]]

local Container = require("ui.container")

local Widget = {}

Widget.__index = function(self, key)
    local method = rawget(Widget, key)
    if method ~= nil then
        return method
    end
    return Container[key]
end

function Widget.Create(window, parent, options)
    options = options or {}

    local theme = window.Theme
    local self = setmetatable({}, Widget)

    local container = Instance.new("Frame")
    container.Name = "Section_" .. (options.text or "")
    container.Size = UDim2.new(1, 0, 0, 34)
    container.BackgroundTransparency = 1
    container.Parent = parent

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 7)
    corner.Parent = container

    local header = Instance.new("TextButton")
    header.Name = "Header"
    header.Size = UDim2.new(1, 0, 0, 30)
    header.BackgroundColor3 = theme.surface
    header.Text = ""
    header.BorderSizePixel = 0
    header.AutoButtonColor = false
    header.Parent = container

    local headerCorner = Instance.new("UICorner")
    headerCorner.CornerRadius = UDim.new(0, 7)
    headerCorner.Parent = header

    local title = Instance.new("TextLabel")
    title.Name = "Title"
    title.Size = UDim2.new(1, -40, 1, 0)
    title.Position = UDim2.new(0, 12, 0, 0)
    title.BackgroundTransparency = 1
    title.Text = (options.text or "Section"):upper()
    title.TextColor3 = theme.accent
    title.Font = Enum.Font.GothamBold
    title.TextSize = 11
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.Parent = header

    local indicator = Instance.new("TextLabel")
    indicator.Name = "Indicator"
    indicator.Size = UDim2.new(0, 20, 1, 0)
    indicator.Position = UDim2.new(1, -28, 0, 0)
    indicator.BackgroundTransparency = 1
    indicator.Text = "-"
    indicator.TextColor3 = theme.textDim
    indicator.Font = Enum.Font.GothamBold
    indicator.TextSize = 14
    indicator.Parent = header

    local content = Instance.new("Frame")
    content.Name = "Content"
    content.Size = UDim2.new(1, 0, 0, 0)
    content.Position = UDim2.new(0, 0, 0, 34)
    content.BackgroundTransparency = 1
    content.Parent = container

    local contentLayout = Instance.new("UIListLayout")
    contentLayout.Padding = UDim.new(0, 6)
    contentLayout.SortOrder = Enum.SortOrder.LayoutOrder
    contentLayout.Parent = content

    local contentPadding = Instance.new("UIPadding")
    contentPadding.PaddingTop = UDim.new(0, 8)
    contentPadding.PaddingLeft = UDim.new(0, 2)
    contentPadding.PaddingRight = UDim.new(0, 2)
    contentPadding.PaddingBottom = UDim.new(0, 2)
    contentPadding.Parent = content

    local expanded = options.expanded ~= false

    local function resize()
        local height = 0
        local count = 0
        for _, child in ipairs(content:GetChildren()) do
            if child:IsA("GuiObject") and not child:IsA("UIComponent") then
                height = height + (child.Size.Y.Offset or 0)
                count = count + 1
            end
        end
        height = height + math.max(0, (count - 1) * 6)
        content.Size = UDim2.new(1, 0, 0, expanded and math.max(height, 0) or 0)
    end

    header.MouseButton1Click:Connect(function()
        expanded = not expanded
        indicator.Text = expanded and "-" or "+"
        content.Visible = expanded
        resize()
    end)

    indicator.Text = expanded and "-" or "+"
    content.Visible = expanded

    self.Element = container
    self.Content = content
    self._window = window
    self._container = content

    function self:Refresh()
        resize()
    end

    function self:Destroy()
        pcall(function()
            container:Destroy()
        end)
    end

    return self
end

return Widget
end

__BFS_MODULES["ui.widgets.slider"] = function(require)
--[[
    ui/widgets/slider.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    A labelled slider with a numeric readout.
]]

local Widget = {}

Widget.__index = Widget

function Widget.Create(window, parent, options)
    options = options or {}

    local theme = window.Theme
    local self = setmetatable({}, Widget)

    local min = options.min or 0
    local max = options.max or 100
    local step = options.step or 1
    local suffix = options.suffix or ""
    local decimals = options.decimals or 0

    local container = Instance.new("Frame")
    container.Name = "Slider_" .. (options.text or "")
    container.Size = UDim2.new(1, 0, 0, 58)
    container.BackgroundColor3 = theme.surfaceAlt
    container.BorderSizePixel = 0
    container.Parent = parent

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 8)
    corner.Parent = container

    local label = Instance.new("TextLabel")
    label.Name = "Label"
    label.Size = UDim2.new(0.6, -12, 0, 24)
    label.Position = UDim2.new(0, 12, 0, 6)
    label.BackgroundTransparency = 1
    label.Text = options.text or "Slider"
    label.TextColor3 = theme.text
    label.Font = Enum.Font.Gotham
    label.TextSize = 13
    label.TextXAlignment = Enum.TextXAlignment.Left
    label.Parent = container

    local value = options.default or min
    local readout = Instance.new("TextLabel")
    readout.Name = "Value"
    readout.Size = UDim2.new(0.4, -12, 0, 24)
    readout.Position = UDim2.new(0.6, 0, 0, 6)
    readout.BackgroundTransparency = 1
    readout.Text = ""
    readout.TextColor3 = theme.accent
    readout.Font = Enum.Font.GothamBold
    readout.TextSize = 13
    readout.TextXAlignment = Enum.TextXAlignment.Right
    readout.Parent = container

    local track = Instance.new("Frame")
    track.Name = "Track"
    track.Size = UDim2.new(1, -24, 0, 6)
    track.Position = UDim2.new(0, 12, 0, 40)
    track.BackgroundColor3 = theme.surface
    track.BorderSizePixel = 0
    track.Parent = container

    local trackCorner = Instance.new("UICorner")
    trackCorner.CornerRadius = UDim.new(1, 0)
    trackCorner.Parent = track

    local fill = Instance.new("Frame")
    fill.Name = "Fill"
    fill.Size = UDim2.new(0, 0, 1, 0)
    fill.BackgroundColor3 = theme.accent
    fill.BorderSizePixel = 0
    fill.Parent = track

    local fillCorner = Instance.new("UICorner")
    fillCorner.CornerRadius = UDim.new(1, 0)
    fillCorner.Parent = fill

    local knob = Instance.new("Frame")
    knob.Name = "Knob"
    knob.Size = UDim2.new(0, 16, 0, 16)
    knob.Position = UDim2.new(0, -8, 0.5, -8)
    knob.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    knob.BorderSizePixel = 0
    knob.Parent = track

    local knobCorner = Instance.new("UICorner")
    knobCorner.CornerRadius = UDim.new(1, 0)
    knobCorner.Parent = knob

    local function format(v)
        if decimals > 0 then
            return string.format("%." .. decimals .. "f", v) .. suffix
        end
        return tostring(math.floor(v)) .. suffix
    end

    local function ratio()
        if max <= min then
            return 0
        end
        return (value - min) / (max - min)
    end

    local function paint()
        local r = ratio()
        fill.Size = UDim2.new(r, 0, 1, 0)
        knob.Position = UDim2.new(r, -8, 0.5, -8)
        readout.Text = format(value)
    end

    local function setValue(newValue, silent)
        newValue = math.floor(newValue / step + 0.5) * step
        newValue = math.max(min, math.min(max, newValue))
        if math.abs(newValue - value) < 0.0001 then
            return
        end
        value = newValue
        paint()

        if not silent and options.callback then
            local ok, err = pcall(options.callback, value)
            if not ok and window.Logger then
                window.Logger:warn("Slider '%s' callback failed: %s", options.text, tostring(err))
            end
        end
    end

    local dragging = false

    local function update(input)
        local width = track.AbsoluteSize.X
        if width <= 0 then
            return
        end
        local relative = (input.Position.X - track.AbsolutePosition.X) / width
        if relative < 0 then relative = 0 elseif relative > 1 then relative = 1 end
        setValue(min + (max - min) * relative)
    end

    knob.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging = true
        end
    end)

    knob.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging = false
        end
    end)

    track.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            update(input)
        end
    end)

    local connections = {}
    local ok, UserInputService = pcall(function()
        return game:GetService("UserInputService")
    end)
    if ok then
        local connection = UserInputService.InputChanged:Connect(function(input)
            if dragging and input.UserInputType == Enum.UserInputType.MouseMovement then
                update(input)
            end
        end)
        table.insert(connections, connection)
    end

    paint()

    self.Element = container
    self._value = value

    function self:GetValue()
        return value
    end

    function self:SetValue(newValue, silent)
        setValue(newValue, silent)
    end

    function self:Destroy()
        for _, connection in ipairs(connections) do
            pcall(function()
                connection:Disconnect()
            end)
        end
        pcall(function()
            container:Destroy()
        end)
    end

    return self
end

return Widget
end

