__BFS_MODULES["ui.widgets.table"] = function(require)
--[[
    ui/widgets/table.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    A simple data table: a header row and a scrolling list of rows.

    Used for the roll history, the spawn log and the entity lists.
]]

local Widget = {}

Widget.__index = Widget

function Widget.Create(window, parent, options)
    options = options or {}

    local theme = window.Theme
    local self = setmetatable({}, Widget)

    local columns = options.columns or {}
    local maxRows = options.maxRows or 8

    local container = Instance.new("Frame")
    container.Name = "Table"
    container.Size = UDim2.new(1, 0, 0, 30 + maxRows * 22 + 8)
    container.BackgroundColor3 = theme.surfaceAlt
    container.BorderSizePixel = 0
    container.Parent = parent

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 8)
    corner.Parent = container

    local header = Instance.new("Frame")
    header.Name = "Header"
    header.Size = UDim2.new(1, -20, 0, 22)
    header.Position = UDim2.new(0, 10, 0, 6)
    header.BackgroundTransparency = 1
    header.Parent = container

    local headerLayout = Instance.new("UIListLayout")
    headerLayout.FillDirection = Enum.FillDirection.Horizontal
    headerLayout.Padding = UDim.new(0, 6)
    headerLayout.Parent = header

    for _, column in ipairs(columns) do
        local columnLabel = Instance.new("TextLabel")
        columnLabel.Name = column
        columnLabel.Size = UDim2.new(column.width or 0.33, -6, 1, 0)
        columnLabel.BackgroundTransparency = 1
        columnLabel.Text = column
        columnLabel.TextColor3 = theme.textDim
        columnLabel.Font = Enum.Font.GothamBold
        columnLabel.TextSize = 11
        columnLabel.TextXAlignment = Enum.TextXAlignment.Left
        columnLabel.Parent = header
    end

    local body = Instance.new("ScrollingFrame")
    body.Name = "Body"
    body.Size = UDim2.new(1, -20, 1, -36)
    body.Position = UDim2.new(0, 10, 0, 30)
    body.BackgroundTransparency = 1
    body.BorderSizePixel = 0
    body.ScrollBarThickness = 3
    body.ScrollBarImageColor3 = theme.accent
    body.CanvasSize = UDim2.new(0, 0, 0, 0)
    body.AutomaticCanvasSize = Enum.AutomaticSize.Y
    body.Parent = container

    local bodyLayout = Instance.new("UIListLayout")
    bodyLayout.Padding = UDim.new(0, 2)
    bodyLayout.SortOrder = Enum.SortOrder.LayoutOrder
    bodyLayout.Parent = body

    local rowWidgets = {}

    local function clearRows()
        for _, row in ipairs(rowWidgets) do
            pcall(function()
                row:Destroy()
            end)
        end
        rowWidgets = {}
    end

    --- rows: array of arrays of strings, newest first.
    function self:SetRows(rows)
        clearRows()

        for index, row in ipairs(rows or {}) do
            if index > maxRows then
                break
            end

            local rowFrame = Instance.new("Frame")
            rowFrame.Name = "Row"
            rowFrame.LayoutOrder = index
            rowFrame.Size = UDim2.new(1, -4, 0, 20)
            rowFrame.BackgroundTransparency = 1
            rowFrame.Parent = body

            local rowLayout = Instance.new("UIListLayout")
            rowLayout.FillDirection = Enum.FillDirection.Horizontal
            rowLayout.Padding = UDim.new(0, 6)
            rowLayout.Parent = rowFrame

            for columnIndex, column in ipairs(columns) do
                local cell = Instance.new("TextLabel")
                cell.Name = column
                cell.Size = UDim2.new(column.width or 0.33, -6, 1, 0)
                cell.BackgroundTransparency = 1
                cell.Text = tostring(row[columnIndex] or "")
                cell.TextColor3 = (columnIndex == 1) and theme.text or theme.textDim
                cell.Font = (columnIndex == 1) and Enum.Font.GothamSemibold or Enum.Font.Gotham
                cell.TextSize = 11
                cell.TextXAlignment = Enum.TextXAlignment.Left
                cell.Parent = rowFrame
            end

            table.insert(rowWidgets, rowFrame)
        end
    end

    function self:Clear()
        clearRows()
    end

    self.Element = container

    function self:Destroy()
        clearRows()
        pcall(function()
            container:Destroy()
        end)
    end

    return self
end

return Widget
end

__BFS_MODULES["ui.widgets.toggle"] = function(require)
--[[
    ui/widgets/toggle.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    A labelled on/off switch.
]]

local Widget = {}

Widget.__index = Widget

function Widget.Create(window, parent, options)
    options = options or {}

    local theme = window.Theme
    local self = setmetatable({}, Widget)

    local container = Instance.new("Frame")
    container.Name = "Toggle_" .. (options.text or "")
    container.Size = UDim2.new(1, 0, 0, 40)
    container.BackgroundColor3 = theme.surfaceAlt
    container.BorderSizePixel = 0
    container.Parent = parent

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 8)
    corner.Parent = container

    local label = Instance.new("TextLabel")
    label.Name = "Label"
    label.Size = UDim2.new(1, -74, 1, 0)
    label.Position = UDim2.new(0, 12, 0, 0)
    label.BackgroundTransparency = 1
    label.Text = options.text or "Toggle"
    label.TextColor3 = theme.text
    label.Font = Enum.Font.Gotham
    label.TextSize = 13
    label.TextXAlignment = Enum.TextXAlignment.Left
    label.Parent = container

    local switch = Instance.new("TextButton")
    switch.Name = "Switch"
    switch.Size = UDim2.new(0, 46, 0, 24)
    switch.Position = UDim2.new(1, -58, 0.5, -12)
    switch.BackgroundColor3 = theme.danger
    switch.Text = ""
    switch.BorderSizePixel = 0
    switch.AutoButtonColor = false
    switch.Parent = container

    local switchCorner = Instance.new("UICorner")
    switchCorner.CornerRadius = UDim.new(1, 0)
    switchCorner.Parent = switch

    local knob = Instance.new("Frame")
    knob.Name = "Knob"
    knob.Size = UDim2.new(0, 18, 0, 18)
    knob.Position = UDim2.new(0, 3, 0.5, -9)
    knob.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    knob.BorderSizePixel = 0
    knob.Parent = switch

    local knobCorner = Instance.new("UICorner")
    knobCorner.CornerRadius = UDim.new(1, 0)
    knobCorner.Parent = knob

    local state = options.default and true or false

    local function paint(animated)
        local target = state and theme.success or theme.danger
        local knobTarget = state and UDim2.new(1, -21, 0.5, -9) or UDim2.new(0, 3, 0.5, -9)

        if animated and window.Animations then
            window:Animate(switch, { BackgroundColor3 = target }, 0.18)
            window:Animate(knob, { Position = knobTarget }, 0.18)
        else
            switch.BackgroundColor3 = target
            knob.Position = knobTarget
        end
    end

    switch.MouseButton1Click:Connect(function()
        state = not state
        paint(true)

        if options.callback then
            local ok, err = pcall(options.callback, state)
            if not ok and window.Logger then
                window.Logger:warn("Toggle '%s' callback failed: %s", options.text, tostring(err))
            end
        end
    end)

    paint(false)

    self.Element = container
    self.Switch = switch
    self.Label = label
    self._state = state
    self._options = options

    function self:GetValue()
        return self._state
    end

    function self:SetValue(newValue, silent)
        newValue = newValue and true or false
        if newValue == self._state then
            return
        end
        self._state = newValue
        paint(false)
        if not silent and options.callback then
            pcall(options.callback, newValue)
        end
    end

    function self:Destroy()
        pcall(function()
            container:Destroy()
        end)
    end

    return self
end

return Widget
end

__BFS_MODULES["world.auto_collect"] = function(require)
--[[
    world/auto_collect.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Walks the character to the closest fruit and picks it up.

    Picking a fruit up in Blox Fruits is a proximity interaction. The
    module teleports the character next to the fruit, then triggers the
    interaction with whatever mechanism the executor provides. When the
    executor has no way to fire the interaction, the character still ends
    up standing on the fruit, which picks it up in most cases because the
    game's own touch detection runs on the server.
]]

local Movement = require("world.movement")
local Util = require("core.util")

local AutoCollect = {}

AutoCollect.__index = AutoCollect

function AutoCollect.new(options)
    options = options or {}

    return setmetatable({
        _logger = options.logger,
        _scanner = options.scanner,
        _input = options.input,
        _active = false,
        _target = nil,
        _collected = 0,
        _startedAt = 0,
        _state = "idle",
        _lastCollected = nil,
    }, AutoCollect)
end

function AutoCollect:Start()
    self._active = true
    self._startedAt = os.time()
    self._state = "scanning"
    if self._logger then
        self._logger:info("Auto collect enabled")
    end
end

function AutoCollect:Stop()
    self._active = false
    self._target = nil
    self._state = "idle"
end

function AutoCollect:IsActive()
    return self._active
end

--- The closest fruit that is still in the world.
function AutoCollect:PickTarget()
    if not self._scanner then
        return nil
    end

    local fruits = self._scanner:Fruits()
    if #fruits == 0 then
        return nil
    end

    local root = Movement.GetRoot()
    local origin = root and root.Position or Vector3.new(0, 0, 0)

    local best, bestDistance = nil, math.huge
    for _, fruit in ipairs(fruits) do
        local distance = (fruit.position - origin).Magnitude
        if distance < bestDistance then
            best, bestDistance = fruit, distance
        end
    end

    return best
end

function AutoCollect:Step(deltaTime)
    if not self._active then
        return
    end

    if not Movement.IsAlive() then
        self._state = "waiting for respawn"
        return
    end

    -- validate the current target
    if self._target then
        if not Util.isInstance(self._target.instance) or not self._target.instance.Parent then
            -- the fruit is gone -- it was probably collected
            self._collected = self._collected + 1
            self._lastCollected = self._target.fruit
            self._target = nil
        else
            self:_engage(self._target, deltaTime)
            return
        end
    end

    local target = self:PickTarget()
    if not target then
        self._state = "no fruit in range"
        return
    end

    self._target = target
    self._state = "moving to " .. target.fruit
end

function AutoCollect:_engage(target, deltaTime)
    local root = Movement.GetRoot()
    if not root then
        return
    end

    local distance = (target.position - root.Position).Magnitude

    if distance > 6 then
        self._state = "moving to " .. target.fruit
        local step = (deltaTime or 0.016) * 110
        Movement.MoveTowards(target.position, math.max(step, 4))
        return
    end

    self._state = "collecting " .. target.fruit

    -- try to fire a proximity prompt attached to the fruit
    local fired = false
    if self._input then
        local instance = target.instance
        if Util.isInstance(instance) then
            for _, child in ipairs(instance:GetDescendants()) do
                if Util.isInstance(child, "ProximityPrompt") then
                    if self._input:FireProximityPrompt(child) then
                        fired = true
                        break
                    end
                end
            end
        end
        if not fired then
            self._input:PressE()
        end
    end

    if not fired then
        -- stand on the fruit so the game's own pickup detection fires
        Movement.TeleportNear(target.position, 2)
    end
end

function AutoCollect:GetStatus()
    return {
        active = self._active,
        state = self._state,
        target = self._target and self._target.fruit or nil,
        collected = self._collected,
        lastCollected = self._lastCollected,
        uptime = self._startedAt > 0 and (os.time() - self._startedAt) or 0,
    }
end

return AutoCollect
end

__BFS_MODULES["world.auto_farm"] = function(require)
--[[
    world/auto_farm.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Automatic farming loop.

    The loop is deliberately simple and observable:
        1. pick a target mob (nearest one that matches the level filter)
        2. walk the character to it
        3. attack until it dies or the character leaves the area
        4. repeat

    Everything it does is reported through the status fields, so the
    interface can show what the loop is actually doing instead of a
    vague "running" label.
]]

local Movement = require("world.movement")
local Util = require("core.util")

local AutoFarm = {}

AutoFarm.__index = AutoFarm

function AutoFarm.new(options)
    options = options or {}

    return setmetatable({
        _logger = options.logger,
        _scanner = options.scanner,
        _input = options.input,
        _stats = options.stats,
        _settings = options.settings,
        _active = false,
        _target = nil,
        _targetId = nil,
        _kills = 0,
        _lastKill = 0,
        _startedAt = 0,
        _state = "idle",
    }, AutoFarm)
end

function AutoFarm:Start()
    self._active = true
    self._startedAt = os.time()
    self._state = "scanning"
    if self._logger then
        self._logger:info("Auto farm enabled")
    end
end

function AutoFarm:Stop()
    self._active = false
    self._target = nil
    self._targetId = nil
    self._state = "idle"
    if self._logger then
        self._logger:info("Auto farm disabled after %d kill(s)", self._kills)
    end
end

function AutoFarm:IsActive()
    return self._active
end

function AutoFarm:_settingsValue(path, fallback)
    if not self._settings then
        return fallback
    end
    local value = self._settings:get(path, fallback)
    if value == nil then
        return fallback
    end
    return value
end

--- Choose a mob to attack.
---
--- `targetLevel` of 0 means "use the player's level". Mobs up to
--- `levelTolerance` above the target level are accepted, which is how the
--- suite avoids running into a wall.
function AutoFarm:PickTarget()
    if not self._scanner then
        return nil
    end

    local mobs = self._scanner:Mobs()
    if #mobs == 0 then
        return nil
    end

    local root = Movement.GetRoot()
    local origin = root and root.Position or Vector3.new(0, 0, 0)

    local playerLevel = 0
    if self._stats then
        playerLevel = self._stats:GetLevel()
    end

    local targetLevel = self:_settingsValue("farm.targetLevel", 0) or 0
    if targetLevel <= 0 then
        targetLevel = playerLevel
    end
    if targetLevel <= 0 then
        targetLevel = 100
    end

    local tolerance = 25
    local attackRange = self:_settingsValue("farm.attackRange", 12) or 12
    local searchRadius = (attackRange + 60) * 3

    local best, bestScore = nil, nil

    for _, mob in ipairs(mobs) do
        local level = mob.level or 0
        if level > 0 and level <= targetLevel + tolerance then
            local distance = (mob.position - origin).Magnitude
            if distance <= searchRadius then
                -- prefer mobs close to the target level, then close by
                local levelDelta = math.abs(level - targetLevel)
                local score = levelDelta * 10 + distance
                if bestScore == nil or score < bestScore then
                    best, bestScore = mob, score
                end
            end
        end
    end

    return best
end

--- One iteration of the loop. Called by the scheduler.
function AutoFarm:Step(deltaTime)
    if not self._active then
        return
    end

    if not Movement.IsAlive() then
        self._state = "waiting for respawn"
        self._target = nil
        return
    end

    -- safety stop
    if self:_settingsValue("farm.safeMode", true) then
        local minimum = self:_settingsValue("farm.safeHealth", 30) or 30
        if Movement.GetHealthPercent() < minimum then
            self._state = string.format("stopped: health below %d%%", minimum)
            self:Stop()
            return
        end
    end

    -- keep the current target while it is alive and close
    if self._target and Util.isInstance(self._target.instance) then
        local humanoid = self._target.instance:FindFirstChildOfClass("Humanoid")
        local alive = true
        if humanoid then
            alive = humanoid.Health > 0
        end
        if alive then
            self:_engage(self._target, deltaTime)
            return
        end

        self._kills = self._kills + 1
        self._lastKill = os.time()
        self._target = nil
        self._targetId = nil
    end

    local target = self:PickTarget()
    if not target then
        self._state = "no target in range"
        return
    end

    self._target = target
    self._state = "moving to " .. target.name
end

function AutoFarm:_engage(target, deltaTime)
    local root = Movement.GetRoot()
    if not root then
        return
    end

    local attackRange = self:_settingsValue("farm.attackRange", 12) or 12
    local distance = (target.position - root.Position).Magnitude

    if distance > attackRange then
        self._state = "closing distance to " .. target.name
        local step = (deltaTime or 0.016) * 90
        Movement.MoveTowards(target.position, math.max(step, 3))
        return
    end

    self._state = "attacking " .. target.name
    Movement.LookAt(target.position)
    if self._input then
        self._input:Click()
    end
end

--- Status for the interface.
function AutoFarm:GetStatus()
    return {
        active = self._active,
        state = self._state,
        target = self._target and self._target.name or nil,
        targetLevel = self._target and self._target.level or nil,
        kills = self._kills,
        uptime = self._startedAt > 0 and (os.time() - self._startedAt) or 0,
        lastKill = self._lastKill,
    }
end

function AutoFarm:Reset()
    self._kills = 0
    self._lastKill = 0
end

return AutoFarm
end

__BFS_MODULES["world.auto_quest"] = function(require)
--[[
    world/auto_quest.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Quest runner.

    The flow:
        1. walk to the closest quest giver
        2. read the quest target from the quest panel in the HUD
        3. if the target is a mob we recognise, go and defeat it
        4. return to the quest giver to hand the quest in

    Step 2 is the weak point: the quest panel is a set of TextLabels whose
    structure changes between game updates, so the reader looks for a
    label that contains a mob name from the mob table. When it cannot
    find one, the module says so instead of guessing.
]]

local Movement = require("world.movement")
local Mobs = require("data.mobs")
local NPCs = require("data.npcs")
local Util = require("core.util")

local AutoQuest = {}

AutoQuest.__index = AutoQuest

-- Labels that usually hold the quest description.
local QUEST_LABELS = { "QuestName", "QuestDescription", "QuestTarget", "MissionName", "QuestInfo" }

function AutoQuest.new(options)
    options = options or {}

    return setmetatable({
        _logger = options.logger,
        _scanner = options.scanner,
        _input = options.input,
        _active = false,
        _state = "idle",
        _questGiver = nil,
        _targetMob = nil,
        _completed = 0,
        _startedAt = 0,
    }, AutoQuest)
end

function AutoQuest:Start()
    self._active = true
    self._startedAt = os.time()
    self._state = "looking for a quest giver"
    if self._logger then
        self._logger:info("Auto quest enabled")
    end
end

function AutoQuest:Stop()
    self._active = false
    self._state = "idle"
    self._questGiver = nil
    self._targetMob = nil
end

function AutoQuest:IsActive()
    return self._active
end

--- Read the quest target out of the HUD.
function AutoQuest:ReadQuestTarget()
    local ok, Players = pcall(function()
        return game:GetService("Players")
    end)
    if not ok then
        return nil
    end
    local okPlayer, player = pcall(function()
        return Players.LocalPlayer
    end)
    if not okPlayer or not player then
        return nil
    end
    local okGui, playerGui = pcall(function()
        return player:FindFirstChildOfClass("PlayerGui")
    end)
    if not okGui or not playerGui then
        return nil
    end

    for _, labelName in ipairs(QUEST_LABELS) do
        local ok, label = pcall(function()
            return playerGui:FindFirstChild(labelName, true)
        end)
        if ok and label and (label:IsA("TextLabel") or label:IsA("TextButton")) then
            local text = label.Text
            if type(text) == "string" and text ~= "" then
                -- look for a mob name inside the quest text
                for mobName, mob in pairs(Mobs.ByName) do
                    if text:lower():find(mobName:lower(), 1, true) then
                        return mob
                    end
                end
            end
        end
    end

    return nil
end

--- The closest quest giver in the world.
function AutoQuest:PickQuestGiver()
    if not self._scanner then
        return nil
    end

    local npcs = self._scanner:NPCs()
    local root = Movement.GetRoot()
    local origin = root and root.Position or Vector3.new(0, 0, 0)

    local best, bestDistance = nil, math.huge
    for _, npc in ipairs(npcs) do
        if npc.role == "quest" then
            local distance = (npc.position - origin).Magnitude
            if distance < bestDistance then
                best, bestDistance = npc, distance
            end
        end
    end

    return best
end

function AutoQuest:Step(deltaTime)
    if not self._active then
        return
    end

    if not Movement.IsAlive() then
        self._state = "waiting for respawn"
        return
    end

    local root = Movement.GetRoot()
    if not root then
        return
    end

    -- are we already fighting the quest target?
    if self._targetMob and Util.isInstance(self._targetMob.instance) then
        local humanoid = self._targetMob.instance:FindFirstChildOfClass("Humanoid")
        local alive = not humanoid or humanoid.Health > 0
        if alive then
            self._state = "fighting " .. self._targetMob.name
            local distance = (self._targetMob.position - root.Position).Magnitude
            if distance > 10 then
                local step = (deltaTime or 0.016) * 90
                Movement.MoveTowards(self._targetMob.position, math.max(step, 3))
            else
                Movement.LookAt(self._targetMob.position)
                if self._input then
                    self._input:Click()
                end
            end
            return
        end

        self._completed = self._completed + 1
        self._targetMob = nil
        self._state = "quest target defeated, returning to the giver"
    end

    -- find the giver
    if not self._questGiver or not Util.isInstance(self._questGiver.instance) then
        self._questGiver = self:PickQuestGiver()
        if not self._questGiver then
            self._state = "no quest giver in range"
            return
        end
    end

    local distance = (self._questGiver.position - root.Position).Magnitude
    if distance > 8 then
        self._state = "walking to " .. self._questGiver.name
        local step = (deltaTime or 0.016) * 100
        Movement.MoveTowards(self._questGiver.position, math.max(step, 4))
        return
    end

    -- we are at the giver -- read the quest and go after the target
    local target = self:ReadQuestTarget()
    if target then
        self._targetMob = {
            name = target.name,
            level = target.level,
            instance = nil,
            position = Vector3.new(0, 0, 0),
        }

        -- find the live instance of that mob
        if self._scanner then
            for _, mob in ipairs(self._scanner:Mobs()) do
                if mob.name == target.name then
                    self._targetMob = mob
                    break
                end
            end
        end

        if self._targetMob.instance then
            self._state = "quest accepted: " .. target.name
        else
            self._state = "quest target not in range yet"
        end
        return
    end

    -- no readable quest: interact with the giver and hope
    self._state = "at quest giver, interacting"
    if self._input then
        self._input:Click()
        self._input:PressE()
    end
end

function AutoQuest:GetStatus()
    return {
        active = self._active,
        state = self._state,
        questGiver = self._questGiver and self._questGiver.name or nil,
        target = self._targetMob and self._targetMob.name or nil,
        completed = self._completed,
        uptime = self._startedAt > 0 and (os.time() - self._startedAt) or 0,
    }
end

return AutoQuest
end

__BFS_MODULES["world.entity"] = function(require)
--[[
    world/entity.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Classifies a live workspace instance into something the suite understands.

    Blox Fruits does not expose a clean API for "what is this model?", so
    the classification is heuristic: the name is matched against the fruit,
    mob, boss, chest and NPC tables, and the level is recovered from
    attributes, child values, or the display name.
]]

local Fruits = require("data.fruits")
local Mobs = require("data.mobs")
local Chests = require("data.chests")
local NPCs = require("data.npcs")
local Util = require("core.util")

local Entity = {}

Entity.KINDS = { "fruit", "mob", "boss", "chest", "npc", "player" }

--- Look for a level value on an instance.
--- Looks at attributes first, then at IntValue / NumberValue children, and
--- finally parses the display name ("Bandit [Lv. 35]").
function Entity:ExtractLevel(instance)
    if not Util.isInstance(instance) then
        return nil
    end

    for _, attributeName in ipairs({ "Level", "MobLevel", "Level_" }) do
        local ok, value = pcall(function()
            return instance:GetAttribute(attributeName)
        end)
        if ok and type(value) == "number" then
            return value
        end
    end

    for _, child in ipairs(instance:GetChildren()) do
        if Util.isInstance(child) then
            local className = Util.getClass(child)
            if className == "IntValue" or className == "NumberValue" or className == "StringValue" then
                if string.lower(child.Name):find("level") then
                    local ok, value = pcall(function()
                        return child.Value
                    end)
                    if ok then
                        if type(value) == "number" then
                            return value
                        end
                        if type(value) == "string" then
                            local parsed = tonumber(value:match("%d+"))
                            if parsed then
                                return parsed
                            end
                        end
                    end
                end
            end
        end
    end

    -- parse the display name
    local okName, name = pcall(function()
        return instance.Name
    end)
    if okName and type(name) == "string" then
        local parsed = tonumber(name:match("Lv%.?%s*(%d+)")) or tonumber(name:match("(%d+)"))
        if parsed then
            return parsed
        end
    end

    return nil
end

--- Classify an instance.
--- Returns nil when the instance is not something the suite tracks.
function Entity:Classify(instance)
    if not Util.isInstance(instance) then
        return nil
    end

    local okName, name = pcall(function()
        return instance.Name
    end)
    if not okName or type(name) ~= "string" then
        return nil
    end

    -- players are handled separately
    if Util.getClass(instance) == "Player" then
        return { kind = "player", name = name }
    end

    -- fruit
    local fruit = Fruits.Resolve(name)
    if fruit and (name:lower():find("fruit", 1, true) or self:_looksLikeFruitModel(instance)) then
        return {
            kind = "fruit",
            name = fruit.name,
            display = name,
            rarity = fruit.rarity,
            type = fruit.type,
            record = fruit,
        }
    end

    -- chests
    if Chests.IsChest(name) then
        return {
            kind = "chest",
            name = name,
            display = name,
            tier = Chests.TierOf(name),
        }
    end

    -- bosses
    local boss = Mobs.BossByName[name:lower()]
    if boss then
        return {
            kind = "boss",
            name = boss.name,
            display = name,
            level = self:ExtractLevel(instance) or boss.level,
            record = boss,
        }
    end

    -- NPCs
    local npcRole = NPCs.RoleFromName(name)
    if npcRole then
        return {
            kind = "npc",
            name = name,
            display = name,
            role = npcRole,
        }
    end

    -- mobs
    local mob = Mobs.ByName[name:lower()]
    if mob then
        return {
            kind = "mob",
            name = mob.name,
            display = name,
            level = self:ExtractLevel(instance) or mob.level,
            record = mob,
        }
    end

    -- last resort: does it carry a Humanoid and a readable level?
    local level = self:ExtractLevel(instance)
    if level and self:_hasHumanoid(instance) then
        return {
            kind = "mob",
            name = name,
            display = name,
            level = level,
            guessed = true,
        }
    end

    return nil
end

function Entity:_looksLikeFruitModel(instance)
    if not Util.isInstance(instance) then
        return false
    end
    for _, child in ipairs(instance:GetChildren()) do
        if Util.isInstance(child, "StringValue") then
            if Fruits.Resolve(child.Value) then
                return true
            end
        end
    end
    for _, attributeName in ipairs({ "FruitName", "Fruit", "Rarity" }) do
        local ok, value = pcall(function()
            return instance:GetAttribute(attributeName)
        end)
        if ok and type(value) == "string" and Fruits.Resolve(value) then
            return true
        end
    end
    return false
end

function Entity:_hasHumanoid(instance)
    if not Util.isInstance(instance) then
        return false
    end
    local ok, humanoid = pcall(function()
        return instance:FindFirstChildOfClass("Humanoid")
    end)
    return ok and humanoid ~= nil
end

--- Human readable label for an entity, used by the ESP overlay.
function Entity:Label(entity, distance)
    if not entity then
        return ""
    end

    local parts = {}
    if entity.kind == "fruit" then
        parts[#parts + 1] = entity.name
        parts[#parts + 1] = entity.rarity or ""
    elseif entity.kind == "mob" or entity.kind == "boss" then
        parts[#parts + 1] = entity.name
        if entity.level then
            parts[#parts + 1] = "Lv." .. tostring(entity.level)
        end
    elseif entity.kind == "chest" then
        parts[#parts + 1] = entity.name
    elseif entity.kind == "npc" then
        parts[#parts + 1] = entity.name
    else
        parts[#parts + 1] = entity.name or "?"
    end

    if distance then
        parts[#parts + 1] = string.format("%d studs", math.floor(distance))
    end

    return table.concat(parts, "  |  ")
end

--- Colour used for the ESP overlay.
function Entity:Color(entity)
    if not entity then
        return Color3.fromRGB(200, 200, 200)
    end

    if entity.kind == "fruit" then
        local Rarity = require("luck.rarity")
        return Rarity.Color(entity.rarity)
    elseif entity.kind == "boss" then
        return Color3.fromRGB(255, 60, 60)
    elseif entity.kind == "chest" then
        return Color3.fromRGB(255, 210, 70)
    elseif entity.kind == "npc" then
        return Color3.fromRGB(120, 220, 255)
    elseif entity.kind == "mob" then
        return Color3.fromRGB(200, 120, 255)
    end

    return Color3.fromRGB(200, 200, 200)
end

return Entity
end

__BFS_MODULES["world.esp"] = function(require)
--[[
    world/esp.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    The ESP overlay.

    Every tracked entity gets a BillboardGui with a label, and optionally a
    Highlight so the model itself is tinted. The overlay lives in its own
    ScreenGui so it can be toggled without touching the main interface.

    The overlay is rebuilt from the scanner's buckets rather than patched
    in place, which keeps it simple and correct at the cost of recreating
    the billboards on every refresh. With the default cap of 150 objects
    that is cheap enough to do a few times a second.
]]

local Util = require("core.util")

local Esp = {}

Esp.__index = Esp

function Esp.new(options)
    options = options or {}

    local self = setmetatable({
        _logger = options.logger,
        _cleanup = options.cleanup,
        _screenGui = nil,
        _enabled = false,
        _maxObjects = options.maxObjects or 150,
        _showLabel = true,
        _showDistance = true,
        _useHighlight = true,
        _billboards = {},
        _highlights = {},
    }, Esp)

    return self
end

function Esp:_createScreenGui()
    if self._screenGui then
        return self._screenGui
    end

    local screenGui = Instance.new("ScreenGui")
    screenGui.Name = "BFS_ESP_" .. tostring(math.random(100000, 999999))
    screenGui.ResetOnSpawn = false
    screenGui.DisplayOrder = 900
    screenGui.IgnoreGuiInset = true
    screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling

    local ok, coreGui = pcall(function()
        return game:GetService("CoreGui")
    end)
    if ok then
        pcall(function()
            screenGui.Parent = coreGui
        end)
    end

    if not screenGui.Parent then
        local okPlayer, player = pcall(function()
            return game:GetService("Players").LocalPlayer
        end)
        if okPlayer and player then
            pcall(function()
                screenGui.Parent = player:WaitForChild("PlayerGui")
            end)
        end
    end

    self._screenGui = screenGui

    if self._cleanup then
        self._cleanup:trackInstance(screenGui, "esp-gui")
    end

    return screenGui
end

function Esp:SetEnabled(enabled)
    self._enabled = enabled and true or false

    if not self._enabled then
        self:Clear()
        return
    end

    self:_createScreenGui()
    if self._screenGui then
        self._screenGui.Enabled = true
    end
end

function Esp:IsEnabled()
    return self._enabled
end

function Esp:SetMaxObjects(max)
    self._maxObjects = math.max(1, tonumber(max) or 150)
end

function Esp:SetShowLabel(show)
    self._showLabel = show and true or false
end

function Esp:SetShowDistance(show)
    self._showDistance = show and true or false
end

function Esp:SetUseHighlight(use)
    self._useHighlight = use and true or false
end

--- Remove every billboard and highlight.
function Esp:Clear()
    for _, billboard in ipairs(self._billboards) do
        pcall(function()
            billboard:Destroy()
        end)
    end
    for _, highlight in ipairs(self._highlights) do
        pcall(function()
            highlight:Destroy()
        end)
    end
    self._billboards = {}
    self._highlights = {}
end

function Esp:_makeBillboard(entity, label, distance, color)
    local instance = entity.instance
    if not Util.isInstance(instance) then
        return nil
    end

    -- attach to the part so the label follows the model
    local anchor = instance
    if Util.isInstance(instance, "Model") then
        local ok, part = pcall(function()
            return instance:FindFirstChildWhichIsA("BasePart")
        end)
        if ok and part then
            anchor = part
        end
    end

    if not Util.isInstance(anchor, "BasePart") then
        return nil
    end

    local billboard = Instance.new("BillboardGui")
    billboard.Name = "BFS_Label"
    billboard.Adornee = anchor
    billboard.Size = UDim2.new(0, 220, 0, 26)
    billboard.StudsOffset = Vector3.new(0, 3.2, 0)
    billboard.AlwaysOnTop = true
    billboard.MaxDistance = 4000
    billboard.Parent = self._screenGui

    local text = Instance.new("TextLabel")
    text.Size = UDim2.new(1, 0, 1, 0)
    text.BackgroundTransparency = 1
    text.Text = label
    text.TextColor3 = color
    text.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    text.TextStrokeTransparency = 0.35
    text.Font = Enum.Font.GothamBold
    text.TextSize = 13
    text.TextScaled = false
    text.TextWrapped = false
    text.Parent = billboard

    return billboard
end

function Esp:_makeHighlight(entity, color)
    local instance = entity.instance
    if not Util.isInstance(instance) then
        return nil
    end

    local ok, highlight = pcall(function()
        local h = Instance.new("Highlight")
        h.Adornee = instance
        h.FillColor = color
        h.FillTransparency = 0.75
        h.OutlineColor = color
        h.OutlineTransparency = 0.1
        h.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        h.Parent = self._screenGui
        return h
    end)

    if not ok then
        return nil
    end
    return highlight
end

--- Refresh the overlay from a list of entities.
--- `entries` is an array of { entity = entity, label = string, distance = number }
function Esp:Render(entries, options)
    if not self._enabled then
        return 0
    end

    self:_createScreenGui()
    self:Clear()

    if not self._screenGui then
        return 0
    end

    options = options or {}
    local labelBuilder = options.labelBuilder
    local colorBuilder = options.colorBuilder

    local rendered = 0
    for _, entry in ipairs(entries or {}) do
        if rendered >= self._maxObjects then
            break
        end

        local entity = entry.entity
        if entity and Util.isInstance(entity.instance) and entity.instance.Parent then
            local distance = entry.distance
            local label
            if labelBuilder then
                label = labelBuilder(entity, distance)
            else
                label = entry.label or entity.name or "?"
            end

            if self._showDistance and distance then
                label = label .. string.format("  [%d]", math.floor(distance))
            end

            local color = colorBuilder and colorBuilder(entity) or Color3.fromRGB(255, 255, 255)

            local billboard = self:_makeBillboard(entity, label, distance, color)
            if billboard then
                table.insert(self._billboards, billboard)
                rendered = rendered + 1
            end

            if self._useHighlight then
                local highlight = self:_makeHighlight(entity, color)
                if highlight then
                    table.insert(self._highlights, highlight)
                end
            end
        end
    end

    return rendered
end

function Esp:Count()
    return #self._billboards
end

function Esp:Destroy()
    self:Clear()
    if self._screenGui then
        pcall(function()
            self._screenGui:Destroy()
        end)
        self._screenGui = nil
    end
end

return Esp
end

__BFS_MODULES["world.fast_travel"] = function(require)
--[[
    world/fast_travel.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Teleports the character to a named destination.

    Because the islands are laid out differently in every server, the
    destination is resolved by finding a live NPC whose name matches the
    request and walking to it. The catalogue in data/islands.lua is used
    to turn "Third Sea" into a list of candidate NPCs.
]]

local Movement = require("world.movement")
local NPCs = require("data.npcs")
local Islands = require("data.islands")
local Util = require("core.util")

local FastTravel = {}

FastTravel.__index = FastTravel

function FastTravel.new(options)
    options = options or {}

    return setmetatable({
        _logger = options.logger,
        _scanner = options.scanner,
        _lastDestination = nil,
        _lastError = nil,
        _tripCount = 0,
    }, FastTravel)
end

--- All destinations the suite can currently see in the world.
function FastTravel:Available()
    local out = {}

    if self._scanner then
        for _, npc in ipairs(self._scanner:NPCs()) do
            out[#out + 1] = {
                name = npc.name,
                role = npc.role,
                position = npc.position,
            }
        end
    end

    return out
end

--- Find a live NPC whose name matches the query.
function FastTravel:FindNpc(query)
    if type(query) ~= "string" or query == "" then
        return nil
    end

    if not self._scanner then
        return nil
    end

    local lowered = query:lower()

    -- exact match first
    for _, npc in ipairs(self._scanner:NPCs()) do
        if npc.name:lower() == lowered then
            return npc
        end
    end

    -- then a partial match
    local best = nil
    for _, npc in ipairs(self._scanner:NPCs()) do
        if npc.name:lower():find(lowered, 1, true) then
            best = npc
            break
        end
    end

    if best then
        return best
    end

    -- fall back to a known NPC signature
    local role = NPCs.RoleFromName(query)
    if role then
        for _, npc in ipairs(self._scanner:NPCs()) do
            if npc.role == role then
                return npc
            end
        end
    end

    return nil
end

--- Teleport to a destination by NPC name.
function FastTravel:TravelTo(query)
    local npc = self:FindNpc(query)
    if not npc then
        self._lastError = "no NPC matching '" .. tostring(query) .. "'"
        if self._logger then
            self._logger:warn("Fast travel failed: %s", self._lastError)
        end
        return false
    end

    local ok = Movement.TeleportNear(npc.position, 6)
    if ok then
        self._lastDestination = npc.name
        self._lastError = nil
        self._tripCount = self._tripCount + 1
        if self._logger then
            self._logger:info("Travelled to %s", npc.name)
        end
    end

    return ok
end

--- Teleport to the island that fits a level.
function FastTravel:TravelToIslandForLevel(level)
    local island = Islands.ForLevel(level)
    if not island then
        return false
    end

    -- the island is identified by the NPCs that live on it
    for _, npc in ipairs(NPCs.List) do
        if npc.island == island.name and npc.role ~= "quest" then
            if self:TravelTo(npc.name) then
                return true
            end
        end
    end

    self._lastError = "no NPC found for " .. island.name
    return false
end

function FastTravel:GetStatus()
    return {
        lastDestination = self._lastDestination,
        lastError = self._lastError,
        trips = self._tripCount,
    }
end

return FastTravel
end

__BFS_MODULES["world"] = function(require)
--[[
    world/init.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    World module facade.

    Owns the scanner, the ESP overlay, the automation loops and the fast
    travel helper, and reacts to the settings that turn each feature on
    and off.
]]

local Scanner = require("world.scanner")
local Esp = require("world.esp")
local AutoFarm = require("world.auto_farm")
local AutoCollect = require("world.auto_collect")
local AutoQuest = require("world.auto_quest")
local FastTravel = require("world.fast_travel")
local PlayerStats = require("world.player_stats")
local Input = require("world.input")
local Entity = require("world.entity")
local Movement = require("world.movement")

local World = {}

World.__index = World

function World.new(options)
    options = options or {}

    local self = setmetatable({
        _logger = options.logger,
        _settings = options.settings,
        _cleanup = options.cleanup,
        _scanner = Scanner.new({ logger = options.logger }),
        _input = Input.new({ logger = options.logger }),
        _stats = PlayerStats.new({ logger = options.logger }),
        _started = false,
    }, World)

    self._esp = Esp.new({
        logger = options.logger,
        cleanup = options.cleanup,
    })

    self._autoFarm = AutoFarm.new({
        logger = options.logger,
        scanner = self._scanner,
        input = self._input,
        stats = self._stats,
        settings = options.settings,
    })

    self._autoCollect = AutoCollect.new({
        logger = options.logger,
        scanner = self._scanner,
        input = self._input,
    })

    self._autoQuest = AutoQuest.new({
        logger = options.logger,
        scanner = self._scanner,
        input = self._input,
    })

    self._fastTravel = FastTravel.new({
        logger = options.logger,
        scanner = self._scanner,
    })

    return self
end

function World:Start(suite)
    local settings = suite and suite:settings() or self._settings
    self._settings = settings or self._settings

    -- scan on a timer
    if suite and suite:scheduler() then
        suite:scheduler():every("world.scan", 2.0, function()
            self._scanner:Scan()
        end)

        -- refresh the overlay on its own, slower timer
        suite:scheduler():every("world.esp", 0.5, function()
            self:RefreshESP()
        end)

        -- drive the automation loops
        suite:scheduler():frame("world.farm", function(deltaTime)
            self._autoFarm:Step(deltaTime)
        end)

        suite:scheduler():frame("world.collect", function(deltaTime)
            self._autoCollect:Step(deltaTime)
        end)

        suite:scheduler():frame("world.quest", function(deltaTime)
            self._autoQuest:Step(deltaTime)
        end)
    end

    if settings then
        settings:onChange("world.maxESP", function(value)
            self._esp:SetMaxObjects(value)
        end)

        settings:onChange("world.fruitESPLabel", function(value)
            self._esp:SetShowLabel(value)
        end)

        settings:onChange("farm.autoFarm", function(value)
            if value then
                self._autoFarm:Start()
            else
                self._autoFarm:Stop()
            end
        end)

        settings:onChange("farm.autoCollect", function(value)
            if value then
                self._autoCollect:Start()
            else
                self._autoCollect:Stop()
            end
        end)

        settings:onChange("farm.autoQuest", function(value)
            if value then
                self._autoQuest:Start()
            else
                self._autoQuest:Stop()
            end
        end)

        -- apply the values that are already set
        self._esp:SetMaxObjects(settings:get("world.maxESP", 150))
    end

    -- first scan straight away
    self._scanner:Scan()

    self._started = true

    if self._logger then
        self._logger:info("World module started")
    end

    return true
end

function World:Stop()
    self._started = false
    self._autoFarm:Stop()
    self._autoCollect:Stop()
    self._autoQuest:Stop()
    self._esp:SetEnabled(false)
    self._esp:Destroy()
    return true
end

-- ── accessors ────────────────────────────────────────────────────────────

--- True once Start() has run successfully.
function World:IsStarted()
    return self._started
end

function World:Scanner()
    return self._scanner
end

function World:ESP()
    return self._esp
end

function World:AutoFarm()
    return self._autoFarm
end

function World:AutoCollect()
    return self._autoCollect
end

function World:AutoQuest()
    return self._autoQuest
end

function World:FastTravel()
    return self._fastTravel
end

function World:PlayerStats()
    return self._stats
end

function World:Input()
    return self._input
end

function World:Entity()
    return Entity
end

function World:Movement()
    return Movement
end

-- ── ESP control ──────────────────────────────────────────────────────────

--- Rebuild the overlay from the scanner buckets.
--- `kinds` is a list of entity kinds to draw.
function World:UpdateESP(kinds)
    local entries = {}
    local root = Movement.GetRoot()
    local origin = root and root.Position or Vector3.new(0, 0, 0)

    local buckets = self._scanner:Buckets()
    local wanted = {}
    for _, kind in ipairs(kinds or {}) do
        wanted[kind] = true
    end

    for kind, list in pairs(buckets) do
        if wanted[kind] then
            for _, entity in ipairs(list) do
                local distance = (entity.position - origin).Magnitude
                entries[#entries + 1] = {
                    entity = entity,
                    distance = distance,
                }
            end
        end
    end

    table.sort(entries, function(a, b)
        return a.distance < b.distance
    end)

    return self._esp:Render(entries, {
        labelBuilder = function(entity, distance)
            return Entity:Label(entity, distance)
        end,
        colorBuilder = function(entity)
            return Entity:Color(entity)
        end,
    })
end

--- Which ESP layers are currently enabled by the settings.
function World:EnabledLayers()
    local settings = self._settings
    if not settings then
        return {}
    end

    local layers = {}
    if settings:get("world.fruitESP", false) then
        layers[#layers + 1] = "fruit"
    end
    if settings:get("world.mobESP", false) then
        layers[#layers + 1] = "mob"
    end
    if settings:get("world.bossESP", false) then
        layers[#layers + 1] = "boss"
    end
    if settings:get("world.chestESP", false) then
        layers[#layers + 1] = "chest"
    end
    if settings:get("world.npcESP", false) then
        layers[#layers + 1] = "npc"
    end
    return layers
end

--- Refresh the overlay if any layer is enabled.
function World:RefreshESP()
    local layers = self:EnabledLayers()
    if #layers == 0 then
        self._esp:SetEnabled(false)
        return 0
    end

    self._esp:SetEnabled(true)
    return self:UpdateESP(layers)
end

-- ── automation control ───────────────────────────────────────────────────

function World:SetAutoFarm(enabled)
    if enabled then
        self._autoFarm:Start()
    else
        self._autoFarm:Stop()
    end
    return enabled
end

function World:SetAutoCollect(enabled)
    if enabled then
        self._autoCollect:Start()
    else
        self._autoCollect:Stop()
    end
    return enabled
end

function World:SetAutoQuest(enabled)
    if enabled then
        self._autoQuest:Start()
    else
        self._autoQuest:Stop()
    end
    return enabled
end

--- Travel to a named NPC.
function World:TravelTo(name)
    return self._fastTravel:TravelTo(name)
end

--- One status snapshot for the dashboard.
function World:GetStats()
    local buckets = self._scanner:Buckets()

    return {
        scanCount = self._scanner:ScanCount(),
        scanDuration = self._scanner:LastDuration(),
        counts = {
            fruit = #buckets.fruit,
            mob = #buckets.mob,
            boss = #buckets.boss,
            chest = #buckets.chest,
            npc = #buckets.npc,
        },
        player = self._stats:Get(),
        autoFarm = self._autoFarm:GetStatus(),
        autoCollect = self._autoCollect:GetStatus(),
        autoQuest = self._autoQuest:GetStatus(),
        travel = self._fastTravel:GetStatus(),
        input = { method = self._input:Method() },
    }
end

return World
end

__BFS_MODULES["world.input"] = function(require)
--[[
    world/input.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Simulated input.

    Attacking and interacting need a left mouse click. Executors expose
    that in different ways, so this module tries them in order of
    reliability and reports which one worked. When none is available the
    automation modules say so instead of silently doing nothing.
]]

local Input = {}

Input.__index = Input

local function tryGlobal(name, ...)
    local fn = _G[name]
    if type(fn) ~= "function" then
        return false
    end
    local ok = pcall(fn, ...)
    return ok
end

function Input.new(options)
    options = options or {}

    return setmetatable({
        _logger = options.logger,
        _method = nil,
        _lastClick = 0,
        _clickCooldown = options.clickCooldown or 0.12,
    }, Input)
end

--- Work out which click mechanism is available. Returns a label or nil.
function Input:Detect()
    if self._method then
        return self._method
    end

    if type(_G.keypress) == "function" or type(_G.syn) == "table" and type(_G.syn.keypress) == "function" then
        self._method = "keypress"
        return self._method
    end

    if type(_G.fireproximityprompt) == "function" then
        self._method = "fireproximityprompt"
        return self._method
    end

    if type(_G.VirtualInputManager) == "table" or tryGlobal("getexecutorname") then
        -- executors with a virtual input manager
        local ok, manager = pcall(function()
            return game:GetService("VirtualInputManager")
        end)
        if ok and manager then
            self._method = "virtualinput"
            return self._method
        end
    end

    self._method = "tool"
    return self._method
end

--- Fire a left mouse click.
--- Returns true when a click was actually delivered.
function Input:Click()
    local now = os.clock()
    if now - self._lastClick < self._clickCooldown then
        return false
    end
    self._lastClick = now

    local method = self:Detect()

    if method == "keypress" then
        if tryGlobal("keypress", Enum.KeyCode.MouseButton1) then
            return true
        end
        if type(_G.syn) == "table" and type(_G.syn.keypress) == "function" then
            local ok = pcall(_G.syn.keypress, Enum.KeyCode.MouseButton1)
            return ok
        end
    elseif method == "virtualinput" then
        local ok, manager = pcall(function()
            return game:GetService("VirtualInputManager")
        end)
        if ok and manager then
            local sent = pcall(function()
                manager:SendKeyEvent(true, Enum.KeyCode.MouseButton1, 0, false, false, false)
                task.wait(0.03)
                manager:SendKeyEvent(false, Enum.KeyCode.MouseButton1, 0, false, false, false)
            end)
            if sent then
                return true
            end
        end
    end

    -- fallback: activate the equipped tool
    local ok, player = pcall(function()
        return game:GetService("Players").LocalPlayer
    end)
    if ok and player then
        local okChar, character = pcall(function()
            return player.Character
        end)
        if okChar and character then
            local okTool, tool = pcall(function()
                return character:FindFirstChildOfClass("Tool")
            end)
            if okTool and tool then
                local activated = pcall(function()
                    tool:Activate()
                end)
                if activated then
                    return true
                end
            end
        end
    end

    return false
end

--- Press the "E" key (used for interactions and fruit picking up).
function Input:PressE()
    if type(_G.keypress) == "function" then
        return tryGlobal("keypress", Enum.KeyCode.E)
    end
    if type(_G.syn) == "table" and type(_G.syn.keypress) == "function" then
        return pcall(_G.syn.keypress, Enum.KeyCode.E)
    end
    return false
end

--- Trigger a proximity prompt if the executor supports it.
function Input:FireProximityPrompt(prompt)
    if type(_G.fireproximityprompt) == "function" and prompt then
        return tryGlobal("fireproximityprompt", prompt)
    end
    return false
end

function Input:Method()
    return self._method or "unknown"
end

return Input
end

__BFS_MODULES["world.movement"] = function(require)
--[[
    world/movement.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Character and movement helpers.

    The suite moves the player by writing to the HumanoidRootPart's
    CFrame. That is the same technique every Blox Fruits utility uses, and
    it is the only client-side approach that works without the server
    agreeing to move the character.
]]

local Util = require("core.util")

local Movement = {}

function Movement.GetPlayer()
    local ok, Players = pcall(function()
        return game:GetService("Players")
    end)
    if not ok then
        return nil
    end
    local okPlayer, player = pcall(function()
        return Players.LocalPlayer
    end)
    if okPlayer then
        return player
    end
    return nil
end

function Movement.GetCharacter()
    local player = Movement.GetPlayer()
    if not player then
        return nil
    end
    local ok, character = pcall(function()
        return player.Character
    end)
    if ok then
        return character
    end
    return nil
end

function Movement.GetRoot(character)
    character = character or Movement.GetCharacter()
    if not Util.isInstance(character) then
        return nil
    end
    local ok, root = pcall(function()
        return character:FindFirstChild("HumanoidRootPart")
    end)
    if ok then
        return root
    end
    return nil
end

function Movement.GetHumanoid(character)
    character = character or Movement.GetCharacter()
    if not Util.isInstance(character) then
        return nil
    end
    local ok, humanoid = pcall(function()
        return character:FindFirstChildOfClass("Humanoid")
    end)
    if ok then
        return humanoid
    end
    return nil
end

--- True when the character exists and is alive.
function Movement.IsAlive()
    local humanoid = Movement.GetHumanoid()
    if not humanoid then
        return false
    end
    local ok, health = pcall(function()
        return humanoid.Health
    end)
    return ok and health > 0
end

function Movement.GetHealth()
    local humanoid = Movement.GetHumanoid()
    if not humanoid then
        return 0
    end
    local ok, health = pcall(function()
        return humanoid.Health
    end)
    if ok then
        return health
    end
    return 0
end

function Movement.GetMaxHealth()
    local humanoid = Movement.GetHumanoid()
    if not humanoid then
        return 0
    end
    local ok, maxHealth = pcall(function()
        return humanoid.MaxHealth
    end)
    if ok then
        return maxHealth
    end
    return 0
end

function Movement.GetHealthPercent()
    local maxHealth = Movement.GetMaxHealth()
    if maxHealth <= 0 then
        return 0
    end
    return (Movement.GetHealth() / maxHealth) * 100
end

--- Place the character at a world position, keeping the current facing.
function Movement.TeleportTo(position, lookAt)
    local root = Movement.GetRoot()
    if not root or type(position) ~= "Vector3" then
        return false
    end

    local target = CFrame.new(position)
    if lookAt then
        target = CFrame.lookAt(position, lookAt)
    end

    local ok = pcall(function()
        root.CFrame = target
    end)
    return ok
end

--- Place the character a given distance away from a target, looking at it.
function Movement.TeleportNear(targetPosition, distance)
    if type(targetPosition) ~= "Vector3" then
        return false
    end

    local root = Movement.GetRoot()
    if not root then
        return false
    end

    local origin = root.Position
    local offset = targetPosition - origin
    if offset.Magnitude < 0.001 then
        offset = Vector3.new(0, 0, 1)
    end
    offset = offset.Unit * (distance or 8)

    local destination = targetPosition - offset
    local ok = pcall(function()
        root.CFrame = CFrame.lookAt(destination, targetPosition)
    end)
    return ok
end

--- Step the character towards a target by a distance in studs.
function Movement.MoveTowards(targetPosition, step)
    local root = Movement.GetRoot()
    if not root or type(targetPosition) ~= "Vector3" then
        return false
    end

    local origin = root.Position
    local delta = targetPosition - origin
    local distance = delta.Magnitude

    if distance < 0.5 then
        return false
    end

    local moved = delta.Unit * math.min(step or 5, distance)
    local ok = pcall(function()
        root.CFrame = CFrame.new(origin + moved) * root.CFrame.Rotation
    end)
    return ok
end

--- Face a target without moving.
function Movement.LookAt(targetPosition)
    local root = Movement.GetRoot()
    if not root or type(targetPosition) ~= "Vector3" then
        return false
    end
    local ok = pcall(function()
        root.CFrame = CFrame.lookAt(root.Position, targetPosition)
    end)
    return ok
end

return Movement
end

__BFS_MODULES["world.player_stats"] = function(require)
--[[
    world/player_stats.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    Reads the player's live statistics.

    Blox Fruits keeps the HUD values in IntValue / NumberValue instances
    inside the local player's PlayerGui. The names have changed over time
    ("Level", "XP", "Beli", "Bounty", "Honor", "Mastery"), so every value
    is looked up through a list of candidates.

    This is what the dashboard shows, and the auto-farm module uses the
    level to pick a sensible target.
]]

local Util = require("core.util")

local PlayerStats = {}

PlayerStats.__index = PlayerStats

PlayerStats.CANDIDATES = {
    level = { "Level", "PlayerLevel", "LevelValue" },
    xp = { "XP", "Experience", "Exp" },
    beli = { "Beli", "Money", "Cash" },
    bounty = { "Bounty", "BountyValue" },
    honor = { "Honor", "HonorValue" },
    mastery = { "Mastery", "FruitMastery" },
    fruit = { "CurrentFruit", "FruitName", "EquippedFruit" },
}

function PlayerStats.new(options)
    options = options or {}

    return setmetatable({
        _logger = options.logger,
        _cache = {},
        _cacheTime = 0,
        _cacheLifetime = 0.5,
    }, PlayerStats)
end

function PlayerStats:_playerGui()
    local ok, Players = pcall(function()
        return game:GetService("Players")
    end)
    if not ok then
        return nil
    end
    local okPlayer, player = pcall(function()
        return Players.LocalPlayer
    end)
    if not okPlayer or not player then
        return nil
    end
    local okGui, playerGui = pcall(function()
        return player:FindFirstChildOfClass("PlayerGui")
    end)
    if okGui then
        return playerGui
    end
    return nil
end

--- Look up a numeric HUD value.
function PlayerStats:_readNumeric(candidates)
    local playerGui = self:_playerGui()
    if not playerGui then
        return nil
    end

    for _, candidate in ipairs(candidates) do
        local ok, value = pcall(function()
            local found = playerGui:FindFirstChild(candidate, true)
            if not found then
                return nil
            end
            if found:IsA("IntValue") or found:IsA("NumberValue") or found:IsA("StringValue") then
                local raw = found.Value
                if type(raw) == "string" then
                    return tonumber(raw)
                end
                return raw
            end
            return nil
        end)
        if ok and type(value) == "number" then
            return value
        end
    end

    return nil
end

--- Look up a string HUD value.
function PlayerStats:_readString(candidates)
    local playerGui = self:_playerGui()
    if not playerGui then
        return nil
    end

    for _, candidate in ipairs(candidates) do
        local ok, value = pcall(function()
            local found = playerGui:FindFirstChild(candidate, true)
            if not found then
                return nil
            end
            if found:IsA("StringValue") or found:IsA("TextLabel") or found:IsA("TextButton") then
                return found.Value or found.Text
            end
            return nil
        end)
        if ok and type(value) == "string" and value ~= "" then
            return value
        end
    end

    return nil
end

--- Read every statistic. Results are cached briefly so the UI can poll
--- this without hammering the PlayerGui.
function PlayerStats:Get()
    local now = os.clock()
    if now - self._cacheTime < self._cacheLifetime then
        return self._cache
    end
    self._cacheTime = now

    local stats = {
        level = self:_readNumeric(PlayerStats.CANDIDATES.level) or 0,
        xp = self:_readNumeric(PlayerStats.CANDIDATES.xp) or 0,
        beli = self:_readNumeric(PlayerStats.CANDIDATES.beli) or 0,
        bounty = self:_readNumeric(PlayerStats.CANDIDATES.bounty) or 0,
        honor = self:_readNumeric(PlayerStats.CANDIDATES.honor) or 0,
        mastery = self:_readNumeric(PlayerStats.CANDIDATES.mastery) or 0,
        fruit = self:_readString(PlayerStats.CANDIDATES.fruit) or "None",
    }

    self._cache = stats
    return stats
end

--- Current level only -- used by the auto-farm target picker.
function PlayerStats:GetLevel()
    return self:Get().level
end

function PlayerStats:Invalidate()
    self._cacheTime = 0
end

return PlayerStats
end

__BFS_MODULES["world.scanner"] = function(require)
--[[
    world/scanner.lua
    BLOX FRUITS SUITE v12.0
    ---------------------------------------------------------------------------
    One pass over the workspace, classified into buckets.

    The scan is the expensive part (a Blox Fruits workspace holds tens of
    thousands of descendants), so the scanner runs on an interval rather
    than every frame, keeps a registry of the instances it has seen, and
    exposes the buckets as plain arrays.
]]

local Entity = require("world.entity")
local Util = require("core.util")

local Scanner = {}

Scanner.__index = Scanner

function Scanner.new(options)
    options = options or {}

    return setmetatable({
        _logger = options.logger,
        _scanInterval = options.scanInterval or 2.0,
        _buckets = {
            fruit = {},
            mob = {},
            boss = {},
            chest = {},
            npc = {},
        },
        _registry = {},
        _scanCount = 0,
        _lastScan = 0,
        _lastDuration = 0,
        _maxRegistry = 4000,
    }, Scanner)
end

function Scanner:_workspace()
    local ok, workspace = pcall(function()
        return game:GetService("Workspace")
    end)
    if ok then
        return workspace
    end
    return nil
end

--- Run a scan. Returns the buckets.
function Scanner:Scan()
    local workspace = self:_workspace()
    if not workspace then
        return self._buckets
    end

    local startTime = os.clock()

    local buckets = {
        fruit = {},
        mob = {},
        boss = {},
        chest = {},
        npc = {},
    }

    local registry = {}
    local classifier = Entity

    for _, descendant in ipairs(workspace:GetDescendants()) do
        if Util.isInstance(descendant) then
            local className = Util.getClass(descendant)
            -- skip the parts that make up a character, they are not targets
            if className ~= "Accessory" and className ~= "BodyPart" then
                local entity = classifier:Classify(descendant)
                if entity then
                    local bucket = buckets[entity.kind]
                    if bucket then
                        entity.instance = descendant
                        entity.position = descendant.Position
                        bucket[#bucket + 1] = entity
                    end
                end
            end
        end
    end

    self._buckets = buckets
    self._registry = registry
    self._scanCount = self._scanCount + 1
    self._lastScan = os.clock()
    self._lastDuration = self._lastScan - startTime

    if self._logger then
        self._logger:debug("Scan finished in %.1f ms (%d fruits, %d mobs, %d chests, %d npcs)",
            self._lastDuration * 1000,
            #buckets.fruit, #buckets.mob, #buckets.chest, #buckets.npc)
    end

    return buckets
end

function Scanner:Buckets()
    return self._buckets
end

function Scanner:Fruits()
    return self._buckets.fruit
end

function Scanner:Mobs()
    return self._buckets.mob
end

function Scanner:Bosses()
    return self._buckets.boss
end

function Scanner:Chests()
    return self._buckets.chest
end

function Scanner:NPCs()
    return self._buckets.npc
end

function Scanner:ScanCount()
    return self._scanCount
end

function Scanner:LastDuration()
    return self._lastDuration
end

--- Distance of every entity in a bucket from the local player, sorted
--- from nearest to furthest.
function Scanner:SortedByDistance(bucketName, playerRoot)
    local list = self._buckets[bucketName]
    if not list then
        return {}
    end

    local origin = playerRoot and playerRoot.Position or Vector3.new(0, 0, 0)

    local copy = {}
    for index = 1, #list do
        copy[index] = list[index]
    end

    table.sort(copy, function(a, b)
        local da = (a.position - origin).Magnitude
        local db = (b.position - origin).Magnitude
        return da < db
    end)

    return copy
end

return Scanner
end

-- ── expose the resolver and start the suite ──────────────────
_G.BFS_MODULE_RESOLVER = __bfs_require

local suite = __bfs_require("main")
return suite
